def _load_app_settings():

    global _APP_SETTINGS
    try:
        with open(APP_SETTINGS_FILE, "r", encoding="utf-8") as f:
            _APP_SETTINGS = json.load(f) or {}
    except FileNotFoundError:
        _APP_SETTINGS = {}
    except Exception as e:
        print(f"⚠️ خطأ بقراءة {APP_SETTINGS_FILE}: {e}")
        _APP_SETTINGS = {}
    return _APP_SETTINGS

def _save_app_settings():

    tmp = APP_SETTINGS_FILE + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(_APP_SETTINGS, f, ensure_ascii=False, indent=2)
        os.replace(tmp, APP_SETTINGS_FILE)
        return True
    except Exception as e:
        print(f"❌ فشل حفظ {APP_SETTINGS_FILE}: {e}")
        try: os.remove(tmp)
        except: pass
        return False

def _setting(key, default):

    v = _APP_SETTINGS.get(key)
    return v if v not in (None, "") else default

