def _smtp_send(to_email, msg):

    import smtplib

    host = _setting("smtp_host", SMTP_HOST)
    try: port = int(_setting("smtp_port", SMTP_PORT))
    except (ValueError, TypeError): port = SMTP_PORT
    user = _setting("smtp_user", SMTP_USER)
    pw   = _setting("smtp_pass", SMTP_PASS)
    try:
        if port == 465:
            server = smtplib.SMTP_SSL(host, port, timeout=15)
        else:
            server = smtplib.SMTP(host, port, timeout=15)
            server.ehlo(); server.starttls(); server.ehlo()
        server.login(user, pw)

        msg_str = msg.as_string()
        try:
            nm = _site_name()
            if nm != "Beinty":
                msg_str = msg_str.replace("Beinty", nm)
        except: pass
        server.sendmail(user, to_email, msg_str)
        server.quit()
        return True
    except Exception as e:
        print(f"❌ SMTP error: {e}")
        return False

