@app.after_request
def _apply_site_name(response):

    try:
        response.headers['X-Build'] = _BUILD_ID
    except: pass
    try:

        if response.headers.get('Content-Encoding') == 'gzip':
            return response

        # PERF FIX #4 — هذا الهوك كان يفكّ ويفحص ويعيد بناء جسم *كل* رد نصي.
        # على ردود كبيرة (خدمات/صور base64) هذا يعني نسخ عدة ميغابايت لكل طلب.
        # الآن: نتخطّى الردود المتدفقة (send_file) والردود الكبيرة و304،
        # لأن كل صفحات HTML أصلاً ينطبق عليها الاسم وقت التوليد.
        if getattr(response, 'direct_passthrough', False):
            return response
        if response.status_code in (204, 304):
            return response
        if (response.content_length or 0) > 262144:
            return response

        nm = _site_name()
        if nm == "Beinty":
            return response
        ct = (response.headers.get('Content-Type') or '').lower()

        if any(x in ct for x in ('text/html','javascript','json','text/plain','xml','manifest')):

            data = response.get_data()
            if data:
                try:
                    body = data.decode('utf-8')

                    body = body.replace("Beinty", nm)

                    if len(nm) >= 3:
                        first_part = nm[:-2]
                        last_part = nm[-2:]
                        def _split_logo_replacer(m):
                            tag = m.group(1)
                            attrs = m.group(2) or ""
                            return f'{first_part}<{tag}{attrs}>{last_part}</{tag}>'
                        body = _re_split_logo.sub(_split_logo_replacer, body)
                    response.set_data(body.encode('utf-8'))
                except:
                    pass
    except:
        pass
    return response

import re as _re
_re_split_logo = _re.compile(r'Bein<(\w+)([^>]*)>\s*ty\s*</\1>')

def _apply_site_name_to_html(html):

    try:
        nm = _site_name()

        try:
            import re as _re2
            old_footer_pattern = _re2.compile(
                r'<div[^>]*>\s*<a[^>]*kony\.store[^>]*>[^<]*</a>\s*&middot;\s*<a[^>]*t\.me/srrrs[^>]*>[^<]*</a>\s*&middot;\s*<a[^>]*t\.me/tnxbot[^>]*>[^<]*</a>\s*</div>\s*<div[^>]*>&#169;[^<]*</div>',
                _re2.IGNORECASE
            )
            html = old_footer_pattern.sub(_email_footer_html(), html)
            html = _re2.sub(r'<a[^>]*href=["\']https?://kony\.store[^"\']*["\'][^>]*>[^<]*</a>', '', html, flags=_re2.IGNORECASE)
            html = _re2.sub(r'<a[^>]*href=["\']https?://t\.me/(srrrs|tnxbot)["\'][^>]*>[^<]*</a>', '', html, flags=_re2.IGNORECASE)
            html = html.replace('kony.store', '').replace('t.me/srrrs', '').replace('t.me/tnxbot', '')
        except:
            pass

        if nm == "Beinty":
            return html

        html = html.replace("Beinty", nm)

        if len(nm) >= 3:
            first_part = nm[:-2]
            last_part = nm[-2:]
            def _r(m):
                tag = m.group(1)
                attrs = m.group(2) or ""
                return f'{first_part}<{tag}{attrs}>{last_part}</{tag}>'
            html = _re_split_logo.sub(_r, html)

        return html
    except:
        return html

