def _email_footer_html():
    """يبني footer الإيميل ديناميكياً من إعدادات الأدمن. لو ما عنده إعدادات معبية،
       يظهر بس اسم الموقع + السنة بدون أي روابط للموقع القديم."""
    try:
        nm = _site_name()
        cl = getattr(db, 'contact_links', {}) or {}
        items = []
        tg = (cl.get('telegram') or '').strip()
        wa = (cl.get('whatsapp') or '').strip()
        em = (cl.get('email') or '').strip()
        ig = (cl.get('instagram') or '').strip()
        tw = (cl.get('twitter') or '').strip()
        if tg:
            items.append(f'<a href="{tg}" style="color:#2563eb;text-decoration:none">الدعم الفني</a>')
        if wa:
            wa_url = wa if wa.startswith('http') else f'https://wa.me/{wa.lstrip("+")}'
            items.append(f'<a href="{wa_url}" style="color:#2563eb;text-decoration:none">واتساب</a>')
        if ig:
            ig_url = ig if ig.startswith('http') else f'https://instagram.com/{ig.lstrip("@")}'
            items.append(f'<a href="{ig_url}" style="color:#2563eb;text-decoration:none">إنستقرام</a>')
        if tw:
            tw_url = tw if tw.startswith('http') else f'https://twitter.com/{tw.lstrip("@")}'
            items.append(f'<a href="{tw_url}" style="color:#2563eb;text-decoration:none">تويتر</a>')
        links_html = ''
        if items:
            sep = ' &middot; '
            links_html = f'<div style="font-size:9px;color:#86868b;line-height:2">{sep.join(items)}</div>'
        year = time.strftime("%Y")
        return (
            f'{links_html}'
            f'<div style="font-size:8px;color:#c7c7cc;margin-top:8px">&#169; {year} {nm}. جميع الحقوق محفوظة.</div>'
        )
    except:
        return f'<div style="font-size:8px;color:#c7c7cc">&#169; {time.strftime("%Y")} {_site_name()}</div>'

