def _apply_contact_links_to_html(html):

    try:
        cl = getattr(db, 'contact_links', {}) or {}
        def _v(k): return (cl.get(k) or "").strip()
        tg, wa, em, ig, tw = _v("telegram"), _v("whatsapp"), _v("email"), _v("instagram"), _v("twitter")

        em_url = ("mailto:" + em) if em else "#"

        repl = {
            "__CT_TG_URL__": tg or "#",
            "__CT_WA_URL__": wa or "#",
            "__CT_EM_URL__": em_url,
            "__CT_IG_URL__": ig or "#",
            "__CT_TW_URL__": tw or "#",
            "__CT_TG_HIDE__": "" if tg else "display:none",
            "__CT_WA_HIDE__": "" if wa else "display:none",
            "__CT_EM_HIDE__": "" if em else "display:none",
            "__CT_IG_HIDE__": "" if ig else "display:none",
            "__CT_TW_HIDE__": "" if tw else "display:none",
        }
        for k, v in repl.items():
            html = html.replace(k, v)
        return html
    except:
        return html

