BACKUP_INTERVAL = 3600
MAX_BACKUPS = 48

def ensure_backup_dir():
    os.makedirs(BACKUP_DIR, exist_ok=True)

def create_backup(label="auto"):

    ensure_backup_dir()
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_name = f"backup_{label}_{ts}"
    backup_folder = os.path.join(BACKUP_DIR, backup_name)
    os.makedirs(backup_folder, exist_ok=True)
    copied = 0
    try:

        files_to_backup = [
            DATA_FILE,
            "web_users.json",
            "audit_log.json",
        ]
        for f in files_to_backup:
            if os.path.exists(f):
                shutil.copy2(f, os.path.join(backup_folder, os.path.basename(f)))
                copied += 1

        all_backups = sorted([d for d in os.listdir(BACKUP_DIR) if d.startswith("backup_") and os.path.isdir(os.path.join(BACKUP_DIR, d))])
        while len(all_backups) > MAX_BACKUPS:
            old = all_backups.pop(0)
            old_path = os.path.join(BACKUP_DIR, old)
            shutil.rmtree(old_path, ignore_errors=True)

        old_json = sorted(glob.glob(os.path.join(BACKUP_DIR, "backup_*.json")))
        for oj in old_json:
            try: os.remove(oj)
            except: pass
        return backup_name if copied > 0 else None
    except Exception as e:
        print(f"Backup error: {e}")
    return None

def list_backups():

    ensure_backup_dir()
    backups = []

    for d in sorted(os.listdir(BACKUP_DIR), reverse=True):
        dpath = os.path.join(BACKUP_DIR, d)
        if d.startswith("backup_") and os.path.isdir(dpath):
            files = os.listdir(dpath)
            total_size = sum(os.path.getsize(os.path.join(dpath, f)) for f in files)
            mtime = os.path.getmtime(dpath)
            backups.append({
                "name": d,
                "size": round(total_size / 1024, 1),
                "date": datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M:%S"),
                "timestamp": mtime,
                "files": files
            })

    for f in sorted(glob.glob(os.path.join(BACKUP_DIR, "backup_*.json")), reverse=True):
        fname = os.path.basename(f)
        size = os.path.getsize(f)
        mtime = os.path.getmtime(f)
        backups.append({
            "name": fname,
            "size": round(size / 1024, 1),
            "date": datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M:%S"),
            "timestamp": mtime,
            "files": [fname]
        })
    backups.sort(key=lambda x: x["timestamp"], reverse=True)
    return backups

def restore_backup(backup_name):

    backup_path = os.path.join(BACKUP_DIR, backup_name)
    try:
        if os.path.isdir(backup_path):

            bak_wu = os.path.join(backup_path, "web_users.json")
            if os.path.exists(bak_wu):
                try:
                    with open(bak_wu, "r", encoding="utf-8") as f:
                        bak_users = json.load(f)
                    current_users = _load_web_users()
                    if isinstance(current_users, dict) and len(current_users) > 10 and isinstance(bak_users, dict) and len(bak_users) < len(current_users) * 0.3:
                        print(f"🛑 رفض استعادة: النسخة فيها {len(bak_users)} مستخدم بس الحالي {len(current_users)}")
                        return False
                except: pass

            create_backup("pre_restore")
            for f in os.listdir(backup_path):
                src = os.path.join(backup_path, f)
                shutil.copy2(src, f)
            return True
        elif os.path.isfile(backup_path):
            create_backup("pre_restore")
            shutil.copy2(backup_path, DATA_FILE)
            return True
    except Exception as e:
        print(f"Restore error: {e}")
    return False

WATCHDOG_INTERVAL = 300
HEALTH_FILE = "health_snapshot.json"

def _save_health_snapshot():

    try:
        snap = {
            "ts": time.time(),
            "date": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "balances_count": len(db.balances),
            "orders_count": db.total_orders(),
            "subscribers_count": len(db.subscribers),
            "data_file_size": os.path.getsize(DATA_FILE) if os.path.exists(DATA_FILE) else 0,
        }

        try:
            if os.path.exists(WEB_USERS_FILE):
                with open(WEB_USERS_FILE, "r", encoding="utf-8") as f:
                    wu = json.load(f)
                snap["web_users_count"] = len(wu) if isinstance(wu, dict) else 0
                snap["web_users_file_size"] = os.path.getsize(WEB_USERS_FILE)
        except:
            pass
        with open(HEALTH_FILE, "w", encoding="utf-8") as f:
            json.dump(snap, f, ensure_ascii=False)
    except:
        pass

def _load_health_snapshot():

    try:
        if os.path.exists(HEALTH_FILE):
            with open(HEALTH_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except:
        pass
    return None

def _find_best_backup():

    ensure_backup_dir()
    snap = _load_health_snapshot()
    min_users = max(1, int(snap.get("balances_count", 1) * 0.5)) if snap else 1

    all_dirs = sorted(
        [d for d in os.listdir(BACKUP_DIR)
         if d.startswith("backup_") and os.path.isdir(os.path.join(BACKUP_DIR, d))],
        reverse=True
    )
    for d in all_dirs:
        dpath = os.path.join(BACKUP_DIR, d)
        data_f = os.path.join(dpath, os.path.basename(DATA_FILE))
        if not os.path.exists(data_f):
            continue
        try:
            with open(data_f, "r", encoding="utf-8") as f:
                bak_data = json.load(f)
            bak_users = len(bak_data.get("balances", {}))
            if bak_users >= min_users:
                return d, bak_data, bak_users
        except:
            continue
    return None, None, 0

def _watchdog_check():

    problems = []
    snap = _load_health_snapshot()

    if not os.path.exists(DATA_FILE):
        problems.append("📁 ملف البيانات مفقود!")
    else:
        try:
            with open(DATA_FILE, "r", encoding="utf-8") as f:
                d = json.load(f)
            current_balances = len(d.get("balances", {}))
            current_orders = sum(len(v) for v in d.get("orders", {}).values())

            if snap:
                old_bal = snap.get("balances_count", 0)
                old_ord = snap.get("orders_count", 0)

                if old_bal > 10 and current_balances < old_bal * 0.3:
                    problems.append(f"📉 الأرصدة نقصت بشكل كبير: {old_bal} → {current_balances}")

                if old_ord > 20 and current_orders == 0:
                    problems.append(f"📉 كل الطلبات راحت! كان {old_ord}")
            elif current_balances == 0 and os.path.getsize(DATA_FILE) < 100:
                problems.append("📁 ملف البيانات فارغ!")
        except json.JSONDecodeError:
            problems.append("💥 ملف البيانات تالف (JSON غير صالح)!")
        except Exception as e:
            problems.append(f"⚠️ خطأ بقراءة البيانات: {e}")

    if not os.path.exists(WEB_USERS_FILE):
        problems.append("📁 ملف المستخدمين مفقود!")
    else:
        try:
            with open(WEB_USERS_FILE, "r", encoding="utf-8") as f:
                wu = json.load(f)
            if snap:
                old_wu = snap.get("web_users_count", 0)
                if old_wu > 10 and len(wu) < old_wu * 0.3:
                    problems.append(f"📉 المستخدمين نقصوا: {old_wu} → {len(wu)}")
        except json.JSONDecodeError:
            problems.append("💥 ملف المستخدمين تالف!")
        except:
            pass

    return problems

def _watchdog_auto_restore(problems):

    backup_name, bak_data, bak_users = _find_best_backup()
    if not backup_name:
        msg = "🚨 <b>تنبيه الحارس</b>\n\n" + "\n".join(problems) + "\n\n❌ ما لگيت نسخة احتياطية للاسترجاع!"
        try:
            bot.send_message(ADMIN_ID, msg, parse_mode="HTML")
        except: pass
        print("❌ Watchdog: لا توجد نسخة احتياطية للاسترجاع")
        return False

    try:
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        corrupt_dir = os.path.join(BACKUP_DIR, f"backup_corrupted_{ts}")
        os.makedirs(corrupt_dir, exist_ok=True)
        for f in [DATA_FILE, WEB_USERS_FILE]:
            if os.path.exists(f):
                shutil.copy2(f, os.path.join(corrupt_dir, os.path.basename(f)))
    except: pass

    ok = restore_backup(backup_name)
    if ok:

        try:
            db._load()
        except: pass
        msg = (
            f"🛡️ <b>الحارس استعاد البيانات تلقائياً</b>\n\n"
            f"🔍 المشاكل:\n" + "\n".join(problems) + "\n\n"
            f"✅ تم الاسترجاع من: {backup_name}\n"
            f"👥 {bak_users} مستخدم بالنسخة المسترجعة"
        )
    else:
        msg = (
            f"🚨 <b>تنبيه الحارس — فشل الاسترجاع!</b>\n\n"
            f"🔍 المشاكل:\n" + "\n".join(problems) + "\n\n"
            f"❌ فشل الاسترجاع من {backup_name}"
        )
    try:
        bot.send_message(ADMIN_ID, msg, parse_mode="HTML")
    except: pass
    print(f"🛡️ Watchdog: {'نجح' if ok else 'فشل'} الاسترجاع من {backup_name}")
    return ok

def watchdog_thread():

    time.sleep(60)

    try:
        _save_health_snapshot()
    except: pass
    while True:
        time.sleep(WATCHDOG_INTERVAL)
        try:
            problems = _watchdog_check()
            if problems:
                print(f"🛡️ Watchdog اكتشف مشاكل: {problems}")
                _watchdog_auto_restore(problems)
            else:

                _save_health_snapshot()
        except Exception as e:
            print(f"⚠️ Watchdog error: {e}")

def auto_cleanup_recharges():

    try:
        now = time.time()
        two_days = 2 * 24 * 3600
        to_delete = []
        for ref, req in db.recharge_requests.items():
            if req.get("status") in ("done", "rejected"):
                try:
                    req_time = datetime.strptime(req.get("date", ""), "%Y-%m-%d %H:%M:%S").timestamp()
                    if now - req_time > two_days:
                        to_delete.append(ref)
                except:
                    pass
        if to_delete:
            for ref in to_delete:

                receipt = db.recharge_requests[ref].get("receipt_file", "")
                if receipt:
                    try: os.remove(os.path.join("receipts", receipt))
                    except: pass
                del db.recharge_requests[ref]
            db.save()
            print(f"🧹 تنظيف: حذف {len(to_delete)} طلب شحن قديم")
    except Exception as e:
        print(f"Cleanup error: {e}")

def auto_backup_thread():

    while True:
        time.sleep(BACKUP_INTERVAL)
        try:
            create_backup("auto")
            auto_cleanup_recharges()
        except:
            pass

