import zipfile

TELEGRAM_BACKUP_INTERVAL = 6 * 3600
TELEGRAM_BACKUP_FILES = [DATA_FILE, WEB_USERS_FILE, "audit_log.json", HEALTH_FILE]

def _create_telegram_backup():
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    zip_name = f"beinty_cloud_backup_{ts}.zip"
    zip_path = os.path.join(BACKUP_DIR, zip_name)
    report_lines = []; total_size = 0; files_added = 0
    try:
        with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            for fpath in TELEGRAM_BACKUP_FILES:
                if os.path.exists(fpath):
                    fsize = os.path.getsize(fpath); total_size += fsize
                    zf.write(fpath, os.path.basename(fpath)); files_added += 1
                    report_lines.append(f"  📄 {os.path.basename(fpath)} — {round(fsize/1024,1)} KB")
        if files_added == 0:
            try: os.remove(zip_path)
            except: pass
            return False
        zip_size = os.path.getsize(zip_path)
        user_count = 0; order_count = 0; balance_total = 0.0
        try: wu = _load_web_users(); user_count = len(wu) if isinstance(wu, dict) else 0
        except: pass
        try: order_count = db.total_orders(); balance_total = round(sum(db.balances.values()), 2)
        except: pass
        report = (f"☁️ <b>نسخة احتياطية سحابية — Beinty</b>\n━━━━━━━━━━━━━━━━━━━━\n"
            f"🕐 {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
            f"📊 <b>إحصائيات:</b>\n  👥 المستخدمين: <b>{user_count}</b>\n"
            f"  📦 الطلبات: <b>{order_count}</b>\n  💰 مجموع الأرصدة: <b>${balance_total}</b>\n\n"
            f"📁 <b>الملفات ({files_added}):</b>\n" + "\n".join(report_lines) + "\n\n"
            f"📦 حجم الـ ZIP: <b>{round(zip_size/1024,1)} KB</b>\n━━━━━━━━━━━━━━━━━━━━\n"
            f"✅ لاسترجاع: نزّل الملف → فك الضغط → ارفع الملفات للسيرفر")
        with open(zip_path, 'rb') as zf:
            bot.send_document(ADMIN_ID, zf, caption=report, parse_mode="HTML", visible_file_name=zip_name)
        print(f"☁️ Telegram Backup: تم إرسال {zip_name} ({round(zip_size/1024,1)} KB)")
        try: os.remove(zip_path)
        except: pass
        return True
    except Exception as e:
        print(f"❌ Telegram Backup error: {e}")
        try: bot.send_message(ADMIN_ID, f"❌ <b>فشل النسخ الاحتياطي السحابي!</b>\n\n⚠️ <code>{str(e)[:200]}</code>", parse_mode="HTML")
        except: pass
        try: os.remove(zip_path)
        except: pass
        return False

def _telegram_backup_thread():
    time.sleep(120)
    try: _create_telegram_backup()
    except: pass
    while True:
        time.sleep(TELEGRAM_BACKUP_INTERVAL)
        try: _create_telegram_backup()
        except: pass

