_provider_balance_cache = {"balance": None, "ts": 0, "notified": False}
PROVIDER_BALANCE_WARN = 5.0
PROVIDER_CHECK_INTERVAL = 60

def _get_default_provider():
    """يرجع (url, api_key, name) من أول مزود enabled في db.providers — أو الـ defaults لو ما في مزود مضبوط."""
    try:
        provs = getattr(db, 'providers', None) if 'db' in globals() else None
        if provs and isinstance(provs, dict):
            for pid, p in provs.items():
                if not isinstance(p, dict): continue
                if not p.get("enabled", True): continue
                url = (p.get("url") or "").strip()
                key = (p.get("api_key") or "").strip()
                if url and key:
                    return (url, key, p.get("name") or pid)
    except Exception:
        pass
    return (API_URL, API_KEY, "default")

def _fetch_provider_balance():

    url, key, name = _get_default_provider()
    try:

        try:
            r = requests.post(url, data={"key": key, "action": "balance"}, timeout=15)
        except:
            r = requests.get(url, params={"key": key, "action": "balance"}, timeout=15)
        d = r.json()

        bal_raw = d.get("balance") or d.get("Balance") or d.get("data",{}).get("balance") if isinstance(d,dict) else None
        if bal_raw is None and isinstance(d, (int, float)):
            bal_raw = d
        bal = float(bal_raw) if bal_raw is not None else None
        if bal is not None:
            _provider_balance_cache["balance"] = bal
            _provider_balance_cache["ts"] = time.time()
            _provider_balance_cache["raw"] = str(d)[:200]
            _provider_balance_cache["error"] = None
            _provider_balance_cache["provider"] = name
        else:
            _provider_balance_cache["error"] = f"no balance in response from {name}: {str(d)[:200]}"
        return bal
    except Exception as e:
        _provider_balance_cache["error"] = f"{name}: {str(e)[:200]}"
        logging.warning(f"[ProviderBalance] fetch error from {name}: {e}")
        return _provider_balance_cache.get("balance")

def _provider_balance_monitor():

    time.sleep(10)
    while True:
        try:
            bal = _fetch_provider_balance()
            if bal is not None and bal < PROVIDER_BALANCE_WARN:
                if not _provider_balance_cache.get("notified"):
                    try:
                        bot.send_message(ADMIN_ID,
                            f"⚠️ <b>تنبيه رصيد API المزود!</b>\n\n"
                            f"💰 الرصيد الحالي: <b>${bal:.2f}</b>\n"
                            f"🔻 أقل من الحد المسموح: <b>${PROVIDER_BALANCE_WARN:.2f}</b>\n\n"
                            f"⏰ {time.strftime('%Y-%m-%d %H:%M')}\n\n"
                            f"يرجى شحن رصيد المزود فوراً لضمان استمرار الخدمات!",
                            parse_mode="HTML")
                    except:
                        pass
                    _provider_balance_cache["notified"] = True
            else:
                _provider_balance_cache["notified"] = False
        except:
            pass
        time.sleep(PROVIDER_CHECK_INTERVAL)

threading.Thread(target=_provider_balance_monitor, daemon=True).start()

USER_ACTION_LOG = {}
SPAM_MAX_ACTIONS = 5
SPAM_WINDOW = 60

def check_user_spam(uid, action_type="general"):

    if not uid:
        return False
    uid = str(uid)
    now = time.time()

    if uid not in USER_ACTION_LOG:
        USER_ACTION_LOG[uid] = {}
    if action_type not in USER_ACTION_LOG[uid]:
        USER_ACTION_LOG[uid][action_type] = []

    USER_ACTION_LOG[uid][action_type] = [t for t in USER_ACTION_LOG[uid][action_type] if now - t < SPAM_WINDOW]
    USER_ACTION_LOG[uid][action_type].append(now)
    if len(USER_ACTION_LOG[uid][action_type]) >= SPAM_MAX_ACTIONS:

        _auto_ban_user(uid, action_type)
        return True

    try:
        ip = freq.remote_addr
        if _is_local_ip(ip):
            return False
        ip_key = f"ip_{ip}"
        if ip_key not in USER_ACTION_LOG:
            USER_ACTION_LOG[ip_key] = {}
        if action_type not in USER_ACTION_LOG[ip_key]:
            USER_ACTION_LOG[ip_key][action_type] = []
        USER_ACTION_LOG[ip_key][action_type] = [t for t in USER_ACTION_LOG[ip_key][action_type] if now - t < SPAM_WINDOW]
        USER_ACTION_LOG[ip_key][action_type].append(now)

        if len(USER_ACTION_LOG[ip_key][action_type]) >= SPAM_MAX_ACTIONS * 2:
            BLOCKED_IPS.add(ip)
            threading.Timer(120, lambda: BLOCKED_IPS.discard(ip)).start()
            return True
    except: pass
    return False

def _auto_ban_user(uid, action_type):

    uid = str(uid)
    def _ban_mut(users):
        for uname, u in users.items():
            eff_uid = u.get("telegram_id") or u.get("uid", uname)
            if str(eff_uid) == uid:
                u["banned"] = True
                u["ban_reason"] = f"حظر تلقائي: {SPAM_MAX_ACTIONS}+ {action_type} خلال دقيقة"
                u["ban_time"] = time.strftime("%Y-%m-%d %H:%M:%S")
                u["ban_type"] = "auto"
                return (uname, u.get("email", ""))
        return None
    _hit = _mutate_web_users(_ban_mut)
    if _hit:
        _uname, _email = _hit
        try:
            ip = freq.remote_addr if freq else "unknown"
            ua = freq.headers.get('User-Agent', '')[:80] if freq else ""
            bot.send_message(ADMIN_ID,
                f"🚫 حظر تلقائي!\n\n"
                f"👤 {_uname}\n"
                f"📧 {_email}\n"
                f"⚠️ {SPAM_MAX_ACTIONS}+ {action_type} خلال دقيقة\n"
                f"🌐 IP: {ip}\n"
                f"📱 {ua[:50]}\n"
                f"⏰ {time.strftime('%H:%M:%S')}")
        except: pass
        push_admin_notif("system", {"text": f"حظر تلقائي: {_uname} ({action_type} spam)"})

def rate_limit_check():

    path = freq.path
    if path in ('/', '/app', '/favicon.ico') or freq.method == 'GET':
        return True
    ip = freq.remote_addr

    # PERF/BUG FIX #2 — لا نحظر أبداً IP محلي/بروكسي.
    # لو لسبب ما ما وصلنا IP الزائر الحقيقي (Nginx بدون X-Forwarded-For مثلاً)
    # فالـremote_addr راح يكون 127.0.0.1 لكل الناس. حظره = تعطيل الموقع كله.
    # أفضل نتجاهل الـrate-limit بهذي الحالة على أن نطيح الموقع لكل المستخدمين.
    if _is_local_ip(ip):
        return True

    if ip in BLOCKED_IPS:
        return False
    now = time.time()
    rl = RATE_LIMITS.get(ip, {"count": 0, "reset": now + 60})
    if now > rl["reset"]:
        rl = {"count": 1, "reset": now + 60}
    else:
        rl["count"] += 1
    RATE_LIMITS[ip] = rl
    if rl["count"] > MAX_REQUESTS_PER_MIN:
        BLOCKED_IPS.add(ip)
        threading.Timer(30, lambda: BLOCKED_IPS.discard(ip)).start()
        return False
    return True

def sensitive_rate_check(ip, action="general"):

    now = time.time()
    key = f"{ip}:{action}"
    rl = IP_RATE_LIMITS_API.get(key, {"count": 0, "reset": now + 60})
    if now > rl["reset"]:
        rl = {"count": 1, "reset": now + 60}
    else:
        rl["count"] += 1
    IP_RATE_LIMITS_API[key] = rl
    if rl["count"] > MAX_SENSITIVE_PER_MIN:
        return False
    return True

AUDIT_LOG = []
MAX_AUDIT_LOG = 5000

def audit_log(action, uid, details=None):

    entry = {
        "time": time.strftime("%Y-%m-%d %H:%M:%S"),
        "ts": time.time(),
        "action": action,
        "uid": str(uid),
        "ip": freq.remote_addr if freq else "system",
        "details": details or {}
    }
    AUDIT_LOG.append(entry)
    if len(AUDIT_LOG) > MAX_AUDIT_LOG:
        AUDIT_LOG[:] = AUDIT_LOG[-MAX_AUDIT_LOG:]

    try:
        with open("audit_log.json", "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    except: pass

def login_attempt_check(ip):

    now = time.time()
    la = LOGIN_ATTEMPTS.get(ip, {"count": 0, "block_until": 0})
    if now < la.get("block_until", 0):
        return False
    return True

def login_attempt_record(ip, success):

    if success:
        LOGIN_ATTEMPTS.pop(ip, None)
        return
    now = time.time()
    la = LOGIN_ATTEMPTS.get(ip, {"count": 0, "block_until": 0})
    la["count"] += 1
    if la["count"] >= MAX_LOGIN_ATTEMPTS:
        la["block_until"] = now + LOGIN_BLOCK_TIME
        la["count"] = 0
    LOGIN_ATTEMPTS[ip] = la

@app.before_request
def security_check():

    # PERF/BUG FIX #3 — منع حلقة إعادة التوجيه اللانهائية.
    # قبل: لو Nginx ما يرسل X-Forwarded-Proto (إعداد ناقص/متغيّر)، Flask
    # يشوف الطلب "http" ويعمل 301 إلى https → Nginx يمرّره http مرة ثانية →
    # 301 مرة ثانية → حلقة لا نهائية → صفحة بيضاء / ERR_TOO_MANY_REDIRECTS.
    # الآن: ما نعيد التوجيه إلا إذا البروكسي قال صراحةً إن البروتوكول http.
    # (Nginx/Cloudflare أصلاً يسوّون http→https، فما نحتاج نكرّرها هنا.)
    _xfp = (freq.headers.get('X-Forwarded-Proto') or '').strip().lower()
    if _xfp == 'http' and not freq.is_secure:
        if freq.host not in ('localhost', '127.0.0.1') and ':5000' not in freq.host:
            url = freq.url.replace('http://', 'https://', 1)
            return redirect(url, code=301)

    if not rate_limit_check():
        return jsonify({"ok": False, "error": "rate_limited"}), 429

@app.after_request
def security_headers(resp):

    resp.headers['X-Content-Type-Options'] = 'nosniff'
    resp.headers['X-Frame-Options'] = 'SAMEORIGIN'
    resp.headers['X-XSS-Protection'] = '1; mode=block'
    resp.headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains'
    resp.headers['Referrer-Policy'] = 'strict-origin-when-cross-origin'
    resp.headers['Content-Security-Policy'] = (
        "default-src 'self' 'unsafe-inline' 'unsafe-eval' "
        "https://fonts.googleapis.com https://fonts.gstatic.com "
        "https://cdnjs.cloudflare.com https://telegram.org "
        "https://accounts.google.com https://www.gstatic.com; "
        "script-src 'self' 'unsafe-inline' 'unsafe-eval' "
        "https://cdnjs.cloudflare.com https://telegram.org "
        "https://accounts.google.com https://www.gstatic.com; "
        "frame-src 'self' https://accounts.google.com; "
        "img-src 'self' data: blob: https:; "
        "connect-src 'self' https:; "
        "font-src 'self' https://cdnjs.cloudflare.com https://fonts.gstatic.com data:; "
        "media-src 'self' blob: https:"
    )

    # PERF/BUG FIX #17 — لا نطغى على Cache-Control اللي حدّده المسار نفسه.
    # قبل: هذا الهوك كان يكتب فوق أي Cache-Control موجود. النتيجة الأخطر:
    # /sw.js كان يضع "no-store" (صحيح) وهذا الهوك يبدّله إلى max-age=604800
    # → المتصفح يخزّن الـservice worker ٧ أيام → أي تحديث للموقع ما يوصل
    # للمستخدمين لمدة أسبوع، ويظل يخدمهم من كاش قديم.
    # الآن: نضع الافتراضي فقط إذا المسار ما حدّد شي.
    if not resp.headers.get('Cache-Control'):
        if freq.path.endswith(('.png', '.jpg', '.jpeg', '.webp', '.ico', '.svg', '.gif')):
            resp.headers['Cache-Control'] = 'public, max-age=2592000, immutable'
        elif freq.path.endswith(('.woff2', '.woff', '.ttf', '.eot')):
            resp.headers['Cache-Control'] = 'public, max-age=2592000, immutable'
        elif freq.path.endswith(('.css', '.js')) and '/api/' not in freq.path:
            resp.headers['Cache-Control'] = 'public, max-age=604800'

    if resp.content_type and 'json' in resp.content_type and 'gzip' not in resp.headers.get('Content-Encoding', '') and 'gzip' in freq.headers.get('Accept-Encoding', ''):
        try:
            data = resp.get_data()
            if len(data) > 256:
                compressed = _gzip.compress(data, compresslevel=4)
                resp.set_data(compressed)
                resp.headers['Content-Encoding'] = 'gzip'
                resp.headers['Content-Length'] = len(compressed)
                resp.headers['Vary'] = 'Accept-Encoding'
        except: pass
    return resp

WEB_USERS_FILE = "web_users.json"
_wu_lock = threading.RLock()

# ═══════════════════════════════════════════════════════════════════
# PERF FIX #6 — كاش قراءة فقط لملف web_users.json
#
# قبل: _load_web_users() كان يقرأ الملف من القرص ويعمل json.load
# عند *كل* طلب على /api/user (كل 20 ثانية لكل تبويب مفتوح!)
# و /api/reviews/list و /api/landing-stats و get_bal.
# على ملف بآلاف المستخدمين هذا = عشرات/مئات الملي ثانية لكل طلب،
# وكلها تمسك الـGIL وتعطّل باقي الطلبات.
#
# الآن: نحتفظ بنسخة بالذاكرة ونعيد تحميلها فقط لو تغيّر الملف فعلاً
# (mtime + size). أي حفظ عبر _save_web_users يبطّل الكاش تلقائياً.
# ملاحظة: _web_users_ro() للقراءة فقط — لا تعدّلها. أي تعديل يمر من
# _mutate_web_users() اللي يستخدم _load_web_users() (قراءة طازجة).
# ═══════════════════════════════════════════════════════════════════
_wu_ro_lock = threading.Lock()
_wu_ro = {"sig": None, "data": None}

def _wu_ro_invalidate():
    with _wu_ro_lock:
        _wu_ro["sig"] = None
        _wu_ro["data"] = None

def _web_users_ro():
    """نسخة مقروءة من web_users.json بدون قراءة قرص لكل طلب. لا تعدّلها."""
    try:
        st = os.stat(WEB_USERS_FILE)
        sig = (st.st_mtime_ns, st.st_size)
    except Exception:
        sig = None
    with _wu_ro_lock:
        if sig is not None and _wu_ro["sig"] == sig and _wu_ro["data"] is not None:
            return _wu_ro["data"]
    data = _load_web_users()
    with _wu_ro_lock:
        _wu_ro["sig"] = sig
        _wu_ro["data"] = data
    return data

# ═══════════════════════════════════════════════════════════════════
# PERF FIX #7 — تتبّع نشاط المستخدم (IP/جهاز/آخر ظهور) بالخلفية
#
# قبل: get_auth_user() كان — كل 60 ثانية لكل مستخدم — يسوي على خيط
# الطلب نفسه: قفل عام + قراءة web_users.json كامل + نسخ الملف كامل (.bak)
# + كتابة الملف كامل + fsync. يعني كل مستخدم فعّال كان يجمّد الطلبات
# الثانية لمدة الكتابة. مع عدة مستخدمين → طابور على _wu_lock → بطء وتقطّع.
#
# الآن: نجمّع التحديثات بالذاكرة، وخيط واحد بالخلفية يكتبها كلها دفعة
# وحدة كل 30 ثانية. نفس البيانات بالضبط، بس بدون تعطيل أي طلب.
# ═══════════════════════════════════════════════════════════════════
_track_pending = {}
_track_lock = threading.Lock()

def _queue_activity_track(uname, ip, device, ua):
    if not uname:
        return
    with _track_lock:
        _track_pending[uname] = {
            "last_ip": ip,
            "last_device": device,
            "last_ua": (ua or "")[:200],
            "last_active": time.strftime("%Y-%m-%d %H:%M:%S"),
        }

def _activity_flush_loop():
    while True:
        time.sleep(30)
        try:
            with _track_lock:
                if not _track_pending:
                    continue
                batch = dict(_track_pending)
                _track_pending.clear()

            def _apply(users):
                changed = False
                for uname, vals in batch.items():
                    u = users.get(uname)
                    if u:
                        u.update(vals)
                        changed = True
                return changed

            if batch:
                _mutate_web_users(_apply)
        except Exception as e:
            print(f"⚠️ activity flush: {e}")

threading.Thread(target=_activity_flush_loop, daemon=True).start()


def _load_web_users():

    if os.path.exists(WEB_USERS_FILE):
        try:
            with open(WEB_USERS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, dict) and len(data) > 0:
                    return data
        except Exception as e:
            print(f"⚠️ خطأ بقراءة {WEB_USERS_FILE}: {e}")

    bak = WEB_USERS_FILE + ".bak"
    if os.path.exists(bak):
        try:
            with open(bak, "r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, dict) and len(data) > 0:
                    print(f"⚠️ تم استعادة {WEB_USERS_FILE} من .bak ({len(data)} مستخدم)")
                    shutil.copy2(bak, WEB_USERS_FILE)
                    return data
        except: pass

    try:
        backup_dir = "backups"
        if os.path.exists(backup_dir):
            all_dirs = sorted([d for d in os.listdir(backup_dir) if d.startswith("backup_") and os.path.isdir(os.path.join(backup_dir, d))], reverse=True)
            for d in all_dirs:
                f = os.path.join(backup_dir, d, "web_users.json")
                if os.path.exists(f):
                    try:
                        with open(f, "r", encoding="utf-8") as fh:
                            data = json.load(fh)
                        if isinstance(data, dict) and len(data) > 5:
                            print(f"🔄 تم استعادة {WEB_USERS_FILE} من {d} ({len(data)} مستخدم)")
                            shutil.copy2(f, WEB_USERS_FILE)
                            return data
                    except: continue
    except: pass

    for safe in ["web_users_SAFE.json", "web_users_latest.bak"]:
        if os.path.exists(safe):
            try:
                with open(safe, "r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, dict) and len(data) > 0:
                    print(f"🔄 تم استعادة {WEB_USERS_FILE} من {safe} ({len(data)} مستخدم)")
                    shutil.copy2(safe, WEB_USERS_FILE)
                    return data
            except: pass
    print("❌ لم يتم العثور على أي بيانات مستخدمين!")
    return {}

def _save_web_users(users):

    _wu_ro_invalidate()

    with _wu_lock:

        if os.path.exists(WEB_USERS_FILE):
            try:
                with open(WEB_USERS_FILE, "r", encoding="utf-8") as f:
                    old = json.load(f)
                if isinstance(old, dict) and len(old) > 5 and len(users) < len(old) * 0.5:
                    print(f"🛑 حماية البيانات: رفض حفظ {len(users)} مستخدم فوق {len(old)} مستخدم!")
                    return
            except: pass

        try:
            if os.path.exists(WEB_USERS_FILE):
                shutil.copy2(WEB_USERS_FILE, WEB_USERS_FILE + ".bak")
        except: pass

        tmp = WEB_USERS_FILE + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(users, f, ensure_ascii=False, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, WEB_USERS_FILE)
        except Exception as e:
            print(f"⚠️ خطأ بحفظ المستخدمين: {e}")
            try:
                with open(WEB_USERS_FILE, "w", encoding="utf-8") as f:
                    json.dump(users, f, ensure_ascii=False, indent=2)
            except: pass

def _mutate_web_users(mutator):
    """تعديل ذرّي لملف المستخدمين.

    يحمّل النسخة الحديثة من القرص، يطبّق التعديل، ثم يحفظ — كل ذلك داخل
    قفل واحد (_wu_lock). هذا يمنع سباق (load→modify→save) بين الطلبات
    المتزامنة الذي كان يسبب: حذف الحسابات، رجوع الرصيد للصفر، وتكرار
    الـ LO-ID. أي مسار يعدّل web_users.json يجب أن يمر من هنا وليس عبر
    _load_web_users()/_save_web_users() المنفصلين.

    mutator(users) يستلم dict المستخدمين الحيّة ويعدّلها مكانياً،
    ويمكنه إرجاع قيمة (تُرجَّع للمستدعي كما هي).
    """
    with _wu_lock:
        users = _load_web_users()
        result = mutator(users)
        _save_web_users(users)
        return result

def _hash_pass(password):

    salt = "beinty_smm_2026"

    return "pbk$" + hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex()

BEINTY_ID_START = 1000

def _next_beinty_id(users):

    max_num = BEINTY_ID_START - 1
    for u in users.values():
        if not isinstance(u, dict):
            continue
        bid = u.get('beinty_id', '')

        if isinstance(bid, str) and (bid.startswith('LO-') or bid.startswith('BE-')):
            try:
                n = int(bid[3:])
                if n > max_num:
                    max_num = n
            except (ValueError, TypeError):
                pass
    return f'LO-{max_num + 1}'

def _migrate_beinty_ids():

    try:
        users = _load_web_users()
        if not users:
            return

        need_id = []
        for uname, u in users.items():
            if not isinstance(u, dict):
                continue
            if not u.get('beinty_id'):
                need_id.append((uname, u.get('created', '9999-12-31 23:59:59')))
        if not need_id:
            return

        need_id.sort(key=lambda x: x[1])

        next_num = _next_beinty_id(users)
        try:
            next_num = int(next_num[3:])
        except:
            next_num = BEINTY_ID_START
        for uname, _ in need_id:
            users[uname]['beinty_id'] = f'LO-{next_num}'
            next_num += 1
        _save_web_users(users)
        print(f"✅ تم تعيين LO-ID لـ {len(need_id)} مستخدم")
    except Exception as e:
        print(f"⚠️ خطأ في migration LO-ID: {e}")

def _get_beinty_id_by_uid(uid):

    if not uid:
        return ''
    try:
        users = _load_web_users()
        for u in users.values():
            if isinstance(u, dict) and u.get('uid') == uid:
                return u.get('beinty_id', '') or uid

            if isinstance(u, dict) and str(u.get('telegram_id', '')) == str(uid):
                return u.get('beinty_id', '') or str(uid)
    except:
        pass
    return uid

def _hash_pass_legacy(password):

    salt = "beinty_smm_2026"
    return hashlib.sha256((salt + password).encode()).hexdigest()

def _verify_pass(password, stored_hash):

    if stored_hash.startswith("pbk$"):
        return _hash_pass(password) == stored_hash
    else:

        return _hash_pass_legacy(password) == stored_hash

def _needs_rehash(stored_hash):

    return not stored_hash.startswith("pbk$")

def _gen_token():
    return secrets.token_hex(32)

def _gen_otp():
    return str(secrets.randbelow(900000) + 100000)

def _gen_otp6():

    return str(secrets.randbelow(900000) + 100000)

