@app.route('/api/auth/send_verify', methods=['POST'])
def api_send_verify():

    data = freq.json or {}
    email = data.get('email', '').strip().lower()
    if not email or '@' not in email:
        return jsonify({"ok": False, "error": "بريد إلكتروني غير صالح"})
    users = _load_web_users()
    if email == ADMIN_EMAIL.lower():
        return jsonify({"ok": False, "error": "البريد الإلكتروني مستخدم مسبقاً"})
    for uname, u in users.items():
        if uname == "admin": continue
        if u.get("email") == email:
            return jsonify({"ok": False, "error": "البريد الإلكتروني مستخدم مسبقاً"})
    existing = EMAIL_VERIFY_CODES.get(email)
    if existing and time.time() - existing.get("sent", 0) < 60:
        wait = int(60 - (time.time() - existing["sent"]))
        return jsonify({"ok": False, "error": f"انتظر {wait} ثانية قبل إرسال كود جديد"})
    code = str(secrets.randbelow(900000) + 100000)
    EMAIL_VERIFY_CODES[email] = {"code": code, "expires": time.time() + 600, "attempts": 0, "sent": time.time(), "verified": False}
    threading.Thread(target=_send_verify_email, args=(email, code), daemon=True).start()
    return jsonify({"ok": True, "message": "تم إرسال الكود"})

@app.route('/api/auth/verify_code', methods=['POST'])
def api_verify_code():

    data = freq.json or {}
    email = data.get('email', '').strip().lower()
    code = str(data.get('code', '')).strip()
    if not email or not code:
        return jsonify({"ok": False, "error": "أدخل الكود"})
    rec = EMAIL_VERIFY_CODES.get(email)
    if not rec:
        return jsonify({"ok": False, "error": "لم يتم إرسال كود لهذا الإيميل"})
    if time.time() > rec["expires"]:
        EMAIL_VERIFY_CODES.pop(email, None)
        return jsonify({"ok": False, "error": "انتهت صلاحية الكود — أرسل كود جديد"})
    if rec["attempts"] >= 3:
        EMAIL_VERIFY_CODES.pop(email, None)
        return jsonify({"ok": False, "error": "تجاوزت الحد — أرسل كود جديد"})
    rec["attempts"] += 1
    if code != rec["code"]:
        remaining = 3 - rec["attempts"]
        return jsonify({"ok": False, "error": f"كود خاطئ — باقي {remaining} محاولات"})
    rec["verified"] = True
    return jsonify({"ok": True})

def _get_email_by_uid(uid):

    uid_str = str(uid)
    users = _load_web_users()

    for uname, u in users.items():
        if str(u.get("telegram_id","")) == uid_str:
            return u.get("email",""), u.get("name", uname)

    for uname, u in users.items():
        if u.get("uid","") == uid_str:
            return u.get("email",""), u.get("name", uname)
    return "", ""

def _build_apple_email(title, subtitle, icon, rows, btn_text="", btn_link="", note=""):

    rows_html = ""
    for i, (label, value, color) in enumerate(rows):
        border = 'border-bottom:1px solid #e5e5e5;' if i < len(rows)-1 else ''
        val_style = f'font-size:12px;font-weight:800;color:{color or "#1a1a1a"};text-align:left'
