def _send_notif_email(to_email, subject, html_body):

    import smtplib
    from email.mime.multipart import MIMEMultipart
    from email.mime.text import MIMEText
    try:
        msg = MIMEMultipart('alternative')
        msg["From"] = _email_from()
        msg['To'] = to_email

        msg['Subject'] = _email_subject(subject)
        msg.attach(MIMEText(_email_subject(subject), 'plain', 'utf-8'))
        msg.attach(MIMEText(_apply_site_name_to_html(html_body), 'html', 'utf-8'))
        result = _smtp_send(to_email, msg)
        if result:
            print(f"✅ إشعار إيميل: {subject} → {to_email}")
    except Exception as e:
        print(f"⚠️ خطأ إشعار إيميل: {e}")

def _send_notif_email_bg(to_email, subject, html_body):

    if not to_email: return
    threading.Thread(target=_send_notif_email, args=(to_email, subject, html_body), daemon=True).start()

