OTP_STORE = {}

def web_auth_check(token):

    sess = db.web_sessions.get(token)
    if not sess:
        return None
    if time.time() > sess.get("expires", 0):
        db.web_sessions.pop(token, None); db.save()
        return None
    return sess

def invalidate_user_sessions(username):

    to_remove = [t for t, s in db.web_sessions.items() if s.get("username") == username]
    for t in to_remove:
        db.web_sessions.pop(t, None)
    if to_remove:
        db.save()
    return len(to_remove)

def get_auth_user(data=None):

    if data is None:
        data = freq.json or {}
    token = data.get('token', '')
    if not token:
        auth = freq.headers.get('Authorization', '')
        if auth.startswith('Bearer '):
            token = auth[7:]
    if token:
        sess = web_auth_check(token)
        if sess:
            tg_id = sess.get('telegram_id')
            user_result = {
                'id': tg_id if tg_id else sess['uid'],
                'uid': sess['uid'],
                'name': sess.get('name', sess.get('username', '')),
                'username': sess.get('username', ''),
                'email': sess.get('email', ''),
                'is_admin': sess.get('role') == 'admin',
                'telegram_id': tg_id,
                'auth_type': 'web',
                'banned': False,
            }

            try:
                uname = sess.get('username', '')
                if uname:
                    # حالة الحظر: تُقرأ من الكاش بالذاكرة (بدون قرص، بدون قفل ثقيل)
                    try:
                        _u_ro = _web_users_ro().get(uname) or {}
                        user_result['banned'] = bool(_u_ro.get("banned", False))
                    except Exception:
                        pass

                    # تحديث آخر نشاط: يتجمّع بالذاكرة ويُكتب بالخلفية دفعة وحدة
                    _track_key = f"_track_{uname}"
                    _last_track = getattr(get_auth_user, '_cache', {}).get(_track_key, 0)
                    if time.time() - _last_track > 60:
                        ua_str = freq.headers.get('User-Agent', '')
                        _queue_activity_track(uname, freq.remote_addr or "", _parse_device(ua_str), ua_str)
                        if not hasattr(get_auth_user, '_cache'):
                            get_auth_user._cache = {}
                        get_auth_user._cache[_track_key] = time.time()
            except: pass
            return user_result
    return None

def _parse_device(ua):

    if not ua:
        return "غير معروف"
    ua_l = ua.lower()

    device = ""
    if "iphone" in ua_l:
        device = "iPhone"
    elif "ipad" in ua_l:
        device = "iPad"
    elif "android" in ua_l:

        import re as _re
        m = _re.search(r';\s*([^;)]+)\s*Build', ua)
        device = m.group(1).strip() if m else "Android"
    elif "windows" in ua_l:
        device = "Windows PC"
    elif "macintosh" in ua_l:
        device = "Mac"
    elif "linux" in ua_l:
        device = "Linux"
    else:
        device = "غير معروف"

    browser = ""
    if "chrome" in ua_l and "edg" not in ua_l:
        browser = "Chrome"
    elif "safari" in ua_l and "chrome" not in ua_l:
        browser = "Safari"
    elif "firefox" in ua_l:
        browser = "Firefox"
    elif "edg" in ua_l:
        browser = "Edge"
    return f"{device} — {browser}" if browser else device

def require_auth(f):

    @wraps(f)
    def decorated(*args, **kwargs):
        user = get_auth_user()
        if not user:
            return jsonify({"ok": False, "error": "unauthorized"}), 401
        freq.user = user
        return f(*args, **kwargs)
    return decorated

def require_admin(f):

    @wraps(f)
    def decorated(*args, **kwargs):
        user = get_auth_user()
        if not user or not user.get('is_admin'):
            return jsonify({"ok": False, "error": "unauthorized"}), 403
        freq.user = user
        return f(*args, **kwargs)
    return decorated

