    def _is_admin_uid(self, uid):

        try:
            uid_s = str(uid)

            if uid_s == str(ADMIN_ID):
                return True

            cache = getattr(self, '_admin_uid_cache', None)
            now = time.time()
            if not cache or (now - cache.get('ts', 0)) > 5:
                admin_uids = set()
                try:
                    users = _web_users_ro()   # PERF FIX #6: كاش بدل قراءة قرص
                    if isinstance(users, dict):
                        for uname, u in users.items():
                            if u and u.get('role') == 'admin' and u.get('uid'):
                                admin_uids.add(str(u['uid']))
                except Exception:
                    pass
                self._admin_uid_cache = {'set': admin_uids, 'ts': now}
                cache = self._admin_uid_cache
            return uid_s in cache.get('set', set())
        except Exception:
            return False

    def get_bal(self, uid):

        if self._is_admin_uid(uid):
            return 10.0
        return self.balances.get(uid, 0.0)
    def add_bal(self, uid, amt):

        if self._is_admin_uid(uid):
            return
        with self._bal_lock:
            self.balances[uid] = round(self.balances.get(uid, 0.0) + amt, 4)
        self.save()
    def sub_bal(self, uid, amt):

        if self._is_admin_uid(uid):
            return
        with self._bal_lock:
            self.balances[uid] = round(self.balances.get(uid, 0.0) - amt, 4)
        self.save()

    def try_debit(self, uid, amt):
        """خصم ذرّي مشروط: يخصم فقط إذا الرصيد كافٍ. يرجّع True عند النجاح.
        يمنع سباق (check-then-subtract) الذي يسمح بالخصم المزدوج أو الرصيد السالب."""
        if self._is_admin_uid(uid):
            return True
        with self._bal_lock:
            cur = self.balances.get(uid, 0.0)
            if cur + 1e-9 < amt:
                return False
            self.balances[uid] = round(cur - amt, 4)
        self.save()
        return True
    def add_order(self, uid, info):
        self.orders.setdefault(uid, []).append(info); self.save()
    def get_orders(self, uid): return self.orders.get(uid, [])
    def order_count(self, uid): return len(self.orders.get(uid, []))
    def total_orders(self): return sum(len(v) for v in self.orders.values())
    def add_subscriber(self, uid):
        if uid not in self.subscribers:
            self.subscribers.append(uid); self.save()
    def update_payment(self, method, key, value):
        if method in self.payment_methods:
            self.payment_methods[method][key] = value
            if key == "number":
                self.payment_methods[method]["info"] = f"أرسل إلى {method}: {value}"
            self.save()

