def _translate_smm(text):

    if not text:
        return text
    result = text

    for en, ar in _TR_PLATFORMS.items():
        result = result.replace(en, ar)

    for en, ar in sorted(_TR_PHRASES, key=lambda x: len(x[0]), reverse=True):
        result = result.replace(en, ar)

    for en, ar in _TR_COUNTRIES.items():
        if len(en) <= 2:

            result = re.sub(r'(?<= )' + re.escape(en) + r'(?=[\s\]\)]|$)', ar, result)
            result = result.replace(f'[{en}]', f'[{ar}]')
        else:
            result = result.replace(en, ar)

    result = re.sub(r'\s+', ' ', result).strip()
    result = result.replace('[ ', '[').replace(' ]', ']')

    return result

def _legacy_provider_id():
    """يحاول إيجاد معرّف المزوّد الرئيسي (نفس API_URL) ضمن قائمة المزوّدين، إن وُجد.
    يُستخدم لمطابقة الأسماء المخصصة على خدمات الكاش القديم."""
    try:
        host = (API_URL or "").lower().split("//", 1)[-1].split("/", 1)[0]
        if not host:
            return None
        for pid, p in (getattr(db, "providers", {}) or {}).items():
            if host in (p.get("url", "") or "").lower():
                return pid
    except Exception:
        pass
    return None

def _override_for(svc_id, provider_id=None):
    """يرجع الاسم المخصص لخدمة (إن وُجد) من db.service_name_overrides.
    المفاتيح مخزّنة بصيغة 'provider_id:svc_id'. نطابق بالترتيب:
      1) مفتاح المزوّد المحدّد   2) مفتاح المزوّد الرئيسي (للكاش القديم)
      3) مفتاح svc_id المجرّد     4) أي مفتاح ينتهي بـ ':svc_id'
    """
    ov = getattr(db, "service_name_overrides", None) or {}
    if not ov or not svc_id:
        return None
    sid = str(svc_id)

    def _clean(v):
        return str(v).strip() if v and str(v).strip() else None

    if provider_id:
        r = _clean(ov.get(f"{provider_id}:{sid}"))
        if r:
            return r
    lid = _legacy_provider_id()
    if lid:
        r = _clean(ov.get(f"{lid}:{sid}"))
        if r:
            return r
    r = _clean(ov.get(sid))
    if r:
        return r
    suffix = ":" + sid
    for k, val in ov.items():
        if k.endswith(suffix):
            r = _clean(val)
            if r:
                return r
    return None


class ServiceCache:
    def __init__(self):
        self.lock = threading.Lock()
        self.all_services = []
        self.by_category = {}
        self.platforms = []
        self._json_cache = None
        self._cache_time = 0
        self._disk_file = "services_cache.json"
        self._load_from_disk()

    def _load_from_disk(self):
        try:
            if os.path.exists(self._disk_file):
                with open(self._disk_file, 'r') as f:
                    saved = json.load(f)
                self.all_services = saved.get("raw", [])
                cats = {}
                for s in self.all_services:
                    cat = s.get("category", "")
                    cats.setdefault(cat, []).append(s)
                self.by_category = cats

                # نعيد بناء العرض من الخام مع تطبيق الأسماء المخصصة الحالية،
                # حتى وقت الإقلاع تظهر الأسماء المعدّلة فوراً (لا أسماء المزوّد).
                regenerated = False
                if self.all_services:
                    try:
                        cats2, plats2, json_resp2 = self._build_display(self.all_services)
                        self.by_category = cats2
                        self.platforms = plats2
                        self._json_cache = json_resp2
                        regenerated = True
                    except Exception as e:
                        print(f"⚠️ regen on load: {e}")

                if not regenerated:
                    saved_json = saved.get("json_resp")
                    if saved_json:
                        try:
                            parsed = json.loads(saved_json)
                            self.platforms = parsed.get("platforms", [])
                            self._json_cache = saved_json
                        except:
                            self.platforms = saved.get("platforms", [])
                    else:
                        self.platforms = saved.get("platforms", [])
                self._cache_time = saved.get("time", 0)
                print(f"⚡ كاش: {len(self.all_services)} خدمة — {len(self.platforms)} منصة")
        except Exception as e:
            print(f"⚠️ {e}")

    def _save_to_disk(self, svs, plats, json_resp):
        try:
            with open(self._disk_file, 'w') as f:
                json.dump({"raw": svs, "platforms": plats, "json_resp": json_resp, "time": time.time()}, f)
        except:
            pass

    def _build_display(self, svs):
        """يبني قائمة العرض النهائية من البيانات الخام، مع تطبيق الأسماء المخصصة.
        يُستعمل من refresh() و reapply_overrides() و _load_from_disk()."""
        def detect_platform(cat_name):
            return detect_platform_from_name(cat_name)

        cats = {}
        cat_to_plat = {}
        for s in svs:
            cat = s.get("category", "Other")
            cats.setdefault(cat, []).append(s)
            if cat not in cat_to_plat:
                cat_to_plat[cat] = detect_platform(cat)
        plats = []
        for cat in cats:
            p = cat_to_plat[cat]
            if p not in plats:
                plats.append(p)
        services_list = []
        for s in svs:
            rate = float(s.get("rate", 0))
            name_en = s.get("name", "")
            cat_en = s.get("category", "")
            rate = rate * (_follower_mark() if "follow" in name_en.lower() else _general_mark())
            rf = s.get("refill", "")
            sid = str(s.get("service", ""))
            # الاسم الأساسي من المزوّد (مترجم) — ثم نطبّق الاسم المخصص إن وُجد
            disp_name = _translate_smm(name_en)
            _ov = _override_for(sid)
            if _ov:
                disp_name = _ov
            obj = {
                "id": sid,
                "name": disp_name,
                "cat": _translate_smm(cat_en),
                "plat": cat_to_plat.get(cat_en, "Other"),
                "rate": round(rate, 4),
                "min": s.get("min", 0),
                "max": s.get("max", 0),
            }
            rf_str = str(rf) if rf and str(rf) not in ("0", "False", "false", "True", "true") else ("∞" if str(rf).lower() == "true" else "")
            if rf_str:
                obj["rf"] = rf_str
            if s.get("cancel"):
                obj["cn"] = True
            services_list.append(obj)
        json_resp = json.dumps({"ok": True, "services": services_list, "platforms": plats}, ensure_ascii=False)
        return cats, plats, json_resp

    def refresh(self):
        try:
            resp = requests.get(API_URL, params={"key": API_KEY, "action": "services"}, timeout=30)
            data = resp.json()
            svs = data["data"] if isinstance(data, dict) and "data" in data else data if isinstance(data, list) else []
        except Exception:
            return
        if not svs:
            return

        cats, plats, json_resp = self._build_display(svs)
        with self.lock:
            self.all_services = svs
            self.by_category = cats
            self.platforms = plats
            self._json_cache = json_resp
            self._cache_time = time.time()
        threading.Thread(target=self._save_to_disk, args=(svs, plats, json_resp), daemon=True).start()
        print(f"🔄 خدمات: {len(svs)} — منصات: {', '.join(plats[:12])}")

    def reapply_overrides(self):
        """يعيد تطبيق الأسماء المخصصة على الكاش القديم فوراً دون إعادة سحب من المزوّد.
        يُستدعى بعد أي تعديل اسم من لوحة الأدمن حتى يبيّن التغيير فوراً."""
        try:
            with self.lock:
                svs = list(self.all_services or [])
            if not svs:
                return
            cats, plats, json_resp = self._build_display(svs)
            with self.lock:
                self.by_category = cats
                self.platforms = plats
                self._json_cache = json_resp
                self._cache_time = time.time()
            threading.Thread(target=self._save_to_disk, args=(svs, plats, json_resp), daemon=True).start()
        except Exception as e:
            print(f"⚠️ reapply_overrides error: {e}")

    def get_json(self):
        with self.lock:
            return self._json_cache

    def find(self, sid):
        sid = str(sid)
        with self.lock:
            return next((s for s in self.all_services if str(s.get("service")) == sid), None)

cache = ServiceCache()


