def _compile_platform_rules():
    """يحوّل القائمة فوق إلى regex مُجمّعة. word-boundary مخصصة تشتغل صح
       للعربي (لأن \\b من Python ما تتعامل ممتاز مع حروف يونيكود عربية)."""
    compiled = []
    for plat, keywords in _PLATFORM_RULES:
        patterns = []
        for kw in keywords:
            if kw.startswith('re:'):
                patterns.append(kw[3:])
                continue
            kw_stripped = kw.strip()
            if not kw_stripped:
                continue
            escaped = re.escape(kw_stripped)
            patterns.append(r'(?<![\w\u0600-\u06FF])' + escaped + r'(?![\w\u0600-\u06FF])')
        if not patterns:
            continue
        try:
            compiled.append((plat, re.compile('|'.join(patterns), re.IGNORECASE)))
        except re.error as e:
            print(f"[platform-rules] تجاهلت {plat} بسبب خطأ regex: {e}")
    return compiled


_PLATFORM_COMPILED = _compile_platform_rules()

_PLAT_KEYWORDS = []


def detect_platform_from_name(text):
    """
    يكتشف منصة الخدمة من نص (اسم/فئة/مزيج).
    - يرجع اسم المنصة الموحد لو لقى تطابق صريح
    - يرجع 'Other' لو ما لقى - ولا يحاول تخمين من أول كلمة
      (التخمين هو اللي كان يخلق منصات وهمية مثل HQ / Premium / Best)
    """
    if not text:
        return "Other"
    s = str(text).strip()
    if not s:
        return "Other"
    for plat, pat in _PLATFORM_COMPILED:
        if pat.search(s):
            return plat
    return "Other"


