def _detect_quality(text):
    """
    يكشف صفة الضمان من نص الخدمة.
    يرجع: 'بضمان' / 'بدون ضمان' / 'ضمان مدى الحياة' أو None لو ما واضح.
    يستخدم word-boundary حقيقية تشتغل صح للعربي والإنجليزي.
    """
    if not text:
        return None
    s = str(text)
    for label, kws in _QUALITY_RULES:
        for kw in kws:
            kw_clean = kw.strip()
            if not kw_clean:
                continue
            pat = r'(?<![\w\u0600-\u06FF])' + re.escape(kw_clean) + r'(?![\w\u0600-\u06FF])'
            if re.search(pat, s, re.IGNORECASE):
                return label
    return None


def detect_category_from_name(text):
    """
    يكشف الفئة الأساسية + لاحقة الضمان من اسم الخدمة.
    أمثلة:
      "Instagram Followers Refill 30 Days" -> "متابعين (بضمان)"
      "TikTok Followers No Refill"          -> "متابعين (بدون ضمان)"
      "YouTube Views"                       -> "مشاهدات"
      "Likes Lifetime Guarantee"            -> "لايكات (ضمان مدى الحياة)"
    """
    if not text:
        return "خدمات"
    low = str(text).lower()
    base_cat = "خدمات"
    for kw, cat in _CAT_KEYWORDS:
        if kw in low:
            base_cat = cat
            break
    quality = _detect_quality(text)
    if quality:
        return f"{base_cat} ({quality})"
    return base_cat


def smm_api_call(url, api_key, action, timeout=15, **params):

    if not url or not api_key:
        return {"error": "missing_credentials"}

    u = url.rstrip('/')
    data = {"key": api_key, "action": action}
    data.update(params)
    try:
        if action == "add":
            r = requests.post(u, data=data, timeout=timeout)
        else:
            r = requests.get(u, params=data, timeout=timeout)
        try:
            return r.json() if r.status_code == 200 else {"error": f"http_{r.status_code}"}
        except Exception:
            return {"error": "invalid_json", "raw": r.text[:200]}
    except requests.exceptions.Timeout:
        return {"error": "timeout"}
    except Exception as e:
        return {"error": str(e)[:100]}

def provider_fetch_services(provider):

    resp = smm_api_call(provider["url"], provider["api_key"], "services", timeout=30)
    if isinstance(resp, dict) and resp.get("error"):
        return None, resp["error"]
    services = resp["data"] if isinstance(resp, dict) and "data" in resp else resp if isinstance(resp, list) else []
    return services, None

def provider_fetch_balance(provider):

    resp = smm_api_call(provider["url"], provider["api_key"], "balance", timeout=10)
    if isinstance(resp, dict) and resp.get("error"):
        return None, resp["error"]

    if isinstance(resp, dict):
        try:
            return float(resp.get("balance", 0) or 0), None
        except:
            return 0.0, None
    return 0.0, "unknown_response"

def provider_place_order(provider, service_id, link, quantity):

    resp = smm_api_call(provider["url"], provider["api_key"], "add",
                         service=service_id, link=link, quantity=quantity, timeout=30)
    return resp

def provider_check_order(provider, order_id):

    resp = smm_api_call(provider["url"], provider["api_key"], "status", order=order_id, timeout=10)
    return resp

class AggregatedCache:

    def __init__(self):
        self.lock = threading.Lock()
        self.services = []
        self.platforms = []
        self._json = None
        self._time = 0

    def rebuild(self):

        services = []
        plats_order = []
        plats_seen = set()
        for key, psvc in db.provider_services.items():
            if not psvc.get("enabled"):
                continue
            prov = db.providers.get(psvc.get("provider_id"))
            if not prov or not prov.get("enabled", True):
                continue
            base_rate = float(psvc.get("rate", 0) or 0)
            markup = psvc.get("user_markup")
            if markup is None or markup == 0:
                name_lower = (psvc.get("name_en", "") or "").lower()
                markup = _follower_mark() if "follow" in name_lower else _general_mark()
            final_rate = round(base_rate * float(markup), 4)
            plat = psvc.get("platform", "Other") or "Other"
            if psvc.get("category_custom") and psvc.get("category"):
                computed_cat = psvc.get("category")
            else:
                _raw_cat_en = (psvc.get("category_en", "") or "").strip()
                if _raw_cat_en:
                    try:
                        computed_cat = _translate_smm(_raw_cat_en) or _raw_cat_en
                    except:
                        computed_cat = _raw_cat_en
                else:
                    _combined_text = ((psvc.get("name_en", "") or "") + " " + (psvc.get("category_en", "") or "")).strip()
                    if _combined_text:
                        computed_cat = detect_category_from_name(_combined_text)
                    else:
                        computed_cat = psvc.get("category") or "خدمات"
            cat_ar = computed_cat
            name_ar = psvc.get("name_ar") or _translate_smm(psvc.get("name_en", "") or "")
            if not (name_ar or "").strip():
                svc_id_raw = psvc.get("svc_id", "")
                cat_part = (cat_ar or "").strip()
                if cat_part:
                    name_ar = f"{plat} — {cat_part}" if plat and plat != "Other" else cat_part
                elif plat and plat != "Other":
                    name_ar = f"خدمة {plat} #{svc_id_raw}" if svc_id_raw else f"خدمة {plat}"
                else:
                    name_ar = f"خدمة #{svc_id_raw}" if svc_id_raw else "خدمة"
            _ovr = (db.service_name_overrides or {}).get(str(key))
            if _ovr and str(_ovr).strip():
                name_ar = str(_ovr).strip()
            disp_id = psvc.get("svc_id", "") or (key.split(":", 1)[1] if ":" in key else key)
            services.append({
                "id": key,
                "display_id": disp_id,
                "name": name_ar,
                "cat": cat_ar,
                "plat": plat,
                "rate": final_rate,
                "min": int(psvc.get("min", 0) or 0),
                "max": int(psvc.get("max", 0) or 0),
                "pv": True,
            })
            if plat not in plats_seen:
                plats_seen.add(plat)
                plats_order.append(plat)
        with self.lock:
            self.services = services
            self.platforms = plats_order
            self._json = json.dumps({"ok": True, "services": services, "platforms": plats_order}, ensure_ascii=False)
            self._time = time.time()

    def get_json(self):
        with self.lock:
            return self._json

    def find(self, sid):

        with self.lock:
            for s in self.services:
                if s["id"] == sid:
                    return s
        return None

    def has_any(self):

        with self.lock:
            return len(self.services) > 0

agg_cache = AggregatedCache()

def _hidden_plats_set():
    """رجوع set من اسماء المنصات المخفية بالحروف الصغيرة — للمقارنة case-insensitive"""
    try:
        return set((p or "").strip().lower() for p in (db.hidden_platforms or []) if p)
    except:
        return set()

def rebuild_agg_cache():

    try:
        agg_cache.rebuild()
    except Exception as e:
        print(f"⚠️ agg_cache rebuild error: {e}")

rebuild_agg_cache()

