def _fsim_slug_to_iso(slug):
    s = str(slug or "").strip().lower().replace(" ", "").replace("_", "").replace("-", "")
    if s in VN_COUNTRIES_DATA:   # المفتاح أصلاً ISO
        return s
    return FIVESIM_NAME_TO_ISO.get(s)

def _vn_svc_icon(svc_id):
    s = (svc_id or "").lower()
    for k,v in {"whatsapp":"wa","telegram":"tg","facebook":"fb","instagram":"ig",
                "tiktok":"tk","google":"gm","gmail":"gm","twitter":"x","discord":"dc",
                "snapchat":"sn","youtube":"yt"}.items():
        if k in s: return v
    return "other"

def _extract_code(sms_text):

    if not sms_text: return ""
    import re as _re
    m = _re.findall(r'\b\d{4,8}\b', sms_text)
    return m[0] if m else ""

def _vn_add_to_blacklist(uid, phone, reason="", country="", service=""):
    """يضيف رقم لقائمة الأرقام السوداء للمستخدم — يمنع إعادة شراء نفس الرقم"""
    if not phone or not uid: return
    uid_s = str(uid)
    if not hasattr(db, "vn_phone_blacklist"):
        db.vn_phone_blacklist = {}
    if uid_s not in db.vn_phone_blacklist:
        db.vn_phone_blacklist[uid_s] = {}
    p = str(phone).strip().lstrip("+").replace(" ", "").replace("-", "")
    db.vn_phone_blacklist[uid_s][p] = {
        "ts": time.time(),
        "reason": reason,
        "country": country,
        "service": service,
    }
    if len(db.vn_phone_blacklist[uid_s]) > 200:
        items = sorted(db.vn_phone_blacklist[uid_s].items(),
                       key=lambda x: x[1].get("ts", 0), reverse=True)
        db.vn_phone_blacklist[uid_s] = dict(items[:200])

def _vn_is_blacklisted(uid, phone):
    """يفحص هل الرقم بالقائمة السوداء للمستخدم"""
    if not phone or not uid: return False
    if not hasattr(db, "vn_phone_blacklist"): return False
    p = str(phone).strip().lstrip("+").replace(" ", "").replace("-", "")
    return p in db.vn_phone_blacklist.get(str(uid), {})

def _vn_cleanup_blacklist():
    """ينظف الأرقام الأقدم من 30 يوم — استدعها بشكل دوري"""
    if not hasattr(db, "vn_phone_blacklist"): return
    now = time.time()
    expire = 30 * 86400
    for uid in list(db.vn_phone_blacklist.keys()):
        phones = db.vn_phone_blacklist[uid]
        for phone in list(phones.keys()):
            if now - phones[phone].get("ts", 0) > expire:
                del phones[phone]
        if not phones:
            del db.vn_phone_blacklist[uid]

