def _sa_name_to_slug(name):
    """يحوّل اسم خدمة المزوّد (إنجليزي) إلى سلَگ داخلي ثابت. fallback: تطبيع عام."""
    n = (name or "").strip().lower()
    if not n:
        return ""
    for slug, kws in SA_NAME_KEYWORDS:
        for kw in kws:
            if kw in n:
                return slug
    # تطبيع عام: أحرف/أرقام فقط مفصولة بـ _ — يضمن سلَگاً صالحاً (الاسم صحيح والكود صحيح)
    s = re.sub(r"[^a-z0-9]+", "_", n).strip("_")
    return s or n

def _sa_fetch_service_slugs(u, k):
    """يبني خريطة {code_lower: slug} موثوقة من getServicesList. best-effort: {} عند الفشل."""
    out = {}
    try:
        r = requests.get(u, params={"api_key": k, "action": "getServicesList"}, timeout=15)
        if r.status_code != 200:
            return out
        d = r.json()
        svcs = d.get("services") if isinstance(d, dict) else None
        if not isinstance(svcs, list):
            return out
        for s in svcs:
            if not isinstance(s, dict):
                continue
            code = str(s.get("code", "") or "").strip().lower()
            slug = _sa_name_to_slug(s.get("name", ""))
            if code and slug:
                out[code] = slug
        if out:
            print(f"[sms-activate] getServicesList: built authoritative code→slug map ({len(out)} entries)")
    except Exception as e:
        print(f"[sms-activate] getServicesList failed: {str(e)[:80]} — using static shortcode fallback")
    return out

