@app.route('/api/user/set_currency', methods=['POST'])
def api_set_currency():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    currency = str(data.get("currency", "")).strip().upper()

    ALLOWED = {c["code"] for c in DEFAULT_CURRENCIES}
    if currency not in ALLOWED:
        return jsonify({"ok": False, "error": "invalid_currency"}), 400
    username = user.get("username", "")
    if not username:
        return jsonify({"ok": False, "error": "no_username"}), 400
    try:
        users = _load_web_users()
        if username not in users:
            # المستخدم موجود بالـ session بس مو بـ web_users - حالة نادرة جداً
            # نسجلها لكن نرجع ok=True لأن العميل لازم يكمل
            print(f"⚠️ set_currency: المستخدم {username} موجود بالـ session لكن مو بـ web_users")
            return jsonify({"ok": True, "currency": currency, "warn": "user_not_in_db"})
        users[username]["currency"] = currency
        _save_web_users(users)
        return jsonify({"ok": True, "currency": currency})
    except Exception as e:
        print(f"⚠️ خطأ بحفظ العملة للمستخدم {username}: {e}")
        return jsonify({"ok": False, "error": "save_failed"}), 500

def _all_services_raw():
    """يرجّع كل الخدمات (الأساسي + المجمّع) كقائمة dict خام قبل تطبيق ميتا الأقسام."""
    out = []
    try:
        bc = cache.get_json()
        if bc:
            out += list(json.loads(bc).get("services", []))
    except Exception:
        pass
    try:
        if agg_cache.has_any():
            aj = agg_cache.get_json()
            if aj:
                out += list(json.loads(aj).get("services", []))
    except Exception:
        pass
    return out

def _apply_cat_meta(services):
    """يطبّق إعادة التسمية + الإخفاء + الترتيب/التثبيت + تعيين الخدمة لقسم — كلها وقت الإرسال."""
    meta = getattr(db, "category_meta", {}) or {}
    ovr = getattr(db, "service_cat_overrides", {}) or {}
    if not meta and not ovr:
        return services
    out = []
    for s in services:
        sid = str(s.get("id", ""))
        orig = (ovr.get(sid) or s.get("cat", "") or "").strip()
        m = meta.get(orig)
        if m and m.get("hidden"):
            continue
        ns = dict(s)
        ns["cat"] = orig
        if m:
            nm = (m.get("name", "") or "").strip()
            if nm:
                ns["cat"] = nm
            ns["_co"] = int(m.get("order", 9999))
            ns["_cp"] = 1 if m.get("pinned") else 0
        else:
            ns["_co"] = 9999
            ns["_cp"] = 0
        out.append(ns)
    out.sort(key=lambda x: (-x.get("_cp", 0), x.get("_co", 9999)))
    for x in out:
        x.pop("_co", None)
        x.pop("_cp", None)
    return out

# ═══════════════════════════════════════════════════════════════════
# PERF FIX #5 — كاش مبنى الرد النهائي لـ /api/services
#
# قبل: كل طلب على /api/services كان يسوي (على آلاف الخدمات = عدة ميغابايت):
#   json.loads(base) + json.loads(agg) + دمج + فلترة + json.dumps
#   + json.loads مرة ثانية + _apply_cat_meta (نسخ dict لكل خدمة + sort)
#   + json.dumps مرة ثانية + md5 على النص كامل + gzip على النص كامل
# حتى الرد 304 كان يدفع كل هذي الكلفة! ومع الـGIL هذا يجمّد كل الطلبات
# الثانية (حتى تحميل /app نفسه) → صفحة بيضاء لثواني.
#
# الآن: نبني الرد مرة وحدة فقط، ونعيد استخدامه لين تتغيّر البيانات فعلاً.
# البصمة (fingerprint) تتغيّر تلقائياً عند: تحديث الخدمات، تحديث المزوّدين،
# إخفاء منصة، تعديل قسم/اسم من لوحة الأدمن.
# ═══════════════════════════════════════════════════════════════════
_svc_payload_lock = threading.Lock()
_svc_payload = {"fp": None, "gz": None, "raw": None, "etag": None}

def _svc_fingerprint(hidden):
    try:
        meta = getattr(db, "category_meta", {}) or {}
        ovr = getattr(db, "service_cat_overrides", {}) or {}
        sig = json.dumps([sorted(hidden), meta, ovr], ensure_ascii=False, sort_keys=True)
        meta_h = hashlib.md5(sig.encode()).hexdigest()[:12]
    except Exception:
        meta_h = "x"
    return "%s|%s|%s|%s|%s" % (
        getattr(cache, "_cache_time", 0),
        len(getattr(cache, "all_services", []) or []),
        getattr(agg_cache, "_time", 0),
        len(getattr(agg_cache, "services", []) or []),
        meta_h,
    )

@app.route('/api/services', methods=['GET'])
def api_services():

    _hidden_fp = _hidden_plats_set()
    fp = _svc_fingerprint(_hidden_fp)

    with _svc_payload_lock:
        cached_ok = (_svc_payload["fp"] == fp and _svc_payload["gz"] is not None)
        c_gz, c_raw, c_etag = _svc_payload["gz"], _svc_payload["raw"], _svc_payload["etag"]

    if cached_ok:
        # الفحص الرخيص أولاً: لو المتصفح عنده نفس النسخة → 304 بكلفة صفر تقريباً
        if freq.headers.get('If-None-Match') == c_etag:
            r304 = app.response_class(status=304)
            r304.headers['ETag'] = c_etag
            r304.headers['Cache-Control'] = 'no-cache'
            return r304
        if 'gzip' in freq.headers.get('Accept-Encoding', ''):
            resp = app.response_class(response=c_gz, status=200, mimetype='application/json')
            resp.headers['Content-Encoding'] = 'gzip'
            resp.headers['ETag'] = c_etag
            resp.headers['Cache-Control'] = 'no-cache'
            resp.headers['Vary'] = 'Accept-Encoding'
            return resp
        resp = app.response_class(response=c_raw, status=200, mimetype='application/json')
        resp.headers['ETag'] = c_etag
        resp.headers['Cache-Control'] = 'no-cache'
        return resp

    return _api_services_build(fp)

def _api_services_build(fp):

    base_cached = cache.get_json()

    agg_json = agg_cache.get_json() if agg_cache.has_any() else None

    _hidden = _hidden_plats_set()

    if base_cached and agg_json:

        try:
            base = json.loads(base_cached)
            agg = json.loads(agg_json)
            merged_services = list(base.get("services", [])) + list(agg.get("services", []))

            plats = list(base.get("platforms", []))
            for p in agg.get("platforms", []):
                if p not in plats:
                    plats.append(p)

            if _hidden:
                merged_services = [s for s in merged_services if (s.get("plat", "") or "").strip().lower() not in _hidden]
                plats = [p for p in plats if (p or "").strip().lower() not in _hidden]

            final = json.dumps({"ok": True, "services": merged_services, "platforms": plats}, ensure_ascii=False)
        except Exception:
            final = base_cached
    elif agg_json:
        if _hidden:
            try:
                _aj = json.loads(agg_json)
                _aj["services"] = [s for s in _aj.get("services", []) if (s.get("plat", "") or "").strip().lower() not in _hidden]
                _aj["platforms"] = [p for p in _aj.get("platforms", []) if (p or "").strip().lower() not in _hidden]
                final = json.dumps(_aj, ensure_ascii=False)
            except:
                final = agg_json
        else:
            final = agg_json
    elif base_cached:
        if _hidden:
            try:
                _bj = json.loads(base_cached)
                _bj["services"] = [s for s in _bj.get("services", []) if (s.get("plat", "") or "").strip().lower() not in _hidden]
                _bj["platforms"] = [p for p in _bj.get("platforms", []) if (p or "").strip().lower() not in _hidden]
                final = json.dumps(_bj, ensure_ascii=False)
            except:
                final = base_cached
        else:
            final = base_cached
    else:
        return jsonify({"ok": True, "services": [], "platforms": []})

    # === تطبيق ميتا الأقسام (إعادة تسمية/إخفاء/ترتيب/تعيين) ===
    try:
        _fj = json.loads(final)
        _fj["services"] = _apply_cat_meta(_fj.get("services", []))
        final = json.dumps(_fj, ensure_ascii=False)
    except Exception:
        pass

    etag_seed = final.encode() + ("|h:" + ",".join(sorted(_hidden))).encode()
    etag = '"' + hashlib.md5(etag_seed).hexdigest()[:16] + '"'
    raw_bytes = final.encode('utf-8')
    gz_bytes = _gzip.compress(raw_bytes, compresslevel=6)

    # نخزّن النسخة المبنية — كل الطلبات الجاية تُخدَم من هنا بدون أي CPU
    with _svc_payload_lock:
        _svc_payload["fp"] = fp
        _svc_payload["raw"] = raw_bytes
        _svc_payload["gz"] = gz_bytes
        _svc_payload["etag"] = etag

    if freq.headers.get('If-None-Match') == etag:
        r304 = app.response_class(status=304)
        r304.headers['ETag'] = etag
        r304.headers['Cache-Control'] = 'no-cache'
        return r304
    if 'gzip' in freq.headers.get('Accept-Encoding', ''):
        resp = app.response_class(response=gz_bytes, status=200, mimetype='application/json')
        resp.headers['Content-Encoding'] = 'gzip'
        resp.headers['ETag'] = etag
        resp.headers['Cache-Control'] = 'no-cache'
        resp.headers['Vary'] = 'Accept-Encoding'
        return resp
    resp = app.response_class(response=raw_bytes, status=200, mimetype='application/json')
    resp.headers['ETag'] = etag
    resp.headers['Cache-Control'] = 'no-cache'
    return resp

@app.route('/api/order', methods=['POST'])
def api_order():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']

    if not sensitive_rate_check(freq.remote_addr, "order"):
        return jsonify({"ok": False, "error": "كثرة الطلبات — انتظر دقيقة"}), 429

    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور"})
    sid = str(data.get('service_id', ''))
    link = str(data.get('link', '')).strip()
    try:
        qty = int(data.get('quantity', 0))
    except:
        return jsonify({"ok": False, "error": "invalid_quantity"})

    svc = cache.find(sid)
    is_provider_svc = False
    selected_provider = None
    if not svc:

        svc = agg_cache.find(sid)
        if svc:
            is_provider_svc = True
            if ":" in sid:
                prov_id = sid.split(":", 1)[0]
                selected_provider = db.providers.get(prov_id)
                if not selected_provider or not selected_provider.get("enabled", True):
                    return jsonify({"ok": False, "error": "provider_disabled"})
    if not svc:
        return jsonify({"ok": False, "error": "service_not_found"})
    if not re.match(r"^https?://", link):
        return jsonify({"ok": False, "error": "invalid_link"})
    mn, mx = int(svc.get("min", 0)), int(svc.get("max", 0))
    if qty < mn or qty > mx:
        return jsonify({"ok": False, "error": "quantity_out_of_range", "min": mn, "max": mx})

    if is_provider_svc:
        rate = float(svc.get("rate", 0))
        _raw_psvc = db.provider_services.get(svc["id"], {})
        base_rate = float(_raw_psvc.get("rate", 0) or rate)
    else:
        rate = calc_rate(svc)
        base_rate = float(svc.get("rate", 0))
    provider_cost = round((base_rate * qty) / 1000.0, 4)
    cost = round((rate * qty) / 1000.0, 4)
    original_cost = cost
    discount = 0
    coupon_code = str(data.get("coupon", "")).strip().upper()

    if coupon_code and coupon_code in db.coupons:
        cp = db.coupons[coupon_code]
        cp_ok = True
        if not cp.get("active", True):
            cp_ok = False
        if cp.get("expires") and time.time() > cp["expires"]:
            cp_ok = False
        if cp.get("max_usage", 0) > 0 and cp.get("used", 0) >= cp["max_usage"]:
            cp_ok = False
        if cp.get("per_user", 0) > 0:
            user_used = sum(1 for u in cp.get("used_by", []) if u == str(uid))
            if user_used >= cp["per_user"]:
                cp_ok = False
        if cp.get("first_only") and db.order_count(uid) > 0:
            cp_ok = False
        if cp.get("min_order", 0) > 0 and cost < cp["min_order"]:
            cp_ok = False
        if cp_ok and cp.get("type") != "credit":
            if cp["type"] == "percent":
                discount = round(cost * cp["value"] / 100, 4)
            elif cp["type"] == "fixed":
                discount = min(cp["value"], cost)
            cost = round(max(0, cost - discount), 4)

            cp.setdefault("used_by", []).append(str(uid))
            cp["used"] = cp.get("used", 0) + 1
            db.save()

    bal = db.get_bal(uid)
    if uid != ADMIN_ID and bal < cost:
        return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})

    comments = str(data.get('comments', '')).strip()
    if is_provider_svc and selected_provider:

        actual_svc_id = sid.split(":", 1)[1] if ":" in sid else sid
        rec = provider_place_order(selected_provider, actual_svc_id, link, qty)
        if comments:

            extra = smm_api_call(selected_provider["url"], selected_provider["api_key"], "add",
                                  service=actual_svc_id, link=link, quantity=qty, comments=comments, timeout=30)
            if isinstance(extra, dict) and "order" in extra:
                rec = extra
    else:
        api_params = dict(action="add", service=svc["service"], link=link, quantity=qty)
        if comments:
            api_params["comments"] = comments
        rec = api_call(**api_params)
    if "order" not in rec:
        return jsonify({"ok": False, "error": "api_error", "detail": str(rec)})

    oid = rec["order"]
    if uid != ADMIN_ID:
        db.sub_bal(uid, cost)
    _svc_name_ar = svc.get("name", "") if is_provider_svc else _translate_smm(svc.get("name", ""))
    _order_record = {
        "order": oid, "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
        "service": _svc_name_ar, "service_id": sid,
        "qty": qty, "link": link, "cost": cost, "provider_cost": provider_cost, "notified": False,
    }

    if is_provider_svc and selected_provider:
        _order_record["provider_id"] = selected_provider["id"]
    db.add_order(uid, _order_record)
    audit_log("order_placed", uid, {"order_id": oid, "cost": cost, "service": _svc_name_ar, "qty": qty})

    try: check_level_gift(uid)
    except: pass

    push_admin_notif("order", {"uid": uid, "name": "", "cost": cost, "service": _svc_name_ar, "order_id": oid})

    def _delay_cache_status():
        time.sleep(5)
        try:
            rec2 = _status_for_order(_order_record)
            for o in db.get_orders(uid):
                if str(o["order"]) == str(oid):
                    o["_cached_status"] = rec2
                    o["_cached_time"] = time.time()
                    break
        except:
            pass
    threading.Thread(target=_delay_cache_status, daemon=True).start()

    push_user_notif(uid, "order", "تم تقديم طلبك!", f"طلب #{oid} — {_svc_name_ar} — ${cost:.4f}", "box")

    _wa_ph = get_user_phone(uid)
    if _wa_ph:
        threading.Thread(target=wa_order_placed, args=(_wa_ph, oid, _svc_name_ar, cost), daemon=True).start()

    try:
        uid_key = db._safe_key(uid)
        ref_data = db.referrals.get(uid_key, {})
        referrer = ref_data.get("referred_by")
        if referrer:
            referrer_key = db._safe_key(referrer)
            rr = db.referrals.get(referrer_key)
            if rr:
                commission = round(cost * REFERRAL_COMMISSION / 100, 4)
                if commission > 0:
                    rr["pending"] = round(rr.get("pending", 0) + commission, 4)
                    rr.setdefault("history", []).append({"amount": commission, "from_order": oid, "time": time.strftime("%d/%m %H:%M")})
                    db.save()
                    push_user_notif(referrer_key, "system", "عمولة إحالة!", f"+${commission:.4f} من طلب إحالتك", "coins")
    except: pass

    try:
        bot.send_message(uid,
            f"✅ تم تقديم طلب من الموقع!\n\n"
            f"رقم الطلب: {oid}\n"
            f"الخدمة: {svc.get('name')}\n"
            f"الكمية: {qty}\n"
            f"التكلفة: ${cost:.4f}\n"
            f"المتبقي: ${db.get_bal(uid):.4f}",
            reply_markup=main_kb(uid))
    except:
        pass

    return jsonify({
        "ok": True,
        "order": {
            "id": oid,
            "service": svc.get("name", ""),
            "qty": qty,
            "cost": cost,
            "original_cost": original_cost,
            "discount": discount,
            "coupon": coupon_code if discount > 0 else "",
            "balance": db.get_bal(uid)
        }
    })

@app.route('/api/order/schedule', methods=['POST'])
def api_order_schedule():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    if not sensitive_rate_check(freq.remote_addr, "order"):
        return jsonify({"ok": False, "error": "كثرة الطلبات — انتظر دقيقة"}), 429
    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور"})
    sid = str(data.get('service_id', ''))
    link = str(data.get('link', '')).strip()
    schedule_time = data.get('schedule_time', 0)
    try:
        qty = int(data.get('quantity', 0))
        schedule_time = int(schedule_time)
    except:
        return jsonify({"ok": False, "error": "بيانات غير صحيحة"})

    if schedule_time < time.time() + 300:
        return jsonify({"ok": False, "error": "الوقت لازم يكون بعد 5 دقائق على الأقل"})
    if schedule_time > time.time() + 7 * 86400:
        return jsonify({"ok": False, "error": "الحد الأقصى للجدولة 7 أيام"})

    svc = cache.find(sid)
    if not svc:
        return jsonify({"ok": False, "error": "service_not_found"})
    if not re.match(r"^https?://", link):
        return jsonify({"ok": False, "error": "invalid_link"})
    mn, mx = int(svc.get("min", 0)), int(svc.get("max", 0))
    if qty < mn or qty > mx:
        return jsonify({"ok": False, "error": "quantity_out_of_range", "min": mn, "max": mx})

    rate = calc_rate(svc)
    cost = round((rate * qty) / 1000.0, 4)
    comments = str(data.get('comments', '')).strip()
    coupon_code = str(data.get("coupon", "")).strip().upper()

    discount = 0
    if coupon_code and coupon_code in db.coupons:
        cp = db.coupons[coupon_code]
        cp_ok = True
        if not cp.get("active", True): cp_ok = False
        if cp.get("expires") and time.time() > cp["expires"]: cp_ok = False
        if cp.get("max_usage", 0) > 0 and cp.get("used", 0) >= cp["max_usage"]: cp_ok = False
        if cp_ok and cp.get("type") != "credit":
            if cp["type"] == "percent":
                discount = round(cost * cp["value"] / 100, 4)
            elif cp["type"] == "fixed":
                discount = min(cp["value"], cost)
            cost = round(max(0, cost - discount), 4)

    bal = db.get_bal(uid)
    if uid != ADMIN_ID and bal < cost:
        return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})

    if uid != ADMIN_ID:
        db.sub_bal(uid, cost)

    sched_id = f"SCH{int(time.time())}{secrets.token_hex(3)}"
    _svc_name_ar = _translate_smm(svc.get("name", ""))
    sched_order = {
        "id": sched_id,
        "uid": uid,
        "service_id": sid,
        "service_name": _svc_name_ar,
        "link": link,
        "qty": qty,
        "cost": cost,
        "discount": discount,
        "coupon": coupon_code if discount > 0 else "",
        "comments": comments,
        "schedule_time": schedule_time,
        "created": time.time(),
        "status": "scheduled"
    }
    db.scheduled_orders.append(sched_order)
    db.save()

    _time_str = time.strftime("%Y-%m-%d %H:%M", time.localtime(schedule_time))
    push_user_notif(uid, "system", "تم جدولة طلبك!", f"طلب {_svc_name_ar} سينفذ بتاريخ {_time_str}", "clock")

    return jsonify({
        "ok": True,
        "scheduled": {
            "id": sched_id,
            "service": _svc_name_ar,
            "qty": qty,
            "cost": cost,
            "schedule_time": schedule_time,
            "balance": db.get_bal(uid)
        }
    })

@app.route('/api/order/schedule/cancel', methods=['POST'])
def api_order_schedule_cancel():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    sched_id = data.get("sched_id", "")

    found = None
    for so in db.scheduled_orders:
        if so["id"] == sched_id and so["uid"] == uid and so["status"] == "scheduled":
            found = so
            break

    if not found:
        return jsonify({"ok": False, "error": "لم يتم العثور على الطلب المجدول"})

    found["status"] = "canceled"
    if uid != ADMIN_ID:
        db.add_bal(uid, found["cost"])
    db.save()

    push_user_notif(uid, "system", "تم إلغاء الطلب المجدول", f"تم إرجاع ${found['cost']:.4f} لرصيدك", "times-circle")

    return jsonify({"ok": True, "balance": db.get_bal(uid)})

