@app.route('/api/orders', methods=['POST'])
def api_orders():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    orders = db.get_orders(uid)
    result = []

    for o in reversed(orders):
        cached = o.get("_cached_status", {})
        status = _norm_status(cached.get("status", "")) if cached else "pending"
        sa = {"completed": "done", "processing": "processing", "in progress": "processing",
              "pending": "pending", "partial": "partial", "canceled": "canceled"}.get(status, "pending")

        sid = str(o.get("service_id", ""))
        svc_info = cache.find(sid) if sid else None
        rf_val = str(svc_info.get("refill", "")) if svc_info else ""
        rf_val = rf_val if rf_val and rf_val not in ("0", "False", "false") else ""
        if rf_val.lower() == "true":
            rf_val = "∞"

        _svc_disp = o.get("service", "")
        if _svc_disp and any(c.isascii() and c.isalpha() for c in _svc_disp[:20]):
            _svc_disp = _translate_smm(_svc_disp)
        result.append({
            "id": o["order"],
            "service": _svc_disp,
            "service_id": o.get("service_id", ""),
            "qty": o.get("qty", 0),
            "link": o.get("link", ""),
            "cost": o.get("cost", 0),
            "date": o.get("timestamp", ""),
            "status": sa,
            "start_count": cached.get("start_count", 0) if cached else 0,
            "remains": cached.get("remains", 0) if cached else 0,
            "rf": rf_val,
        })

    def bg_refresh():
        for o in orders:
            ct = o.get("_cached_time", 0)

            # ما نعيد فحص الطلب اللي خلص رجّعنا فلوسه — الباقي (حتى المكتمل) ممكن يتحوّل لجزئي
            if o.get("refunded"):
                continue
            if time.time() - ct > 120:
                try:
                    rec = _status_for_order(o)
                    if isinstance(rec, dict) and rec:
                        o["_cached_status"] = rec
                        o["_cached_time"] = time.time()
                except:
                    pass
    threading.Thread(target=bg_refresh, daemon=True).start()
    return jsonify({"ok": True, "orders": result})

@app.route('/api/orders/all', methods=['POST'])
def api_orders_all():
    """طلباتي الموحّدة — يجمع كل أنواع الطلبات للمستخدم بمكان واحد."""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = str(user['id'])

    def _ts(s):
        try:
            return time.mktime(time.strptime(str(s), "%Y-%m-%d %H:%M:%S"))
        except Exception:
            return 0.0

    items = []

    # 1) طلبات الرشق (SMM)
    try:
        for o in db.get_orders(user['id']):
            cached = o.get("_cached_status", {}) or {}
            st = _norm_status(cached.get("status", ""))
            sa = {"completed": "done", "processing": "processing", "in progress": "processing",
                  "pending": "pending", "partial": "partial", "canceled": "canceled"}.get(st, "pending")
            _disp = o.get("service", "")
            if _disp and any(c.isascii() and c.isalpha() for c in _disp[:20]):
                _disp = _translate_smm(_disp)
            items.append({
                "kind": "smm", "id": o.get("order", ""), "title": _disp,
                "service": _disp, "service_id": o.get("service_id", ""),
                "svc_no": str(o.get("service_id", "")).split(":")[-1].strip(),
                "qty": o.get("qty", 0),
                "link": o.get("link", ""), "cost": o.get("cost", 0), "date": o.get("timestamp", ""),
                "ts": _ts(o.get("timestamp", "")), "status": sa,
                "start_count": cached.get("start_count", 0) if cached else 0,
                "remains": cached.get("remains", 0) if cached else 0,
            })
    except Exception:
        pass

    # 2) الاشتراكات والشحن والسوشيال المخصص
    for oid, o in db.custom_orders.items():
        if str(o.get("uid")) != uid:
            continue
        st = (o.get("status", "pending") or "pending").lower()
        sa = {"completed": "done", "done": "done", "processing": "processing",
              "pending": "pending", "canceled": "canceled", "cancelled": "canceled"}.get(st, "pending")
        otype = o.get("type", "")
        kind = "sub" if otype == "subscription" else ("charge" if otype == "charging" else "smm")
        sub = o.get("package", "") or (("الكمية: " + str(o.get("qty", 0))) if o.get("qty") else "")
        items.append({
            "kind": kind, "id": oid, "title": o.get("service_name", ""),
            "subtitle": sub, "cost": o.get("cost", 0), "date": o.get("date", ""),
            "ts": _ts(o.get("date", "")), "status": sa, "email": o.get("email", ""),
        })

    # 3) الأرقام الوهمية
    for oid, o in db.vn_orders.items():
        if str(o.get("uid")) != uid:
            continue
        st = (o.get("status", "waiting") or "waiting").lower()
        sa = {"received": "done", "active": "processing", "waiting": "processing",
              "cancelled": "canceled", "canceled": "canceled", "expired": "canceled"}.get(st, "processing")
        items.append({
            "kind": "number", "id": oid,
            "title": (o.get("service_name", "") + " — " + o.get("country_name", "")).strip(" —"),
            "subtitle": o.get("phone", "") or "رقم وهمي", "cost": o.get("sell", 0),
            "date": "", "ts": float(o.get("created", 0) or 0), "status": sa,
        })

    # 4) فيزا + توثيق (مخزّنة كتذاكر)
    for tid, t in db.tickets.items():
        if str(t.get("uid")) != uid:
            continue
        closed = (t.get("status", "open") == "closed")
        sa = "done" if closed else "processing"
        if t.get("visa_order"):
            vo = t["visa_order"]
            items.append({
                "kind": "visa", "id": tid, "title": "بطاقة فيزا $" + str(vo.get("amount", "")),
                "subtitle": vo.get("region", "") or "بطاقة افتراضية",
                "cost": vo.get("price_usd", 0), "date": t.get("date", ""),
                "ts": float(t.get("created", 0) or 0), "status": sa, "ticket_id": tid,
            })
        elif t.get("verify_order"):
            vo = t["verify_order"]
            items.append({
                "kind": "verify", "id": tid, "title": "توثيق " + (vo.get("platform", "") or ""),
                "subtitle": vo.get("dur", "") or "حساب موثّق",
                "cost": vo.get("total_usd", 0), "date": t.get("date", ""),
                "ts": float(t.get("created", 0) or 0), "status": sa, "ticket_id": tid,
            })

    items.sort(key=lambda x: x.get("ts", 0), reverse=True)
    return jsonify({"ok": True, "orders": items})

@app.route('/api/order_status', methods=['POST'])
def api_order_status():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False}), 401
    order_id = data.get('order_id','')
    if not order_id:
        return jsonify({"ok": False})
    try:
        uid = user['id']
        found_o = None
        for o in db.get_orders(uid):
            if str(o["order"]) == str(order_id):
                found_o = o
                break
        if not found_o:
            return jsonify({"ok": False})
        rec = _status_for_order(found_o)
        if not isinstance(rec, dict) or not rec:
            return jsonify({"ok": False})

        found_o["_cached_status"] = rec
        found_o["_cached_time"] = time.time()
        status = _norm_status(rec.get("status", ""))
        sa = {"completed": "done", "processing": "processing", "in progress": "processing",
              "pending": "pending", "partial": "partial", "canceled": "canceled"}.get(status, "pending")
        return jsonify({"ok": True, "status": sa, "remains": rec.get("remains",0), "start_count": rec.get("start_count",0)})
    except:
        return jsonify({"ok": False})

@app.route('/api/tickets', methods=['POST'])
def api_tickets():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    tickets = db.tickets
    user_tickets = [t for t in tickets.values() if t.get("uid") == uid]
    user_tickets.sort(key=lambda x: x.get("created", 0), reverse=True)
    result = []
    for t in user_tickets:
        clean_msgs = []
        for m in t.get("messages", []):
            cm = dict(m)
            if cm.get("type") == "voice" and cm.get("data"):
                del cm["data"]
            clean_msgs.append(cm)
        result.append({
            "id": t["id"], "subject": t["subject"], "category": t.get("category", ""),
            "status": t.get("status", "open"), "date": t.get("date", ""),
            "messages": clean_msgs
        })
    return jsonify({"ok": True, "tickets": result})

@app.route('/api/tickets/create', methods=['POST'])
def api_ticket_create():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']

    if check_user_spam(uid, "ticket"):
        return jsonify({"ok": False, "error": "تم حظر حسابك تلقائياً بسبب نشاط مشبوه"})
    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور"})
    subj = data.get("subject", "").strip()
    desc = data.get("description", "").strip()
    cat = data.get("category", "عام")
    if not subj or not desc:
        return jsonify({"ok": False, "error": "عبّي كل الحقول"})
    tid = str(len(db.tickets) + 1)
    now = time.strftime("%d/%m %H:%M")
    db.tickets[tid] = {
        "id": tid, "uid": uid, "subject": subj, "category": cat,
        "status": "open", "date": now, "created": time.time(),
        "messages": [{"from": "user", "text": desc, "time": now}]
    }
    db.save()

    uname = user.get("first_name", "") + " " + user.get("last_name", "")
    try:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("💬 رد على التذكرة", callback_data=f"tk_reply|{tid}"))
        bot.send_message(ADMIN_ID,
            f"🎫 تذكرة جديدة!\n\n"
            f"👤 {uname} (ID: {uid})\n"
            f"📂 {cat}\n"
            f"📋 {subj}\n\n"
            f"📝 {desc}",
            reply_markup=kb)
    except: pass

    push_admin_notif("ticket", {"uid": uid, "subject": subj, "category": cat})

    email_ticket_opened(uid, tid, subj)
    return jsonify({"ok": True, "ticket_id": tid})

