@app.route('/api/tickets/reply', methods=['POST'])
def api_ticket_reply():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    tid = data.get("ticket_id", "")
    msg = data.get("message", "").strip()
    if not msg:
        return jsonify({"ok": False, "error": "empty"})
    tickets = db.tickets
    t = tickets.get(tid)
    if not t or t.get("uid") != user['id']:
        return jsonify({"ok": False, "error": "not found"})
    now = time.strftime("%d/%m %H:%M")
    t["messages"].append({"from": "user", "text": msg, "time": now})
    t["status"] = "waiting"
    db.save()

    try:
        bot.send_message(ADMIN_ID, f"💬 رد جديد على تذكرة #TK-{tid}:\n{msg}")
    except: pass

    push_admin_notif("ticket_reply", {"uid": user['id'], "tid": tid, "msg": msg[:100]})
    return jsonify({"ok": True})

@app.route('/api/tickets/voice', methods=['POST'])
def api_ticket_voice():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    tid = data.get("ticket_id", "")
    audio = data.get("audio", "")
    dur = data.get("duration", 0)
    if not audio or not tid:
        return jsonify({"ok": False, "error": "missing data"})
    if len(audio) > 5_000_000:
        return jsonify({"ok": False, "error": "too large"})
    tickets = db.tickets
    t = tickets.get(tid)
    if not t or t.get("uid") != user['id']:
        return jsonify({"ok": False, "error": "not found"})

    import base64 as _b64
    fname = f"v_{tid}_{uuid.uuid4().hex[:8]}.webm"
    fpath = os.path.join(VOICE_DIR, fname)
    try:
        with open(fpath, "wb") as f:
            f.write(_b64.b64decode(audio))
    except:
        return jsonify({"ok": False, "error": "invalid audio"})
    now = time.strftime("%d/%m %H:%M")
    voice_url = f"/api/voice/{fname}"
    t["messages"].append({"from": "user", "type": "voice", "url": voice_url, "duration": dur, "time": now})
    t["status"] = "waiting"
    db.save()
    try:
        bot.send_message(ADMIN_ID, f"🎤 رسالة صوتية جديدة على تذكرة #TK-{tid} ({dur}ث)")
    except: pass
