@app.route('/api/admin/tickets', methods=['POST'])
def api_admin_tickets():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    _users_idx = {}
    try:
        _wu = _load_web_users()
        for _uname, _u in _wu.items():
            if not isinstance(_u, dict):
                continue
            _info = {"beinty_id": _u.get("beinty_id", ""), "name": _u.get("name", "") or _uname}
            _wuid = _u.get("uid", "")
            if _wuid:
                _users_idx[str(_wuid)] = _info
            _tg = _u.get("telegram_id")
            if _tg:
                _users_idx[str(_tg)] = _info
    except: pass
    result = []
    for t in sorted(db.tickets.values(), key=lambda x: x.get("created", 0), reverse=True):
        clean_msgs = []
        for m in t.get("messages", []):
            cm = dict(m)
            if cm.get("type") == "voice" and cm.get("data"):
                del cm["data"]
            clean_msgs.append(cm)
        _user_info = _users_idx.get(str(t["uid"]), {})
        result.append({
            "id": t["id"], "uid": t["uid"], "subject": t["subject"],
            "category": t.get("category", ""), "status": t.get("status", "open"),
            "date": t.get("date", ""), "messages": clean_msgs,
            "msg_count": len(t.get("messages", [])),
            "user_beinty_id": _user_info.get("beinty_id", ""),
            "user_name": _user_info.get("name", ""),
        })
    return jsonify({"ok": True, "tickets": result})

