@app.route('/api/ticket_img/<fname>')
def serve_ticket_img(fname):
    import re as _re2
    if not _re2.match(r'^[a-zA-Z0-9_\-]+\.(jpg|png|webp)$', fname):
        return "not found", 404
    fpath = os.path.join(TICKET_IMG_DIR, fname)
    if not os.path.exists(fpath):
        return "not found", 404
    mime = 'image/jpeg'
    if fname.endswith('.png'): mime = 'image/png'
    elif fname.endswith('.webp'): mime = 'image/webp'
    return send_file(fpath, mimetype=mime)

@app.route('/api/voice/<fname>')
def serve_voice(fname):
    import re as _re2
    if not _re2.match(r'^[a-zA-Z0-9_\-]+\.webm$', fname):
        return "not found", 404
    fpath = os.path.join(VOICE_DIR, fname)
    if not os.path.exists(fpath):
        return "not found", 404
    return send_file(fpath, mimetype='audio/webm')

