@app.route('/api/landing-stats')
def api_landing_stats():

    try:
        web_users = _web_users_ro()   # PERF FIX #6
        web_count = len([u for u in web_users if u != "admin"])
        tg_only = len([s for s in db.subscribers if s != ADMIN_ID and not any(
            wu.get("telegram_id") == s for wu in web_users.values()
        )])
        total_users = web_count + tg_only + 1500
        total_orders = db.total_orders() + len(db.custom_orders) + 3000
        _hidden_ls = _hidden_plats_set()
        try:
            _base_svcs = cache.all_services or []
            if _hidden_ls:
                _base_svcs = [s for s in _base_svcs if (s.get("plat", "") or "").strip().lower() not in _hidden_ls]
            base_svc_count = len(_base_svcs)
        except:
            base_svc_count = 0
        try:
            _agg_svcs = agg_cache.services or []
            if _hidden_ls:
                _agg_svcs = [s for s in _agg_svcs if (s.get("plat", "") or "").strip().lower() not in _hidden_ls]
            agg_svc_count = len(_agg_svcs)
        except:
            agg_svc_count = 0
        total_services = base_svc_count + agg_svc_count
        base_plats = set()
        try:
            for p in (cache.platforms or []):
                if (p or "").strip().lower() not in _hidden_ls:
                    base_plats.add(p)
            for p in (agg_cache.platforms or []):
                if (p or "").strip().lower() not in _hidden_ls:
                    base_plats.add(p)
        except: pass
        total_platforms = len(base_plats)
        return jsonify({
            "users": total_users,
            "orders": total_orders,
            "services": total_services,
            "platforms": total_platforms
        })
    except:
        return jsonify({"users": 0, "orders": 0, "services": 0, "platforms": 0})

@app.route('/api/admin/stats', methods=['POST'])
def api_admin_stats():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    web_users = _load_web_users()
    web_count = len([u for u in web_users if u != "admin"])
    tg_only = len([s for s in db.subscribers if s != ADMIN_ID and not any(
        wu.get("telegram_id") == s for wu in web_users.values()
    )])
    total_users = web_count + tg_only
    total_orders = db.total_orders()

    total_orders += len(db.custom_orders)
    total_balance = sum(db.balances.values())
    pending_recharges = sum(1 for r in db.recharge_requests.values() if r.get("status")=="pending")
    open_tickets = sum(1 for t in db.tickets.values() if t.get("status") in ("open","waiting"))
    total_revenue = sum(r.get("usd",0) for r in db.recharge_requests.values() if r.get("status")=="done")
    pending_sub_orders = len([o for o in db.custom_orders.values() if o.get("status")=="pending"])
    return jsonify({"ok": True, "stats": {
        "users": total_users, "orders": total_orders, "balance": round(total_balance,2),
        "pending_recharges": pending_recharges, "open_tickets": open_tickets, "revenue": round(total_revenue,2),
        "pending_sub_orders": pending_sub_orders
    }})

def send_wa(phone, message):

    try:

        try:
            nm = _site_name()
            if nm != "Beinty":
                message = message.replace("Beinty", nm)
        except: pass
        try:
            _dom = WEBAPP_URL.split("//", 1)[-1].rstrip("/")
            if _dom and _dom != "kony.store":
                message = message.replace("kony.store", _dom)
        except: pass
        phone = str(phone).strip().replace('+', '')
        if phone.startswith('07'):
            phone = '964' + phone[1:]
        elif phone.startswith('7'):
            phone = '964' + phone
        _ultra_instance = _setting("ultra_instance", ULTRA_INSTANCE)
        _ultra_token    = _setting("ultra_token", ULTRA_TOKEN)
        resp = requests.post(f"https://api.ultramsg.com/{_ultra_instance}/messages/chat", data={
            "token": _ultra_token,
            "to": f"+{phone}",
            "body": message,
            "priority": "10"
        }, timeout=10)
        print(f"[WA] Sent to {phone[:6]}***: {resp.status_code}")
        return resp.status_code == 200
    except Exception as e:
        print(f"[WA] Error: {e}")
        return False

