def get_user_phone(uid):

    uid_str = str(uid)
    latest_phone = None
    latest_time = 0
    for ref, req in db.asiacell_requests.items():
        if str(req.get('uid','')) == uid_str or str(req.get('web_uid','')) == uid_str:
            phone = req.get('phone','')
            if phone:
                req_time = req.get('expires', 0)
                if req_time > latest_time:
                    latest_time = req_time
                    latest_phone = phone
    return latest_phone

ADMIN_NOTIFS = []

def _resolve_push_username(uid):

    try:
        wu = _load_web_users() or {}
        for uname, udata in wu.items():
            if uname == "admin": continue
            if str(udata.get("uid","")) == str(uid) or str(udata.get("id","")) == str(uid):
                return udata.get("name", uname) or uname
        return str(uid)[:12]
    except:
        return str(uid)[:12]

def push_admin_notif(ntype, data):

    ADMIN_NOTIFS.append({"type": ntype, "data": data, "time": time.time()})
    while len(ADMIN_NOTIFS) > 50:
        ADMIN_NOTIFS.pop(0)

    title = ""
    body = ""
    d = data if isinstance(data, dict) else {}
    try:
        if ntype == "order":
            oid = d.get("order_id", "")
            uname = d.get("name", "") or _resolve_push_username(d.get("uid", ""))
            svc = d.get("service", "")
            cost = d.get("cost", 0)
            uid = d.get("uid", "")
            bal = 0
            try: bal = db.get_bal(uid)
            except: pass
            title = f"📦 طلب جديد #{oid}" if oid else "📦 طلب جديد"
            body = f"{uname} — {svc}\nالتكلفة: ${cost:.2f} | الرصيد: ${bal:.2f}"

        elif ntype == "recharge":
            usd = d.get("usd", 0)
            uname = d.get("name", "") or _resolve_push_username(d.get("uid", ""))
            method = d.get("method", "")
            ref = d.get("ref", "")
            uid = d.get("uid", "")
            bal = 0
            try: bal = db.get_bal(uid)
            except: pass
            title = f"💰 طلب شحن — ${usd:.2f}"
            body = f"{uname} عبر {method}"
            if ref:
                body += f"\n{ref} | رصيده: ${bal:.2f}"

        elif ntype == "ticket":
            uname = _resolve_push_username(d.get("uid", ""))
            cat = d.get("category", "")
            subj = d.get("subject", "")
            title = f"🎫 تذكرة جديدة — {cat}" if cat else "🎫 تذكرة جديدة"
            body = f"{uname}\n{subj}"

        elif ntype == "ticket_reply":
            uname = _resolve_push_username(d.get("uid", ""))
            tid = d.get("tid", "")
            msg = d.get("msg", "")
            title = f"💬 رد على تذكرة #TK-{tid}" if tid else "💬 رد على تذكرة"
            body = f"{uname}: {msg}"

        elif ntype == "user":
            uname = d.get("username", "")
            email = d.get("email", "")

            today_count = 0
            total_count = 0
            try:
                wu = _load_web_users() or {}
                today_str = time.strftime("%Y-%m-%d")
                total_count = len([u for u in wu if u != "admin"])
                today_count = sum(1 for u in wu.values() if str(u.get("created","")).startswith(today_str))
            except: pass
            title = f"👤 {uname} سجّل الآن"
            body = f"{email}\nاليوم: {today_count} تسجيل | الكلي: {total_count:,}"

        elif ntype == "system":
            title = "⚠️ تنبيه النظام"
            body = d.get("text", "") or d.get("msg", "") or str(data)

        else:
            title = f"🔔 {ntype}"
            body = d.get("text", "") or d.get("msg", "") or str(data)
    except Exception as e:
        title = title or f"🔔 {ntype}"
        body = body or str(data)

    admin_sub = db.push_subs.get(str(ADMIN_ID)) or db.push_subs.get(ADMIN_ID)
    if admin_sub:
        threading.Thread(target=_send_push, args=(admin_sub, title, body, '/app'), daemon=True).start()

