@app.route('/api/admin/payment_methods/update', methods=['POST'])
def api_admin_update_pm():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or str(user['id']) != str(ADMIN_ID):
        return jsonify({"ok": False}), 403
    old_name = data.get('old_name','')
    new_name = data.get('new_name','').strip()
    rate = data.get('rate',0)
    number = data.get('number','').strip()
    if not new_name or not number:
        return jsonify({"ok": False, "error": "missing fields"})
    old_info = db.payment_methods.get(old_name, {})
    if old_name in db.payment_methods:
        del db.payment_methods[old_name]
    icon = data.get('icon', '') or old_info.get('icon', '')
    notes = data.get('notes', old_info.get('notes', ''))
    db.payment_methods[new_name] = {"rate": float(rate), "number": number, "info": f"أرسل إلى {new_name}: {number}", "icon": icon, "notes": notes}
    db.save()
    return jsonify({"ok": True})

