@app.route('/api/admin/announcements/add', methods=['POST'])
def api_admin_add_ann():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403

    if data.get("text") and not data.get("title"):
        text = data.get("text", "").strip()
        if not text: return jsonify({"ok": False})
        ann = {
            "id": f"ann_{int(time.time())}_{secrets.token_hex(2)}",
            "enabled": True,
            "eyebrow": "إعلان",
            "title": text[:50] + ("..." if len(text) > 50 else ""),
            "emoji": "📢",
            "tag_text": "جديد",
            "tag_color": "green",
            "sections": [{"icon": "fas fa-bullhorn", "color": "blue", "label": "الإعلان", "content": text}],
            "cta_text": "اطّلع",
            "cta_icon": "fas fa-arrow-left",
            "cta_link": "",
            "show_once": True,
            "send_push": data.get("send_push", True),
            "expires_at": "",
            "type": data.get("type", "info"),
            "date": time.strftime("%Y-%m-%d %H:%M")
        }
    else:

        title = (data.get("title") or "").strip()
        if not title: return jsonify({"ok": False, "error": "title_required"})
        ann = {
            "id": f"ann_{int(time.time())}_{secrets.token_hex(2)}",
            "enabled": bool(data.get("enabled", True)),
            "eyebrow": (data.get("eyebrow") or "إعلان رسمي").strip()[:40],
            "title": title[:80],
            "emoji": (data.get("emoji") or "🌟")[:8],
            "tag_text": (data.get("tag_text") or "").strip()[:20],
            "tag_color": data.get("tag_color", "green"),
            "sections": data.get("sections", []) or [],
            "cta_text": (data.get("cta_text") or "اطّلع").strip()[:30],
            "cta_icon": (data.get("cta_icon") or "fas fa-bolt").strip()[:40],
            "cta_link": (data.get("cta_link") or "").strip()[:200],
            "show_once": bool(data.get("show_once", True)),
            "send_push": bool(data.get("send_push", True)),
            "expires_at": (data.get("expires_at") or "").strip(),
            "type": "popup_new",
            "date": time.strftime("%Y-%m-%d %H:%M")
        }

    db.announcements.insert(0, ann)

    db.announcements = db.announcements[:20]
    db.save()

    if ann.get("send_push", True):
        push_title = f"📢 {ann.get('title', 'إعلان جديد')}"
        push_body = ""
        secs = ann.get("sections") or []
        if secs and isinstance(secs[0], dict):
            push_body = (secs[0].get("content") or "")[:140]
        if not push_body:
            push_body = ann.get("title", "")

        import re as _re
        push_body = _re.sub(r'<[^>]+>', '', push_body)
        for sub_uid, sub in list(db.push_subs.items()):
            threading.Thread(target=_send_push, args=(sub, push_title, push_body, '/app'), daemon=True).start()

    return jsonify({"ok": True, "ann": ann})

@app.route('/api/admin/announcements/toggle', methods=['POST'])
def api_admin_toggle_ann():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    aid = data.get("id", "")
    enabled = bool(data.get("enabled", True))
    for a in db.announcements:
        if a.get("id") == aid:
            a["enabled"] = enabled
            db.save()
            return jsonify({"ok": True})
    return jsonify({"ok": False, "error": "not_found"})

def _ensure_default_tiktok_packages():

    if not db.tiktok_packages:
        defaults = [
            {"coins": 30, "price_usd": 0.45, "price_iqd": 650},
            {"coins": 100, "price_usd": 1.49, "price_iqd": 2000},
            {"coins": 350, "price_usd": 4.99, "price_iqd": 6500},
            {"coins": 700, "price_usd": 9.99, "price_iqd": 13500, "popular": True},
            {"coins": 1400, "price_usd": 19.99, "price_iqd": 27000},
            {"coins": 3500, "price_usd": 49.99, "price_iqd": 67500, "best_value": True},
            {"coins": 7000, "price_usd": 99.99, "price_iqd": 135000},
            {"coins": 17500, "price_usd": 249.99, "price_iqd": 337500},
        ]
        for i, p in enumerate(defaults):
            db.tiktok_packages.append({
                "id": f"ttpkg_{int(time.time())}_{i}",
                "coins": p["coins"],
                "price_usd": p["price_usd"],
                "price_iqd": p["price_iqd"],
                "badge_text": "",
                "popular": p.get("popular", False),
                "best_value": p.get("best_value", False),
                "active": True,
                "order": i
            })
        db.save()

