@app.route('/api/admin/tiktok/packages/add', methods=['POST'])
def api_admin_tiktok_pkg_add():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    try:
        coins = int(data.get("coins", 0))
        price_usd = float(data.get("price_usd", 0))
        price_iqd = int(float(data.get("price_iqd", 0)))
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "قيم غير صالحة"})
    if coins <= 0: return jsonify({"ok": False, "error": "عدد العملات إلزامي"})
    max_order = max([p.get("order", 0) for p in db.tiktok_packages] or [-1]) + 1
    pkg = {
        "id": f"ttpkg_{int(time.time())}_{secrets.token_hex(2)}",
        "coins": coins,
        "price_usd": price_usd,
        "price_iqd": price_iqd,
        "badge_text": (data.get("badge_text") or "").strip()[:20],
        "popular": bool(data.get("popular", False)),
        "best_value": bool(data.get("best_value", False)),
        "active": bool(data.get("active", True)),
        "order": max_order
    }
    db.tiktok_packages.append(pkg)
    db.save()
    return jsonify({"ok": True, "package": pkg})

@app.route('/api/admin/tiktok/packages/edit', methods=['POST'])
def api_admin_tiktok_pkg_edit():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    pid = data.get("id", "")
    for p in db.tiktok_packages:
        if p.get("id") == pid:
            try:
                if "coins" in data: p["coins"] = int(data["coins"])
                if "price_usd" in data: p["price_usd"] = float(data["price_usd"])
                if "price_iqd" in data: p["price_iqd"] = int(float(data["price_iqd"]))
            except (ValueError, TypeError):
                return jsonify({"ok": False, "error": "قيم غير صالحة"})
            if "badge_text" in data: p["badge_text"] = (data["badge_text"] or "").strip()[:20]
            if "popular" in data: p["popular"] = bool(data["popular"])
            if "best_value" in data: p["best_value"] = bool(data["best_value"])
            if "active" in data: p["active"] = bool(data["active"])
            db.save()
            return jsonify({"ok": True, "package": p})
    return jsonify({"ok": False, "error": "غير موجود"})

