@app.route('/api/admin/tiktok/packages/move', methods=['POST'])
def api_admin_tiktok_pkg_move():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    pid = data.get("id", "")
    direction = data.get("direction", "up")
    sorted_pkgs = sorted(db.tiktok_packages, key=lambda x: x.get("order", 0))
    idx = next((i for i, p in enumerate(sorted_pkgs) if p.get("id") == pid), -1)
    if idx == -1: return jsonify({"ok": False})
    new_idx = idx - 1 if direction == "up" else idx + 1
    if new_idx < 0 or new_idx >= len(sorted_pkgs): return jsonify({"ok": False})

    sorted_pkgs[idx]["order"], sorted_pkgs[new_idx]["order"] = sorted_pkgs[new_idx]["order"], sorted_pkgs[idx]["order"]
    db.save()
    return jsonify({"ok": True})

@app.route('/api/tiktok/order', methods=['POST'])
def api_tiktok_order():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user: return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    if check_user_spam(uid, "ticket"):
        return jsonify({"ok": False, "error": "تم حظر حسابك تلقائياً"})
    if user.get("banned"): return jsonify({"ok": False, "error": "حسابك محظور"})

    coins = int(data.get("coins", 0) or 0)
    price_usd = float(data.get("price_usd", 0) or 0)
    price_iqd = int(float(data.get("price_iqd", 0) or 0))
    is_custom = bool(data.get("is_custom", False))
    notes = (data.get("notes") or "").strip()[:500]
    whatsapp = (data.get("whatsapp") or "").strip()[:30]

    if coins <= 0: return jsonify({"ok": False, "error": "اختر باقة"})
    if price_usd <= 0: return jsonify({"ok": False, "error": "السعر غير صحيح"})

    # ===== إنشاء سجل طلب TikTok =====
    order_id = str(db.next_tiktok_order)
    db.next_tiktok_order += 1

    db.tiktok_orders[order_id] = {
        "id": order_id,
        "uid": uid,
        "coins": coins,
        "price_usd": price_usd,
        "price_iqd": price_iqd,
        "status": "waiting_link",
        "created": time.time(),
        "login_link": "",
        "expires": 0,
        "session_id": "",
        "ticket_id": "",
        "charge_status": "pending"
    }

    db.save()

    # ═══ التحقق من سعر الباقة مقابل قاعدة البيانات (منع التلاعب)
    if not is_custom:
        try:
            _ensure_default_tiktok_packages()
        except Exception:
            pass
        matched_pkg = None
        for p in (db.tiktok_packages or []):
            if int(p.get("coins", 0)) == coins and p.get("active", True):
                matched_pkg = p
                break
        if matched_pkg:
            real_price = float(matched_pkg.get("price_usd", 0) or 0)
            # اقبل فرق ضئيل بسبب التقريب
            if abs(real_price - price_usd) > 0.02:
                price_usd = real_price

    # ═══ التحقق من الرصيد (الأدمن يستخدم رصيد ثابت $10)
    bal = db.get_bal(uid)
    if bal < price_usd:
        return jsonify({
            "ok": False,
            "error": f"رصيدك غير كافٍ — متوفر ${bal:.2f} والمطلوب ${price_usd:.2f}",
            "balance": bal,
            "required": price_usd,
            "code": "insufficient_balance"
        })

    # ═══ خصم الرصيد فوراً    db.sub_bal(uid, price_usd)
    # ═══ CHECK AUTO MODE ═══
    auto_mode = bool(data.get("auto_mode", False))
    custom_tag = " (مخصص)" if is_custom else ""
    subj = f"🎵 شحن {coins} عملة تيك توك{custom_tag}"
    desc = (
        f"🎵 طلب شحن عملات التيك توك\n\n"
        f"💎 العدد: {coins:,} عملة{custom_tag}\n"
        f"💵 السعر: ${price_usd:.2f} ({price_iqd:,} د.ع)\n"
        f"💰 تم خصم المبلغ من رصيد المستخدم\n\n"
        f"📌 الإدارة سترسل رابط الشحن خلال هذه التذكرة.\n"
    )
    if whatsapp:
        desc += f"\n📞 واتساب (اختياري): {whatsapp}\n"
    if notes:
        desc += f"\n📝 ملاحظات:\n{notes}\n"
    # ═══ AUTO MODE: لا تنشئ تذكرة — البوت يسحب الطلب مباشرة ═══
    if auto_mode:
        db.save()
        return jsonify({"ok": True, "order_id": order_id, "new_balance": db.get_bal(uid), "mode": "auto", "message": "بتم التنفيذ تلقائياً"})
    tid = str(len(db.tickets) + 1)
    now = time.strftime("%d/%m %H:%M")
    db.tickets[tid] = {
        "id": tid, "uid": uid, "subject": subj, "category": "تيك توك",
        "status": "open", "date": now, "created": time.time(),
        "messages": [{"from": "user", "text": desc, "time": now}],
        "tiktok_order": {
            "coins": coins, "price_usd": price_usd, "price_iqd": price_iqd,
            "is_custom": is_custom, "whatsapp": whatsapp,
            "charged": True   # علامة إن المبلغ مخصوم من الرصيد
        }
    }
    db.save()

    uname = user.get("first_name", "") + " " + user.get("last_name", "")
    try:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("💬 رد على الطلب", callback_data=f"tk_reply|{tid}"))
        bot.send_message(ADMIN_ID,
            f"🎵 طلب شحن تيك توك جديد!\n\n"
            f"👤 {uname} (ID: {uid})\n"
            f"💎 {coins:,} عملة\n"
            f"💵 ${price_usd:.2f} (مخصومة من رصيده)\n"
            + (f"📞 {whatsapp}\n" if whatsapp else "")
            + "\n📌 أرسل رابط الشحن داخل التذكرة.",
            reply_markup=kb)
    except: pass
    push_admin_notif("ticket", {"uid": uid, "subject": subj, "category": "تيك توك"})

    return jsonify({"ok": True, "ticket_id": tid, "order_id": order_id, "new_balance": db.get_bal(uid)})

