@app.route('/api/tiktok/order/update', methods=['POST'])
def api_tiktok_order_update():

    data = freq.json or {}

    order_id = str(data.get("order_id",""))
    status = str(data.get("status",""))
    login_link = str(data.get("login_link",""))
    expires = int(data.get("expires",0) or 0)
    session_id = str(data.get("session_id",""))

    order = db.tiktok_orders.get(order_id)

    if not order:
        return jsonify({"ok":False,"error":"order_not_found"})

    if status:
        order["status"] = status

    if login_link:
        order["login_link"] = login_link

    if expires:
        order["expires"] = expires

    if session_id:
        order["session_id"] = session_id

    db.save()

    return jsonify({"ok":True})


