@app.route('/api/admin/visa/cards/add', methods=['POST'])
def api_admin_visa_card_add():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    try:
        amount = float(data.get("amount", 0))
        price_usd = float(data.get("price_usd", 0))
        tier = int(data.get("tier", 1))
        validity_months = int(data.get("validity_months", 12))
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "قيم غير صالحة"})
    if amount <= 0: return jsonify({"ok": False, "error": "قيمة البطاقة إلزامية"})
    if price_usd <= 0: return jsonify({"ok": False, "error": "السعر إلزامي"})
    image = (data.get("image") or "").strip()
    if image and len(image) > 4 * 1024 * 1024:
        return jsonify({"ok": False, "error": "الصورة كبيرة جداً (الحد الأقصى 3MB)"})
    if image and not image.startswith("data:image/"):
        image = ""
    max_order = max([c.get("order", 0) for c in db.visa_cards] or [-1]) + 1
    card = {
        "id": f"visa_{int(time.time())}_{secrets.token_hex(2)}",
        "name": (data.get("name") or "").strip()[:50],
        "amount": amount,
        "price_usd": price_usd,
        "tier": max(1, min(6, tier)),
        "region": (data.get("region") or "USA").strip()[:30],
        "validity_months": max(1, min(60, validity_months)),
        "details": (data.get("details") or "").strip()[:2000],
        "badge_text": (data.get("badge_text") or "").strip()[:20],
        "image": image,
        "popular": bool(data.get("popular", False)),
        "best_value": bool(data.get("best_value", False)),
        "active": bool(data.get("active", True)),
        "order": max_order
    }
    db.visa_cards.append(card)
    db.save()
    return jsonify({"ok": True, "card": card})

@app.route('/api/admin/visa/cards/edit', methods=['POST'])
def api_admin_visa_card_edit():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    cid = data.get("id", "")
    for c in db.visa_cards:
        if c.get("id") == cid:
            try:
                if "amount" in data: c["amount"] = float(data["amount"])
                if "price_usd" in data: c["price_usd"] = float(data["price_usd"])
                if "tier" in data: c["tier"] = max(1, min(6, int(data["tier"])))
                if "validity_months" in data: c["validity_months"] = max(1, min(60, int(data["validity_months"])))
            except (ValueError, TypeError):
                return jsonify({"ok": False, "error": "قيم غير صالحة"})
            if "region" in data: c["region"] = (data["region"] or "").strip()[:30]
            if "name" in data: c["name"] = (data["name"] or "").strip()[:50]
            if "details" in data: c["details"] = (data["details"] or "").strip()[:2000]
            if "badge_text" in data: c["badge_text"] = (data["badge_text"] or "").strip()[:20]
            if "image" in data:
                img = (data["image"] or "").strip()
                if img and len(img) > 4 * 1024 * 1024:
                    return jsonify({"ok": False, "error": "الصورة كبيرة جداً (الحد الأقصى 3MB)"})
                if img and not img.startswith("data:image/"):
                    img = ""
                c["image"] = img
            if "popular" in data: c["popular"] = bool(data["popular"])
            if "best_value" in data: c["best_value"] = bool(data["best_value"])
            if "active" in data: c["active"] = bool(data["active"])
            db.save()
            return jsonify({"ok": True, "card": c})
    return jsonify({"ok": False, "error": "البطاقة غير موجودة"})

