# ═══════════════════════════════════════════════════════════════
#  قسم توثيق الحسابات (Account Verification)
#  منصات يحددها الأدمن، كل منصة باقات (مدّة + سعر)
#  نوعان: حساب موثّق جاهز / توثيق الحساب الشخصي → كلاهما يفتح تذكرة
# ═══════════════════════════════════════════════════════════════
VERIFY_READY_DEFAULT_NOTE = ("حساب موثّق رسمياً بالعلامة الزرقاء وجاهز للاستلام فوراً — أرخص وأسرع من توثيق "
                             "حسابك الشخصي، ومثالي إذا تريد حساب موثّق جاهز للشغل بسرعة.")
VERIFY_READY_DEFAULT_FEATURES = [
    "موثّق بالعلامة الزرقاء الرسمية وجاهز للاستلام",
    "تسليم فوري بدون انتظار إجراءات التوثيق",
    "حساب نظيف وآمن وبدون أي مخالفات",
    "تستلم بيانات الحساب كاملة (إيميل + كلمة المرور)",
    "ضمان استبدال عند أي مشكلة بالتسليم",
]

def _ensure_default_verify_platforms():
    if not db.verify_platforms:
        defaults = [
            {"key": "instagram", "name": "إنستغرام", "icon": "fab fa-instagram", "color": "#E1306C", "hot": True, "renew_usd": 4.5, "ready_price": 18.0,
             "packs": [{"dur": "شهر واحد", "price_usd": 25.0, "badge": ""},
                       {"dur": "شهرين", "price_usd": 45.0, "badge": "الأكثر طلباً"},
                       {"dur": "٣ أشهر", "price_usd": 60.0, "badge": ""}]},
            {"key": "tiktok", "name": "تيك توك", "icon": "fab fa-tiktok", "color": "#000000", "hot": True, "renew_usd": 4.0, "ready_price": 16.0,
             "packs": [{"dur": "شهر واحد", "price_usd": 22.0, "badge": ""},
                       {"dur": "شهرين", "price_usd": 40.0, "badge": ""},
                       {"dur": "٣ أشهر", "price_usd": 55.0, "badge": "أفضل قيمة"}]},
            {"key": "facebook", "name": "فيسبوك", "icon": "fab fa-facebook-f", "color": "#1877F2", "hot": False, "renew_usd": 4.5, "ready_price": 12.0,
             "packs": [{"dur": "شهر واحد", "price_usd": 20.0, "badge": ""},
                       {"dur": "٣ أشهر", "price_usd": 50.0, "badge": ""}]},
            {"key": "x", "name": "منصة X", "icon": "fab fa-x-twitter", "color": "#000000", "hot": False, "renew_usd": 3.5, "ready_price": 10.0,
             "packs": [{"dur": "شهر واحد", "price_usd": 18.0, "badge": ""},
                       {"dur": "٣ أشهر", "price_usd": 45.0, "badge": ""}]},
        ]
        for i, p in enumerate(defaults):
            packs = []
            for pk in p["packs"]:
                packs.append({"id": "vp_" + secrets.token_hex(3), "dur": pk["dur"],
                              "price_usd": float(pk["price_usd"]), "badge": pk.get("badge", "")})
            db.verify_platforms.append({
                "id": "vfp_%d_%d" % (int(time.time()), i),
                "key": p["key"], "name": p["name"], "icon": p["icon"], "color": p["color"],
                "hot": p.get("hot", False), "active": True, "order": i, "group": "social",
                "renew_usd": float(p.get("renew_usd", 0) or 0),
                "ready": {"enabled": True, "price_usd": float(p.get("ready_price", 0) or 0),
                          "note": VERIFY_READY_DEFAULT_NOTE, "features": list(VERIFY_READY_DEFAULT_FEATURES)},
                "packs": packs
            })
        db.save()

def _vf_ready_norm(p):
    r = p.get("ready") or {}
    if not isinstance(r, dict):
        r = {}
    try:
        rp = float(r.get("price_usd", 0) or 0)
    except (ValueError, TypeError):
        rp = 0.0
    feats = [str(x).strip() for x in (r.get("features") or []) if str(x).strip()]
    return {
        "enabled": bool(r.get("enabled", False)) and rp > 0,
        "price_usd": rp,
        "note": str(r.get("note", "") or "")[:600],
        "features": feats[:12],
    }

def _vf_public_platforms():
    _ensure_default_verify_platforms()
    out = []
    for p in sorted(db.verify_platforms, key=lambda x: x.get("order", 0)):
        if not p.get("active", True):
            continue
        packs = [pk for pk in p.get("packs", []) if pk.get("active", True) is not False]
        ready = _vf_ready_norm(p)
        if not packs and not ready["enabled"]:
            continue
        q = dict(p)
        q["packs"] = packs
        q["ready"] = ready
        q["group"] = "other" if p.get("group") == "other" else "social"
        out.append(q)
    return out

