def _vf_sanitize_packs(raw):
    packs = []
    for pk in (raw or []):
        try:
            dur = str(pk.get("dur", "")).strip()[:40]
            price = float(pk.get("price_usd", 0) or 0)
        except (ValueError, TypeError):
            continue
        if not dur or price <= 0:
            continue
        packs.append({
            "id": str(pk.get("id") or ("vp_" + secrets.token_hex(3))),
            "dur": dur, "price_usd": price,
            "badge": str(pk.get("badge", "")).strip()[:20],
            "active": bool(pk.get("active", True))
        })
    return packs

def _vf_sanitize_ready(raw):
    r = raw if isinstance(raw, dict) else {}
    try:
        price = float(r.get("price_usd", 0) or 0)
    except (ValueError, TypeError):
        price = 0.0
    if price < 0:
        price = 0.0
    feats = []
    for f in (r.get("features") or []):
        s = str(f).strip()[:120]
        if s:
            feats.append(s)
        if len(feats) >= 12:
            break
    return {
        "enabled": bool(r.get("enabled", False)) and price > 0,
        "price_usd": price,
        "note": str(r.get("note", "") or "").strip()[:600],
        "features": feats,
    }

@app.route('/api/admin/verify/platform/save', methods=['POST'])
def api_admin_verify_platform_save():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    name = (data.get("name") or "").strip()[:50]
    if not name:
        return jsonify({"ok": False, "error": "اسم المنصة إلزامي"})
    icon = (data.get("icon") or "fas fa-circle-check").strip()[:60]
    color = (data.get("color") or "#06b6d4").strip()[:20]
    image = (data.get("image") or "").strip()
    if image and not image.startswith("data:image/"):
        image = ""
    image = image[:1500000]
    active = bool(data.get("active", True))
    hot = bool(data.get("hot", False))
    try:
        renew_usd = float(data.get("renew_usd", 0) or 0)
        if renew_usd < 0:
            renew_usd = 0.0
    except (ValueError, TypeError):
        renew_usd = 0.0
    group = "other" if (data.get("group") == "other") else "social"
    ready = _vf_sanitize_ready(data.get("ready"))
    packs = _vf_sanitize_packs(data.get("packs"))
    if not packs and not ready["enabled"]:
        return jsonify({"ok": False, "error": "أضف باقة توثيق واحدة على الأقل أو فعّل الحساب الجاهز بسعر"})
    pid = data.get("id", "")
    for p in db.verify_platforms:
        if p.get("id") == pid:
            p["name"] = name; p["icon"] = icon; p["color"] = color
            p["image"] = image
            p["active"] = active; p["hot"] = hot; p["renew_usd"] = renew_usd
            p["group"] = group; p["ready"] = ready; p["packs"] = packs
            db.save()
            return jsonify({"ok": True, "platform": p})
    max_order = max([p.get("order", 0) for p in db.verify_platforms] or [-1]) + 1
    plat = {
        "id": "vfp_%d_%s" % (int(time.time()), secrets.token_hex(2)),
        "key": "", "name": name, "icon": icon, "color": color, "image": image,
        "hot": hot, "active": active, "order": max_order, "renew_usd": renew_usd,
        "group": group, "ready": ready, "packs": packs
    }
    db.verify_platforms.append(plat)
    db.save()
    return jsonify({"ok": True, "platform": plat})

