@app.route('/api/admin/verify/country-fees', methods=['POST'])
def api_admin_verify_country_fees():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    fees = data.get("fees") or {}
    valid = {c["code"] for c in VERIFY_COUNTRIES}
    cur = getattr(db, "verify_country_fees", None)
    if not isinstance(cur, dict):
        cur = {}
    for k, v in fees.items():
        kk = str(k).strip().upper()
        if kk in valid:
            try:
                fv = float(v)
                cur[kk] = fv if fv > 0 else 0.0
            except Exception:
                pass
    db.verify_country_fees = cur
    db.save()
    return jsonify({"ok": True, "countries": _verify_country_list()})

# قائمة دول التوثيق + رسوم التأهيل (المصدر الموثوق للحساب — الواجهة تعكسها فقط)
VERIFY_COUNTRIES = [
    {"code": "IQ", "ar": "العراق", "en": "Iraq", "flag": "🇮🇶", "fee": 0},
    {"code": "SA", "ar": "السعودية", "en": "Saudi Arabia", "flag": "🇸🇦", "fee": 0},
    {"code": "AE", "ar": "الإمارات", "en": "UAE", "flag": "🇦🇪", "fee": 0},
    {"code": "EG", "ar": "مصر", "en": "Egypt", "flag": "🇪🇬", "fee": 0},
    {"code": "JO", "ar": "الأردن", "en": "Jordan", "flag": "🇯🇴", "fee": 0},
    {"code": "KW", "ar": "الكويت", "en": "Kuwait", "flag": "🇰🇼", "fee": 0},
    {"code": "QA", "ar": "قطر", "en": "Qatar", "flag": "🇶🇦", "fee": 0},
    {"code": "MA", "ar": "المغرب", "en": "Morocco", "flag": "🇲🇦", "fee": 0},
    {"code": "DZ", "ar": "الجزائر", "en": "Algeria", "flag": "🇩🇿", "fee": 0},
    {"code": "SD", "ar": "السودان", "en": "Sudan", "flag": "🇸🇩", "fee": 5},
    {"code": "SY", "ar": "سوريا", "en": "Syria", "flag": "🇸🇾", "fee": 5},
    {"code": "IR", "ar": "إيران", "en": "Iran", "flag": "🇮🇷", "fee": 5},
]


def _verify_country(code):
    code = (code or "").strip().upper()
    for c in VERIFY_COUNTRIES:
        if c["code"] == code:
            return c
    return None


def _verify_fee_map():
    base = {c["code"]: float(c["fee"]) for c in VERIFY_COUNTRIES}
    try:
        ov = getattr(db, "verify_country_fees", None) or {}
        for k, v in ov.items():
            kk = str(k).strip().upper()
            if kk in base:
                try:
                    base[kk] = float(v)
                except Exception:
                    pass
    except Exception:
        pass
    return base


def _verify_country_list():
    fees = _verify_fee_map()
    return [{"code": c["code"], "ar": c["ar"], "en": c["en"], "flag": c["flag"],
             "fee": fees.get(c["code"], 0)} for c in VERIFY_COUNTRIES]


def _verify_fee_for(code):
    return float(_verify_fee_map().get((code or "").strip().upper(), 0.0))


@app.route('/api/verify/order', methods=['POST'])
def api_verify_order():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "غير مصرّح"}), 403
    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور"})

    uid = str(user.get("uid"))
    platform_id = (data.get("platform_id") or "").strip()
    pack_id = (data.get("pack_id") or "").strip()
    mode = (data.get("mode") or "ready").strip()
    if mode not in ("ready", "personal"):
        mode = "ready"
    acct_type = (data.get("acct_type") or "personal").strip()
    if acct_type not in ("personal", "business"):
        acct_type = "personal"
    acct_type_ar = "حساب تجاري" if acct_type == "business" else "حساب شخصي"
    country_code = (data.get("country") or "IQ").strip().upper()[:4]
    whatsapp = (data.get("whatsapp") or "").strip()[:30]
    notes = (data.get("notes") or "").strip()[:500]

    if not whatsapp:
        return jsonify({"ok": False, "error": "رقم الواتساب إلزامي"})

    _ensure_default_verify_platforms()
    plat = None
    for p in db.verify_platforms:
        if p.get("id") == platform_id and p.get("active", True):
            plat = p
            break
    if not plat:
        return jsonify({"ok": False, "error": "المنصة غير متوفرة"})
    is_ready = (mode == "ready")
    acc_login = (data.get("login") or "").strip()[:120]
    acc_pass = (data.get("password") or "").strip()[:120]
    recovery = (data.get("recovery") or "").strip()[:120]

    if is_ready:
        ready = _vf_ready_norm(plat)
        if not ready["enabled"]:
            return jsonify({"ok": False, "error": "الحساب الجاهز غير متوفر لهذه المنصة"})
        price_usd = float(ready["price_usd"])
        if price_usd <= 0:
            return jsonify({"ok": False, "error": "سعر الحساب الجاهز غير صحيح"})
        dur = ""
        country_code = ""
        country_fee = 0.0
        country_ar = ""
        total_usd = price_usd
    else:
        pack = None
        for pk in plat.get("packs", []):
            if pk.get("id") == pack_id:
                pack = pk
                break
        if not pack:
            return jsonify({"ok": False, "error": "الباقة غير متوفرة"})
        price_usd = float(pack.get("price_usd", 0) or 0)
        dur = pack.get("dur", "")
        if price_usd <= 0:
            return jsonify({"ok": False, "error": "سعر الباقة غير صحيح"})
        cinfo = _verify_country(country_code)
        country_fee = _verify_fee_for(country_code)
        country_ar = cinfo["ar"] if cinfo else country_code
        total_usd = price_usd + country_fee
        if not acc_login:
            return jsonify({"ok": False, "error": "اسم المستخدم/الإيميل إلزامي"})
        if not acc_pass:
            return jsonify({"ok": False, "error": "كلمة المرور إلزامية"})

    current_bal = db.get_bal(uid)
    if current_bal < total_usd:
        return jsonify({
            "ok": False, "error": "insufficient_balance",
            "message": "رصيدك غير كافٍ — تحتاج $%.2f ولديك $%.2f. اشحن رصيدك أولاً." % (total_usd, current_bal),
            "required": total_usd, "balance": current_bal
        })

    db.sub_bal(uid, total_usd)
    new_bal = db.get_bal(uid)

    type_ar = "حساب موثّق جاهز" if is_ready else "توثيق الحساب الشخصي"
    subj = ("🔵 طلب حساب موثّق جاهز — " if is_ready else "✅ طلب توثيق حساب شخصي — ") + plat.get("name", "")
    desc = (
        ("🔵 طلب حساب موثّق جاهز\n\n" if is_ready else "✅ طلب توثيق حساب شخصي\n\n") +
        "📱 المنصة: %s\n" % plat.get("name", "") +
        (("⏱️ المدّة: %s\n" % dur) if (not is_ready and dur) else "") +
        "🧩 النوع: %s\n" % type_ar +
        (("👤 نوع الحساب: %s\n" % acct_type_ar) if not is_ready else "") +
        (("🌍 الدولة: %s\n" % country_ar) if (not is_ready and country_ar) else "") +
        (("💰 السعر: $%.2f\n" % price_usd) if is_ready else ("💰 سعر الباقة: $%.2f\n" % price_usd)) +
        (("🏷️ رسوم تأهيل (%s): $%.2f\n" % (country_ar, country_fee)) if country_fee > 0 else "") +
        "💵 الإجمالي: $%.2f (تم الخصم ✓)\n" % total_usd +
        "💼 الرصيد المتبقي: $%.2f\n\n" % new_bal
    )
    if not is_ready:
        desc += "🔐 بيانات الحساب:\n"
        desc += "📧 اليوزر/الإيميل: %s\n" % acc_login
        desc += "🔑 كلمة المرور: %s\n" % acc_pass
        if recovery:
            desc += "📨 إيميل الاسترداد: %s\n" % recovery
        desc += "\n"
    desc += "📞 واتساب: %s\n" % whatsapp
    if notes:
        desc += "\n📝 ملاحظات:\n%s\n" % notes

    tid = str(len(db.tickets) + 1)
    now = time.strftime("%d/%m %H:%M")
    db.tickets[tid] = {
        "id": tid, "uid": uid, "subject": subj, "category": "توثيق الحسابات",
        "status": "open", "date": now, "created": time.time(),
        "messages": [{"from": "user", "text": desc, "time": now}],
        "verify_order": {
            "platform_id": platform_id, "platform": plat.get("name", ""),
            "pack_id": pack_id if not is_ready else "", "dur": dur, "mode": mode,
            "acct_type": acct_type if not is_ready else "",
            "acct_type_ar": acct_type_ar if not is_ready else "",
            "price_usd": price_usd, "whatsapp": whatsapp,
            "country": country_code, "country_ar": country_ar, "country_fee": country_fee,
            "total_usd": total_usd,
            "login": acc_login if not is_ready else "",
            "password": acc_pass if not is_ready else "",
            "recovery": recovery if not is_ready else "",
            "charged": True, "charged_amount": total_usd
        }
    }
    db.save()

    uname = user.get("first_name", "") + " " + user.get("last_name", "")
    try:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("💬 رد على الطلب", callback_data="tk_reply|" + tid))
        bot.send_message(ADMIN_ID,
            "%s طلب توثيق جديد!\n\n👤 %s (ID: %s)\n📱 %s · %s\n⏱️ %s\n💰 $%.2f (تم الخصم ✓)\n📞 %s" % (
                ("🔵" if is_ready else "✅"), uname, uid, plat.get("name", ""), type_ar,
                (dur if dur else "تسليم فوري"), total_usd, whatsapp),
            reply_markup=kb)
    except Exception:
        pass
    push_admin_notif("ticket", {"uid": uid, "subject": subj, "category": "توثيق الحسابات"})

    return jsonify({"ok": True, "ticket_id": tid, "charged": total_usd, "new_balance": new_bal})


@app.route('/api/admin/visa/refund', methods=['POST'])
def api_admin_visa_refund():
    """إرجاع رصيد طلب فيزا — لما الأدمن يرفض الطلب"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    tid = (data.get("ticket_id") or "").strip()
    t = db.tickets.get(tid)
    if not t:
        return jsonify({"ok": False, "error": "ticket_not_found"})
    vo = t.get("visa_order") or {}
    if not vo:
        return jsonify({"ok": False, "error": "not_a_visa_order"})
    if vo.get("refunded"):
        return jsonify({"ok": False, "error": "already_refunded"})
    if not vo.get("charged"):
        return jsonify({"ok": False, "error": "was_not_charged"})

    amt = float(vo.get("charged_amount") or vo.get("price_usd") or 0)
    if amt <= 0:
        return jsonify({"ok": False, "error": "invalid_amount"})

    uid = t.get("uid")
    db.add_bal(uid, amt)
    vo["refunded"] = True
    vo["refunded_at"] = time.time()
    vo["refunded_by"] = user.get('id')
    now = time.strftime("%d/%m %H:%M")
    msgs = t.setdefault("messages", [])
    msgs.append({
        "from": "system",
        "text": f"💰 تم إرجاع ${amt:.2f} لرصيد المستخدم — الطلب ملغى",
        "time": now
    })
    db.save()
    try:
        push_user_notif(uid, "system", "💰 تم إرجاع رصيدك", f"تم إرجاع ${amt:.2f} لرصيدك بسبب إلغاء طلب الفيزا", "wallet")
    except: pass
    return jsonify({"ok": True, "refunded": amt, "ticket_id": tid})


@app.route('/api/admin/visa/cards/toggle', methods=['POST'])
def api_admin_visa_card_toggle():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    cid = data.get("id", "")
    for c in db.visa_cards:
        if c.get("id") == cid:
            c["active"] = not c.get("active", True)
            db.save()
            return jsonify({"ok": True, "active": c["active"]})
    return jsonify({"ok": False})

@app.route('/api/visa/order', methods=['POST'])
def api_visa_order():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user: return jsonify({"ok": False, "error": "غير مصادق"}), 401
    if check_user_spam(user.get("uid"), "visa_order"):
        return jsonify({"ok": False, "error": "محاولات كثيرة - حاول لاحقاً"}), 429
    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور"})

    uid = str(user.get("uid"))
    card_id = (data.get("card_id") or "").strip()
    whatsapp = (data.get("whatsapp") or "").strip()[:30]
    notes = (data.get("notes") or "").strip()[:500]

    if not card_id: return jsonify({"ok": False, "error": "اختر بطاقة"})
    if not whatsapp: return jsonify({"ok": False, "error": "رقم الواتساب إلزامي"})

    card = None
    for c in db.visa_cards:
        if c.get("id") == card_id and c.get("active", True):
            card = c
            break
    if not card:
        return jsonify({"ok": False, "error": "البطاقة غير متوفرة"})

    amount = card.get("amount", 0)
    price_usd = float(card.get("price_usd", 0) or 0)
    region = card.get("region", "USA")
    validity = card.get("validity_months", 12)

    if price_usd <= 0:
        return jsonify({"ok": False, "error": "سعر البطاقة غير صحيح"})
    current_bal = db.get_bal(uid)
    if current_bal < price_usd:
        return jsonify({
            "ok": False,
            "error": "insufficient_balance",
            "message": f"رصيدك غير كافٍ — تحتاج ${price_usd:.2f} ولديك ${current_bal:.2f}. اشحن رصيدك أولاً.",
            "required": price_usd,
            "balance": current_bal
        })

    db.sub_bal(uid, price_usd)
    new_bal = db.get_bal(uid)

    subj = f"💳 طلب شراء بطاقة فيزا ${amount}"
    desc = (
        f"💳 طلب شراء بطاقة فيزا افتراضية\n\n"
        f"💵 قيمة البطاقة: ${amount} USD\n"
        f"💰 السعر المدفوع: ${price_usd}\n"
        f"🌍 المنطقة: {region}\n"
        f"📅 الصلاحية: {validity} شهر\n\n"
        f"✅ تم خصم ${price_usd:.2f} من رصيد المستخدم\n"
        f"💼 الرصيد المتبقي: ${new_bal:.2f}\n\n"
        f"📞 واتساب: {whatsapp}\n"
    )
    if notes:
        desc += f"\n📝 ملاحظات:\n{notes}\n"

    tid = str(len(db.tickets) + 1)
    now = time.strftime("%d/%m %H:%M")
    db.tickets[tid] = {
        "id": tid, "uid": uid, "subject": subj, "category": "بطاقات الفيزا",
        "status": "open", "date": now, "created": time.time(),
        "messages": [{"from": "user", "text": desc, "time": now}],
        "visa_order": {
            "card_id": card_id, "amount": amount, "price_usd": price_usd,
            "region": region, "validity_months": validity, "whatsapp": whatsapp,
            "charged": True, "charged_amount": price_usd
        }
    }
    db.save()

    uname = user.get("first_name", "") + " " + user.get("last_name", "")
    try:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("💬 رد على الطلب", callback_data=f"tk_reply|{tid}"))
        bot.send_message(ADMIN_ID,
            f"💳 طلب فيزا جديد!\n\n"
            f"👤 {uname} (ID: {uid})\n"
            f"💵 ${amount} ({region})\n"
            f"💰 ${price_usd} (تم الخصم ✓)\n"
            f"📞 {whatsapp}",
            reply_markup=kb)
    except: pass
    push_admin_notif("ticket", {"uid": uid, "subject": subj, "category": "بطاقات الفيزا"})

    return jsonify({"ok": True, "ticket_id": tid, "charged": price_usd, "new_balance": new_bal})

