@app.route('/api/currency-rates', methods=['GET'])
def api_currency_rates():

    overrides = db.currency_rates or {}
    out = []
    for c in DEFAULT_CURRENCIES:
        r = dict(c)
        if c["code"] in overrides:
            try:
                r["rate"] = float(overrides[c["code"]])
            except (ValueError, TypeError):
                pass
        out.append(r)
    return jsonify({"ok": True, "currencies": out})

@app.route('/api/admin/currency-rates/list', methods=['POST'])
def api_admin_curr_list():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    overrides = db.currency_rates or {}
    out = []
    for c in DEFAULT_CURRENCIES:
        r = dict(c)
        r["default_rate"] = c["rate"]
        if c["code"] in overrides:
            try:
                r["rate"] = float(overrides[c["code"]])
                r["modified"] = True
            except (ValueError, TypeError):
                r["modified"] = False
        else:
            r["modified"] = False
        out.append(r)
    return jsonify({"ok": True, "currencies": out})

@app.route('/api/admin/currency-rates/update', methods=['POST'])
def api_admin_curr_update():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    code = (data.get("code") or "").strip().upper()
    rate = data.get("rate")
    valid_codes = [c["code"] for c in DEFAULT_CURRENCIES]
    if code not in valid_codes:
        return jsonify({"ok": False, "error": "عملة غير معروفة"})
    if code == "USD":
        return jsonify({"ok": False, "error": "الدولار هو الأساس — لا يُعدّل"})
    try:
        rate = float(rate)
        if rate <= 0:
            return jsonify({"ok": False, "error": "السعر يجب أن يكون موجباً"})
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "قيمة غير صالحة"})
    if not isinstance(db.currency_rates, dict):
        db.currency_rates = {}
    db.currency_rates[code] = rate
    db.save()
    # ═══ Regenerate webapp.html so the embedded JS _currencies array reflects new rates
    try: generate_webapp()
    except Exception: pass
    return jsonify({"ok": True, "code": code, "rate": rate})

@app.route('/api/admin/currency-rates/reset', methods=['POST'])
def api_admin_curr_reset():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    code = (data.get("code") or "").strip().upper()
    if isinstance(db.currency_rates, dict) and code in db.currency_rates:
        del db.currency_rates[code]
        db.save()
        try: generate_webapp()
        except Exception: pass
    return jsonify({"ok": True})

