@app.route('/api/admin/platforms/list', methods=['POST'])
def api_admin_plats_list():
    """يرجع كل المنصات المكتشفة (من المزودين + الكاش) مع عدد الخدمات وحالة الإخفاء"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False, "error": "unauthorized"}), 403

    all_svcs = []
    try:
        all_svcs.extend(cache.all_services or [])
    except: pass
    try:
        all_svcs.extend(agg_cache.services or [])
    except: pass

    by_key = {}
    for s in all_svcs:
        plat_raw = (s.get("plat") or "Other").strip() or "Other"
        key = plat_raw.lower()
        if key not in by_key:
            by_key[key] = {"name": plat_raw, "count": 0}
        by_key[key]["count"] += 1

    hidden_set = _hidden_plats_set()

    for hp in hidden_set:
        if hp not in by_key:
            by_key[hp] = {"name": hp, "count": 0}

    platforms = []
    for key, info in by_key.items():
        platforms.append({
            "name": info["name"],
            "key": key,
            "service_count": info["count"],
            "hidden": key in hidden_set,
        })
    platforms.sort(key=lambda x: (x["hidden"], -x["service_count"], x["name"].lower()))

    return jsonify({
        "ok": True,
        "platforms": platforms,
        "total": len(platforms),
        "visible": sum(1 for p in platforms if not p["hidden"]),
        "hidden": sum(1 for p in platforms if p["hidden"]),
        "total_services": sum(p["service_count"] for p in platforms),
        "visible_services": sum(p["service_count"] for p in platforms if not p["hidden"]),
    })


@app.route('/api/admin/platforms/toggle', methods=['POST'])
def api_admin_plats_toggle():
    """يبدّل حالة منصة بين ظاهرة ومخفية"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False, "error": "unauthorized"}), 403

    key = (data.get("key") or "").strip().lower()
    if not key:
        return jsonify({"ok": False, "error": "missing_key"}), 400

    hidden = list(db.hidden_platforms or [])
    hidden_norm = [(h or "").strip().lower() for h in hidden]
    if key in hidden_norm:
        db.hidden_platforms = [h for h, hn in zip(hidden, hidden_norm) if hn != key]
        action = "shown"
    else:
        db.hidden_platforms = hidden + [key]
        action = "hidden"
    db.save()
    return jsonify({"ok": True, "action": action, "key": key, "hidden_count": len(db.hidden_platforms)})


@app.route('/api/admin/platforms/bulk', methods=['POST'])
def api_admin_plats_bulk():
    """عمليات جماعية: إخفاء الكل أو إظهار الكل"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False, "error": "unauthorized"}), 403

    action = (data.get("action") or "").strip().lower()
    if action == "show_all":
        db.hidden_platforms = []
        db.save()
        return jsonify({"ok": True, "hidden_count": 0})
    return jsonify({"ok": False, "error": "invalid_action"}), 400


# ═══════════════ إدارة الأقسام (SMM) ═══════════════
def _admin_ok(data):
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return None
    return user

@app.route('/api/admin/sections', methods=['POST'])
def api_admin_sections():
    data = freq.json or {}
    if not _admin_ok(data):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    meta = db.category_meta or {}
    ovr = db.service_cat_overrides or {}
    raw = _all_services_raw()
    counts = {}
    svc_list = []
    for s in raw:
        sid = str(s.get("id", ""))
        cur = (ovr.get(sid) or s.get("cat", "") or "").strip() or "غير مصنّف"
        counts[cur] = counts.get(cur, 0) + 1
        svc_list.append({
            "id": sid,
            "name": s.get("name", "") or s.get("cat", ""),
            "plat": s.get("plat", "") or "",
            "cat": cur,
        })
    cats = {}
    for c in counts:
        cats[c] = True
    for c in meta:
        cats[c] = True
    out = []
    for c in cats:
        m = meta.get(c, {}) or {}
        out.append({
            "key": c,
            "name": (m.get("name", "") or "").strip() or c,
            "icon": m.get("icon", "") or "fas fa-folder",
            "order": int(m.get("order", 9999)),
            "pinned": bool(m.get("pinned")),
            "hidden": bool(m.get("hidden")),
            "count": counts.get(c, 0),
        })
    out.sort(key=lambda x: (-1 if x["pinned"] else 0, x["order"], x["key"]))
    return jsonify({"ok": True, "sections": out, "services": svc_list})

@app.route('/api/admin/sections/save', methods=['POST'])
def api_admin_sections_save():
    data = freq.json or {}
    if not _admin_ok(data):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    key = str(data.get("key", "")).strip()
    if not key:
        return jsonify({"ok": False, "error": "no_key"})
    m = dict(db.category_meta.get(key, {}) or {})
    if "name" in data:
        m["name"] = str(data.get("name", "") or "").strip()
    if "icon" in data:
        m["icon"] = str(data.get("icon", "") or "").strip()
    if "pinned" in data:
        m["pinned"] = bool(data.get("pinned"))
    if "hidden" in data:
        m["hidden"] = bool(data.get("hidden"))
    if "order" in data:
        try:
            m["order"] = int(data.get("order"))
        except Exception:
            pass
    db.category_meta[key] = m
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/sections/create', methods=['POST'])
def api_admin_sections_create():
    data = freq.json or {}
    if not _admin_ok(data):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    name = str(data.get("name", "") or "").strip()
    if not name:
        return jsonify({"ok": False, "error": "no_name"})
    if name in db.category_meta:
        return jsonify({"ok": False, "error": "exists"})
    try:
        max_order = max([int(x.get("order", 0)) for x in db.category_meta.values()] + [0])
    except Exception:
        max_order = 0
    db.category_meta[name] = {
        "name": name,
        "icon": str(data.get("icon", "") or "fas fa-folder").strip(),
        "order": max_order + 1,
        "pinned": False,
        "hidden": False,
    }
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/sections/reorder', methods=['POST'])
def api_admin_sections_reorder():
    data = freq.json or {}
    if not _admin_ok(data):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    order = data.get("order", [])
    if not isinstance(order, list):
        return jsonify({"ok": False, "error": "bad_order"})
    for i, key in enumerate(order):
        k = str(key).strip()
        m = dict(db.category_meta.get(k, {}) or {})
        m["order"] = i
        db.category_meta[k] = m
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/sections/assign', methods=['POST'])
def api_admin_sections_assign():
    data = freq.json or {}
    if not _admin_ok(data):
        return jsonify({"ok": False, "error": "unauthorized"}), 403
    sid = str(data.get("service_id", "")).strip()
    cat = str(data.get("cat", "") or "").strip()
    if not sid:
        return jsonify({"ok": False, "error": "no_service"})
    if not isinstance(db.service_cat_overrides, dict):
        db.service_cat_overrides = {}
    if cat:
        db.service_cat_overrides[sid] = cat
    else:
        db.service_cat_overrides.pop(sid, None)
    db.save()
    return jsonify({"ok": True})


@app.route('/api/admin/announcements/delete', methods=['POST'])
def api_admin_del_ann():
    data = freq.json or {}
