@app.route('/api/admin/section_labels', methods=['POST'])
def api_admin_section_labels():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    labels = data.get("labels") or {}
    if not isinstance(labels, dict):
        return jsonify({"ok": False, "error": "invalid"})
    valid_keys = {"subscription", "charging", "chargegames", "vn", "visa"}
    for key, val in labels.items():
        if key not in valid_keys: continue
        if not isinstance(val, dict): continue
        nm = (val.get("name") or "").strip()[:40]
        ic = (val.get("icon") or "").strip()[:60]
        if not nm: continue
        if key not in db.section_labels or not isinstance(db.section_labels[key], dict):
            db.section_labels[key] = {}
        db.section_labels[key]["name"] = nm
        if ic:
            db.section_labels[key]["icon"] = ic
    db.save()
    return jsonify({"ok": True, "section_labels": db.section_labels})

