@app.route('/api/admin/site_name', methods=['POST'])
def api_admin_site_name():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    nm = (data.get("name") or "").strip()
    if not nm:
        return jsonify({"ok": False, "error": "empty_name"})
    if len(nm) < 2 or len(nm) > 20:
        return jsonify({"ok": False, "error": "invalid_length"})

    if not re.match(r'^[A-Za-z0-9]+$', nm):
        return jsonify({"ok": False, "error": "invalid_chars"})
    db.site_name = nm

    if 'logo_variant_light' in data:
        try:
            v = int(data['logo_variant_light'])
            if v in (1, 2, 3):
                db.logo_variant_light = v
        except: pass
    db.save()
    try: print(f"💾 Site name saved: {nm!r} → bot_data.json")
    except: pass

    _invalidate_html_caches()
    return jsonify({"ok": True, "site_name": db.site_name, "logo_variant_light": db.logo_variant_light})

@app.route('/api/admin/pwa_icon', methods=['POST'])
def api_admin_pwa_icon():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403
    img = (data.get("image") or "").strip()
    if img == "CLEAR" or img == "":
        db.pwa_icon = ""
        try: db.pwa_icon_version = int(db.pwa_icon_version or 1) + 1
        except: db.pwa_icon_version = 2
        db.save()
        _invalidate_html_caches()
        return jsonify({"ok": True, "cleared": True, "version": db.pwa_icon_version})

    if not img.startswith("data:image/"):
        return jsonify({"ok": False, "error": "invalid_image"})

    if len(img) > 3_000_000:
        return jsonify({"ok": False, "error": "too_large"})
    db.pwa_icon = img
    try: db.pwa_icon_version = int(db.pwa_icon_version or 1) + 1
    except: db.pwa_icon_version = 2
    db.save()
    _invalidate_html_caches()
    return jsonify({"ok": True, "version": db.pwa_icon_version})

