@app.route('/api/admin/contact_links', methods=['POST'])
def api_admin_contact_links():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'): return jsonify({"ok": False}), 403

    links = data.get("links")
    if not isinstance(links, dict):
        return jsonify({"ok": False, "error": "missing_links"})

    allowed = ("telegram", "whatsapp", "email", "instagram", "twitter")
    cleaned = dict(getattr(db, "contact_links", {}) or {})
    for k in allowed:
        if k in links:
            v = links.get(k)
            if v is None: v = ""
            v = str(v).strip()[:300]

            if k == "email" and v and ("@" not in v or "." not in v):
                return jsonify({"ok": False, "error": "invalid_email", "field": "email"})

            if k in ("telegram", "whatsapp", "instagram", "twitter") and v:
                if not (v.startswith("http://") or v.startswith("https://")):
                    return jsonify({"ok": False, "error": "invalid_url", "field": k})
            cleaned[k] = v

    for k in allowed:
        cleaned.setdefault(k, "")

    db.contact_links = cleaned
    db.save()

    _invalidate_html_caches()
    return jsonify({"ok": True, "contact_links": db.contact_links})

