@app.route('/api/admin/custom_services/add', methods=['POST'])
def api_admin_add_custom_service():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    stype = data.get("type", "")
    name = data.get("name", "").strip()
    desc = data.get("desc", "").strip()
    icon = data.get("icon", "📦")
    color = data.get("color", "#4A90FF")
    if not name or not stype:
        return jsonify({"ok": False, "error": "missing fields"})
    sid = f"cs_{int(time.time())}_{secrets.token_hex(3)}"
    svc = {"id": sid, "name": name, "type": stype, "desc": desc, "icon": icon, "color": color, "active": True, "image": data.get("image", "")}
    if stype in ("subscription", "charging"):
        svc["packages"] = data.get("packages", [])
        svc["email_required"] = bool(data.get("email_required", False))
        svc["username_required"] = bool(data.get("username_required", False))
        if stype == "subscription" and data.get("qty_mode"):
            svc["qty_mode"] = True
            svc["unit_price"] = float(data.get("unit_price", 0) or 0)
            svc["min"] = int(data.get("min", 1) or 1)
            svc["max"] = int(data.get("max", 100) or 100)
    else:
        svc["rate"] = float(data.get("rate", 0))
        svc["min"] = int(data.get("min", 100))
        svc["max"] = int(data.get("max", 100000))
    db.custom_services[sid] = svc
    db.save()
    return jsonify({"ok": True, "id": sid})

