@app.route('/api/custom_services', methods=['GET'])
def api_public_custom_services():

    import hashlib, gzip as _gz
    result = {sid: svc for sid, svc in db.custom_services.items() if svc.get("active", True)}
    json_str = json.dumps({"ok": True, "services": result}, ensure_ascii=False)

    etag = '"cs-' + hashlib.md5(json_str.encode()).hexdigest()[:16] + '"'
    if freq.headers.get('If-None-Match') == etag:
        return app.response_class(status=304)

    if 'gzip' in freq.headers.get('Accept-Encoding', ''):
        gz = _gz.compress(json_str.encode(), compresslevel=4)
        resp = app.response_class(response=gz, status=200, mimetype='application/json')
        resp.headers['Content-Encoding'] = 'gzip'
    else:
        resp = app.response_class(response=json_str, status=200, mimetype='application/json')

    resp.headers['ETag'] = etag
    resp.headers['Cache-Control'] = 'private, max-age=30'
    return resp

