@app.route('/api/admin/providers', methods=['POST'])
def api_admin_providers_list():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    provs = []
    for pid, p in db.providers.items():

        total = 0; enabled = 0
        for k, s in db.provider_services.items():
            if s.get("provider_id") == pid:
                total += 1
                if s.get("enabled"): enabled += 1
        plats = set(s.get("platform") for k, s in db.provider_services.items()
                    if s.get("provider_id") == pid and s.get("platform"))

        safe = {k: v for k, v in p.items() if k != "api_key"}
        safe["api_key_masked"] = ("*" * max(0, len(p.get("api_key","")) - 4) + p.get("api_key","")[-4:]) if p.get("api_key") else ""
        safe["services_total"] = total
        safe["services_enabled"] = enabled
        safe["platforms_count"] = len(plats)
        provs.append(safe)
    provs.sort(key=lambda x: x.get("created", 0), reverse=True)
    return jsonify({"ok": True, "providers": provs})

