@app.route('/api/admin/providers/sync', methods=['POST'])
def api_admin_providers_sync():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    pid = str(data.get("id", "")).strip()
    if pid not in db.providers:
        return jsonify({"ok": False, "error": "not_found"})
    prov = db.providers[pid]
    services, err = provider_fetch_services(prov)
    if err:
        prov["status"] = "error"
        prov["last_check"] = time.time()
        db.save()
        return jsonify({"ok": False, "error": err})

    old_enabled = {k.split(":", 1)[1]: s for k, s in db.provider_services.items() if s.get("provider_id") == pid}

    keys_to_remove = [k for k, s in db.provider_services.items() if s.get("provider_id") == pid]
    for k in keys_to_remove:
        del db.provider_services[k]

    added = 0
    for s in services:
        svc_id = str(s.get("service", "")).strip()
        if not svc_id:
            continue
        name_en = s.get("name", "")
        cat_en = s.get("category", "")
        _combined = f"{cat_en} {name_en}".strip()
        detected_plat = detect_platform_from_name(_combined)
        if detected_plat == "Other":
            detected_plat = detect_platform_from_name(cat_en) if cat_en else detect_platform_from_name(name_en)
        detected_cat = detect_category_from_name(f"{name_en} {cat_en}".strip())
        key = f"{pid}:{svc_id}"

        was_enabled = old_enabled.get(svc_id, {}).get("enabled", False)
        user_markup = old_enabled.get(svc_id, {}).get("user_markup")
        _prev = old_enabled.get(svc_id, {})
        # نحافظ على الإعدادات اللي يتحكم بها الأدمن (التثبيت/الفئة المخصصة) عبر المزامنة.
        # المزامنة تحدّث حقول المزوّد فقط: السعر/الحد/الحالة/الاسم الأصلي.
        prev_pinned = bool(_prev.get("pinned", False))
        prev_cat_custom = bool(_prev.get("category_custom", False))
        prev_custom_cat = _prev.get("category") if prev_cat_custom else None
        prev_name_ar = _prev.get("name_ar")
        db.provider_services[key] = {
            "provider_id": pid,
            "svc_id": svc_id,
            "name_en": name_en,
            "category_en": cat_en,
            "platform": detected_plat,
            "category": prev_custom_cat if prev_cat_custom and prev_custom_cat else detected_cat,
            "category_custom": prev_cat_custom,
            "rate": float(s.get("rate", 0) or 0),
            "min": int(s.get("min", 0) or 0),
            "max": int(s.get("max", 0) or 0),
            "type": s.get("type", ""),
            "enabled": was_enabled,
            "user_markup": user_markup,
            "pinned": prev_pinned,
        }
        # نحافظ على الترجمة العربية السابقة إن وُجدت (الاسم المخصص محفوظ أصلاً بمعزل عن هذا)
        if prev_name_ar:
            db.provider_services[key]["name_ar"] = prev_name_ar
        added += 1
    prov["status"] = "ok"
    prov["services_count"] = added
    prov["last_check"] = time.time()
    db.save()
    rebuild_agg_cache()
    try: cache.reapply_overrides()
    except Exception: pass
    return jsonify({"ok": True, "count": added})

@app.route('/api/admin/providers/redetect_platforms', methods=['POST'])
def api_admin_providers_redetect():
    """
    يعيد تصنيف المنصات لجميع خدمات المزودين الموجودة بناءً على القواميس الحالية
    بدون ما يحتاج يسحب من API المزود من جديد. مفيد لما تضيف كلمات منصات جديدة
    أو لإصلاح خدمات صارت مصنفة 'Other' بالغلط.
    """
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    pid_filter = str(data.get("provider_id", "")).strip()
    changed = 0
    other_before = 0
    other_after = 0
    for key, psvc in list(db.provider_services.items()):
        if pid_filter and psvc.get("provider_id") != pid_filter:
            continue
        old_plat = psvc.get("platform", "Other")
        name_en = psvc.get("name_en", "") or ""
        cat_en  = psvc.get("category_en", "") or ""
        if old_plat == "Other":
            other_before += 1
        _combined = f"{cat_en} {name_en}".strip()
        new_plat = detect_platform_from_name(_combined)
        if new_plat == "Other":
            new_plat = detect_platform_from_name(cat_en) if cat_en else detect_platform_from_name(name_en)
        if new_plat != old_plat:
            psvc["platform"] = new_plat
            changed += 1
        new_cat = detect_category_from_name(f"{name_en} {cat_en}".strip())
        if new_cat and psvc.get("category") != new_cat:
            psvc["category"] = new_cat
        if psvc.get("platform") == "Other":
            other_after += 1
    if changed:
        db.save()
        rebuild_agg_cache()
    return jsonify({
        "ok": True,
        "changed": changed,
        "other_before": other_before,
        "other_after": other_after,
        "message": f"تم إعادة تصنيف {changed} خدمة. غير مصنفة: {other_before} → {other_after}"
    })

@app.route('/api/admin/providers/services', methods=['POST'])
def api_admin_providers_services():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    pid = str(data.get("id", "")).strip()
    if pid not in db.providers:
        return jsonify({"ok": False, "error": "not_found"})
    plat_filter = str(data.get("platform", "")).strip()
    cat_filter = str(data.get("category", "")).strip()
    q = str(data.get("q", "")).strip().lower()
    enabled_only = bool(data.get("enabled_only"))
    services = []
    plat_counts = {}
    cat_counts = {}
    total = 0
    enabled = 0
    for key, s in db.provider_services.items():
        if s.get("provider_id") != pid:
            continue
        total += 1
        if s.get("enabled"): enabled += 1
        plat = s.get("platform", "Other")
        cat = s.get("category", "خدمات")
        plat_counts[plat] = plat_counts.get(plat, 0) + 1
        cat_counts[cat] = cat_counts.get(cat, 0) + 1
        if plat_filter and plat != plat_filter: continue
        if cat_filter and cat != cat_filter: continue
        if enabled_only and not s.get("enabled"): continue
        if q:
            name = (s.get("name_en", "") + " " + s.get("category_en", "")).lower()
            if q not in name: continue
        services.append({
            "key": key,
            "svc_id": s.get("svc_id"),
            "name": s.get("name_en", ""),
            "name_ar": s.get("name_ar", ""),
            "name_override": (db.service_name_overrides or {}).get(str(key), ""),
            "category_en": s.get("category_en", ""),
            "platform": plat,
            "category": cat,
            "rate": s.get("rate", 0),
            "min": s.get("min", 0),
            "max": s.get("max", 0),
            "enabled": s.get("enabled", False),
            "pinned": bool(s.get("pinned", False)),
            "user_markup": s.get("user_markup"),
        })

    offset = int(data.get("offset", 0))
    limit = int(data.get("limit", 200))
    total_scope = len(services)
    services = services[offset:offset + limit]
    return jsonify({
        "ok": True,
        "services": services,
        "total": total,
        "enabled": enabled,
        "shown": len(services),
        "scope_total": total_scope,
        "has_more": (offset + limit) < total_scope,
        "platforms": plat_counts,
        "categories": cat_counts,
    })

