@app.route('/api/admin/providers/services/batch', methods=['POST'])
def api_admin_providers_services_batch():
    """يطبّق دفعة تغييرات (تفعيل/تعطيل/تثبيت/إعادة تسمية) بطلب واحد وحفظ واحد.
    يستقبل: changes=[{key, enabled?, pinned?, name_override?}, ...]"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    changes = data.get("changes")
    if not isinstance(changes, list):
        return jsonify({"ok": False, "error": "bad_changes"})
    if not isinstance(db.service_name_overrides, dict):
        db.service_name_overrides = {}
    applied = 0
    for ch in changes:
        if not isinstance(ch, dict):
            continue
        key = str(ch.get("key", "")).strip()
        if key not in db.provider_services:
            continue
        svc = db.provider_services[key]
        touched = False
        if "enabled" in ch:
            svc["enabled"] = bool(ch["enabled"]); touched = True
        if "pinned" in ch:
            svc["pinned"] = bool(ch["pinned"]); touched = True
        if "name_override" in ch:
            nm = str(ch.get("name_override", "")).strip()
            if nm:
                db.service_name_overrides[key] = nm
            else:
                db.service_name_overrides.pop(key, None)
            touched = True
        if touched:
            applied += 1
    db.save()
    rebuild_agg_cache()
    try: cache.reapply_overrides()
    except Exception: pass
    return jsonify({"ok": True, "applied": applied})

@app.route('/api/admin/vn/config', methods=['POST'])
def api_admin_vn_config():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    action = data.get("action", "get")
    cfg = db.vn_config
    if action == "get":

        safe = dict(cfg)
        k = cfg.get("api_key", "")
        safe["api_key_masked"] = ("•" * max(0, len(k) - 4) + k[-4:]) if k else ""
        safe.pop("api_key", None)

        total_countries = len(VN_COUNTRIES_DATA)
        enabled_countries = sum(1 for c in db.vn_countries.values() if c.get("enabled"))
        total_svcs = len(db.vn_services)
        enabled_svcs = sum(1 for s in db.vn_services.values() if s.get("enabled"))
        active_orders = sum(1 for o in db.vn_orders.values() if o.get("status") in ("waiting", "active"))
        return jsonify({
            "ok": True,
            "config": safe,
            "stats": {
                "total_countries": total_countries,
                "enabled_countries": enabled_countries,
                "total_services": total_svcs,
                "enabled_services": enabled_svcs,
                "active_orders": active_orders,
            }
        })
    if action == "save":
        if "provider" in data:
            p = str(data["provider"]).strip()
            if p in ("5sim", "smspool", "sms-activate", "smsman", "grizzly", "custom", "durianrcs"):
                cfg["provider"] = p
        if "url" in data:
            u = str(data["url"]).strip()
            if u and re.match(r"^https?://", u):
                cfg["url"] = u
        if "api_key" in data and data["api_key"]:
            cfg["api_key"] = str(data["api_key"]).strip()

        if "username" in data:
            un = str(data["username"]).strip()

            if un or data.get("username") == "":
                cfg["username"] = un
        if "default_markup" in data:
            try: cfg["default_markup"] = max(0, min(500, float(data["default_markup"])))
            except: pass
        if "number_ttl" in data:
            try: cfg["number_ttl"] = max(5, min(60, int(data["number_ttl"])))
            except: pass
        if "poll_interval" in data:
            try: cfg["poll_interval"] = max(3, min(30, int(data["poll_interval"])))
            except: pass
        if "enabled" in data:
            cfg["enabled"] = bool(data["enabled"])
        db.save()
        return jsonify({"ok": True})
    return jsonify({"ok": False, "error": "unknown_action"})

@app.route('/api/admin/vn/test', methods=['POST'])
def api_admin_vn_test():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    url = str(data.get("url", "")).strip() or db.vn_config.get("url", "")
    key = str(data.get("api_key", "")).strip() or db.vn_config.get("api_key", "")
    prov = str(data.get("provider", "")).strip() or db.vn_config.get("provider", "5sim")

    if prov == "durianrcs" and "username" in data:
        un = str(data.get("username", "")).strip()
        if un:
            db.vn_config["username"] = un
            db.save()
    res = vn_test_connection(url=url, key=key, provider=prov)
    if res.get("ok"):
        db.vn_config["status"] = "ok"
        db.vn_config["balance"] = res.get("balance", 0)
        db.vn_config["last_check"] = time.time()
        db.save()
    else:
        db.vn_config["status"] = "error"
        db.save()
    return jsonify(res)

@app.route('/api/admin/vn/durian/projects', methods=['POST'])
def api_admin_vn_durian_projects():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    action = str(data.get("action", "list")).strip()
    cfg = db.vn_config
    projects = list(cfg.get("durian_projects", []) or [])

    def _norm(p):

        return {
            "pid": str(p.get("pid", "") or "").strip(),
            "country_iso": str(p.get("country_iso", "") or "").strip().lower(),
            "service_id": str(p.get("service_id", "") or "").strip().lower(),
            "service_name": str(p.get("service_name", "") or "").strip(),
            "cost": max(0.0, float(p.get("cost", 0) or 0)),
            "vip": str(p.get("vip", "") or "").strip(),
            "note": str(p.get("note", "") or "").strip()[:200],
        }

    if action == "list":

        out = []
        for i, p in enumerate(projects):
            np = _norm(p)
            cc = np["country_iso"]
            np["_idx"] = i
            np["_country_name_ar"] = (VN_COUNTRIES_DATA.get(cc, {}) or {}).get("name_ar", cc.upper())
            np["_country_phone_code"] = (VN_COUNTRIES_DATA.get(cc, {}) or {}).get("phone_code", "")
            if not np["service_name"]:
                np["service_name"] = VN_SVC_NAMES.get(np["service_id"], np["service_id"].title())
            out.append(np)
        return jsonify({
            "ok": True,
            "projects": out,
            "countries_available": [
                {"iso": iso, "name_ar": info.get("name_ar", iso),
                 "name_en": info.get("name_en", iso), "phone_code": info.get("phone_code", "")}
                for iso, info in sorted(VN_COUNTRIES_DATA.items(),
                    key=lambda x: x[1].get("name_ar", x[0]))
            ],
            "services_suggestions": [
                {"id": sid, "name": nm} for sid, nm in sorted(VN_SVC_NAMES.items())
                if "_" not in sid or sid in ("mail_ru", "western_union", "perfect_money")
            ],
        })

    if action == "add":
        new_p = _norm(data.get("project", {}) or data)

        if not new_p["pid"]:
            return jsonify({"ok": False, "error": "pid فارغ"})
        if not new_p["country_iso"]:
            return jsonify({"ok": False, "error": "اختر الدولة"})
        if new_p["country_iso"] not in VN_COUNTRIES_DATA:
            return jsonify({"ok": False, "error": "كود دولة غير مدعوم"})
        if not new_p["service_id"]:
            return jsonify({"ok": False, "error": "أدخل معرّف الخدمة (مثلاً: whatsapp)"})
        if new_p["cost"] <= 0:
            return jsonify({"ok": False, "error": "السعر لازم > 0"})
        if not new_p["service_name"]:
            new_p["service_name"] = VN_SVC_NAMES.get(new_p["service_id"], new_p["service_id"].title())

        for p in projects:
            if (str(p.get("pid", "")).strip() == new_p["pid"]
                and str(p.get("country_iso", "")).strip().lower() == new_p["country_iso"]
                and str(p.get("service_id", "")).strip().lower() == new_p["service_id"]):
                return jsonify({"ok": False, "error": "هذا المشروع موجود مسبقاً (نفس pid + الدولة + الخدمة)"})
        projects.append(new_p)
        cfg["durian_projects"] = projects
        db.save()
        return jsonify({"ok": True, "added": new_p, "total": len(projects)})

    if action == "update":
        try: idx = int(data.get("idx", -1))
        except: idx = -1
        if idx < 0 or idx >= len(projects):
            return jsonify({"ok": False, "error": "index_out_of_range"})
        upd = _norm(data.get("project", {}) or data)
        if not upd["pid"] or not upd["country_iso"] or not upd["service_id"] or upd["cost"] <= 0:
            return jsonify({"ok": False, "error": "بيانات ناقصة"})
        if upd["country_iso"] not in VN_COUNTRIES_DATA:
            return jsonify({"ok": False, "error": "كود دولة غير مدعوم"})
        if not upd["service_name"]:
            upd["service_name"] = VN_SVC_NAMES.get(upd["service_id"], upd["service_id"].title())
        projects[idx] = upd
        cfg["durian_projects"] = projects
        db.save()
        return jsonify({"ok": True, "updated": upd})

    if action == "delete":
        try: idx = int(data.get("idx", -1))
        except: idx = -1
        if idx < 0 or idx >= len(projects):
            return jsonify({"ok": False, "error": "index_out_of_range"})
        removed = projects.pop(idx)
        cfg["durian_projects"] = projects

        rm_key = f"{removed.get('country_iso','')}:{removed.get('service_id','')}"

        still_used = any(
            str(p.get("country_iso", "")).strip().lower() == removed.get("country_iso", "")
            and str(p.get("service_id", "")).strip().lower() == removed.get("service_id", "")
            for p in projects
        )
        if not still_used and rm_key in db.vn_services:
            db.vn_services.pop(rm_key, None)
        db.save()
        return jsonify({"ok": True, "removed": removed, "total": len(projects)})

    if action == "preview":

        pid = str(data.get("pid", "") or "").strip()
        if not pid:
            return jsonify({"ok": False, "error": "pid فارغ"})
        u = (cfg.get("url", "") or "").rstrip("/")
        nm = (cfg.get("username", "") or "").strip()
        k = cfg.get("api_key", "")
        if not u or not nm or not k:
            return jsonify({"ok": False, "error": "أكمل إعدادات الاتصال أولاً"})
        try:
            r = requests.get(f"{u}/getCountryPhoneNum",
                params={"name": nm, "ApiKey": k, "pid": pid}, timeout=10)
            if r.status_code != 200:
                return jsonify({"ok": False, "error": f"HTTP {r.status_code}"})
            d = r.json()
            code = str(d.get("code", ""))
            if code != "200":
                return jsonify({"ok": False, "error": _durian_msg(code, d.get("msg", ""))})
            data_obj = d.get("data") or {}
            countries_avail = []
            if isinstance(data_obj, dict):
                for cc, cnt in data_obj.items():
                    cc_l = str(cc).lower()
                    info = VN_COUNTRIES_DATA.get(cc_l, {}) or {}
                    countries_avail.append({
                        "iso": cc_l,
                        "name_ar": info.get("name_ar", cc_l.upper()),
                        "phone_code": info.get("phone_code", ""),
                        "count": int(cnt or 0),
                    })
            countries_avail.sort(key=lambda x: -x["count"])
            return jsonify({"ok": True, "pid": pid, "countries": countries_avail})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)[:120]})

    return jsonify({"ok": False, "error": "unknown_action"})

@app.route('/api/admin/vn/diagnose', methods=['POST'])
def api_admin_vn_diagnose():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    url = (str(data.get("url", "")).strip() or db.vn_config.get("url", "")).rstrip("/")
    key = str(data.get("api_key", "")).strip() or db.vn_config.get("api_key", "")
    if not url or not key:
        return jsonify({"ok": False, "error": "أدخل الرابط والمفتاح"})
    paths = ["/user/profile", "/profile", "/user/info", "/balance", "/guest/prices"]
    results = []
    for p in paths:
        full = f"{url}{p}"
        try:
            r = requests.get(full, headers={"Authorization": f"Bearer {key}", "Accept": "application/json"}, timeout=8)
            preview = r.text[:200] if r.text else ""
            results.append({
                "path": p,
                "full_url": full,
                "status": r.status_code,
                "size": len(r.text or ""),
                "preview": preview,
                "content_type": r.headers.get("content-type", ""),
            })
        except requests.exceptions.Timeout:
            results.append({"path": p, "full_url": full, "status": "timeout", "preview": ""})
        except Exception as e:
            results.append({"path": p, "full_url": full, "status": "error", "preview": str(e)[:100]})
    return jsonify({"ok": True, "results": results})

@app.route('/api/admin/system/settings', methods=['POST'])
def api_admin_system_settings():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    action = str(data.get("action", "get")).strip()

    SECRET_KEYS = {"smtp_pass", "binance_api_secret", "binance_api_key", "bot_token"}

    def _mask(v):
        s = str(v or "")
        if not s: return ""
        if len(s) <= 6: return "•" * len(s)
        return "•" * (len(s) - 4) + s[-4:]

    if action == "get":

        smtp = {
            "host":  _setting("smtp_host", SMTP_HOST),
            "port":  int(_setting("smtp_port", SMTP_PORT)),
            "user":  _setting("smtp_user", SMTP_USER),
            "pass_masked":  _mask(_setting("smtp_pass", SMTP_PASS)),
            "has_custom_pass": bool(_APP_SETTINGS.get("smtp_pass")),
        }

        binance = {
            "api_key_masked":     _mask(_setting("binance_api_key", BINANCE_API_KEY)),
            "api_secret_masked":  _mask(_setting("binance_api_secret", BINANCE_API_SECRET)),
            "pay_id":             _setting("binance_pay_id", BINANCE_PAY_ID),
            "has_custom_key":     bool(_APP_SETTINGS.get("binance_api_key")),
            "has_custom_secret":  bool(_APP_SETTINGS.get("binance_api_secret")),
        }

        telegram = {
            "bot_token_masked": _mask(_setting("bot_token", BOT_TOKEN)),
            "admin_id":         int(_setting("admin_id", ADMIN_ID) or ADMIN_ID),
            "has_custom_token": bool(_APP_SETTINGS.get("bot_token")),
            "current_runtime_token_masked": _mask(BOT_TOKEN),
            "current_runtime_admin_id":     ADMIN_ID,
        }
        markup = {
            "follower_mark":      _follower_mark(),
            "general_mark":       _general_mark(),
            "default_follower":   FOLLOWER_MARK,
            "default_general":    GENERAL_MARK,
            "follower_profit_pct": round((_follower_mark() - 1) * 100, 2),
            "general_profit_pct":  round((_general_mark() - 1) * 100, 2),
        }
        google = {
            "client_id":        _google_client_id(),
            "has_custom_id":    bool(_APP_SETTINGS.get("google_client_id")),
            "default_id":       GOOGLE_CLIENT_ID,
            "webapp_url":       WEBAPP_URL,
            "has_custom_url":   bool(_APP_SETTINGS.get("webapp_url")),
        }
        return jsonify({
            "ok": True,
            "smtp": smtp,
            "binance": binance,
            "telegram": telegram,
            "markup": markup,
            "google": google,
            "note": "تعديلات SMTP و Binance و Google ونسب الربح تطبَّق فوراً. تعديل Bot Token و Admin ID يحتاج إعادة تشغيل السيرفر.",
        })

    if action == "save":
        section = str(data.get("section", "")).strip()
        changed = []
        needs_restart = False

        def _set(key, value, allow_empty=False):
            v = "" if value is None else str(value).strip()
            if not v and not allow_empty:
                return False
            if v == _APP_SETTINGS.get(key):
                return False
            if v:
                _APP_SETTINGS[key] = v
            else:
                _APP_SETTINGS.pop(key, None)
            changed.append(key)
            return True

        if section == "smtp":

            if "host" in data: _set("smtp_host", data.get("host"))
            if "port" in data:
                try:
                    p = int(data.get("port"))
                    if p > 0 and p < 65536:
                        _set("smtp_port", p)
                except: pass
            if "user" in data: _set("smtp_user", data.get("user"))
            new_pass = data.get("password") or data.get("pass")
            if new_pass:
                _set("smtp_pass", new_pass)

        elif section == "binance":
            if "pay_id" in data: _set("binance_pay_id", data.get("pay_id"))
            new_key = data.get("api_key")
            new_secret = data.get("api_secret")
            if new_key: _set("binance_api_key", new_key)
            if new_secret: _set("binance_api_secret", new_secret)

        elif section == "telegram":
            new_token = data.get("bot_token")
            if new_token:
                _set("bot_token", new_token)
                needs_restart = True
            if "admin_id" in data:
                try:
                    aid = int(data.get("admin_id"))
                    if aid > 0:
                        _set("admin_id", aid)
                        needs_restart = True
                except: pass

        elif section == "markup":
            if "follower_mark" in data:
                try:
                    v = float(data.get("follower_mark"))
                    if 1.0 <= v <= 10.0:
                        _set("follower_mark", round(v, 4))
                except: pass
            if "general_mark" in data:
                try:
                    v = float(data.get("general_mark"))
                    if 1.0 <= v <= 10.0:
                        _set("general_mark", round(v, 4))
                except: pass
            if changed:
                try:
                    rebuild_agg_cache()
                    cache.refresh_now() if hasattr(cache, 'refresh_now') else None
                except: pass

        elif section == "google":
            new_cid = data.get("client_id")
            if new_cid is not None:
                # السماح بالإفراغ للرجوع للافتراضي
                _set("google_client_id", new_cid, allow_empty=True)
                # إعادة توليد صفحة الهبوط لتضمين الـ client_id الجديد
                try:
                    generate_landing()
                    _invalidate_html_caches()
                except: pass
            new_url = data.get("webapp_url")
            if new_url is not None:
                u = str(new_url).strip().rstrip('/')
                if u and not u.startswith("http"):
                    u = "https://" + u
                if _set("webapp_url", u, allow_empty=True):
                    # تطبيق فوري — WEBAPP_URL يُقرأ وقت الاستخدام بكل مكان
                    globals()["WEBAPP_URL"] = u or "https://kony.store"
                    try:
                        generate_landing()
                        _invalidate_html_caches()
                    except: pass

        else:
            return jsonify({"ok": False, "error": "section مطلوبة (smtp / binance / telegram / markup / google)"})

        if not changed:
            return jsonify({"ok": True, "changed": [], "message": "لا تغييرات"})

        if not _save_app_settings():
            return jsonify({"ok": False, "error": "فشل حفظ الملف"})

        return jsonify({
            "ok": True,
            "changed": changed,
            "needs_restart": needs_restart,
            "message": "تم حفظ التعديلات" + (" — يحتاج إعادة تشغيل السيرفر للتفعيل" if needs_restart else " وتطبيقها فوراً"),
        })

    if action == "test_smtp":

        to = str(data.get("to", "") or ADMIN_EMAIL).strip()
        if not to or "@" not in to:
            return jsonify({"ok": False, "error": "إيميل المستلم غير صحيح"})
        try:
            from email.mime.text import MIMEText
            msg = MIMEText("هذا إيميل اختبار من إعدادات النظام — لو وصلك معناه SMTP يشتغل.", "plain", "utf-8")
            msg["Subject"] = "اختبار SMTP"
            msg["From"] = _email_from()
            msg["To"] = to
            ok = _smtp_send(to, msg)
            if ok:
                return jsonify({"ok": True, "message": f"تم إرسال إيميل اختبار إلى {to}"})
            return jsonify({"ok": False, "error": "فشل الإرسال — راجع إعدادات SMTP"})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)[:120]})

    if action == "test_binance":

        try:
            r = _binance_req("GET", "/sapi/v1/asset/wallet/balance")
            if isinstance(r, list):
                total = sum(float(x.get("balance", 0) or 0) for x in r if isinstance(x, dict))
                return jsonify({"ok": True, "message": f"اتصال Binance ناجح — إجمالي الرصيد ≈ ${total:.2f}"})
            return jsonify({"ok": True, "message": "اتصال Binance ناجح"})
        except Exception as e:
            err = str(e)[:140]
            return jsonify({"ok": False, "error": f"فشل الاتصال: {err}"})

    return jsonify({"ok": False, "error": "unknown_action"})

@app.route('/api/admin/system/restart', methods=['POST'])
def api_admin_system_restart():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    if str(data.get("confirm", "")).strip() != "yes":
        return jsonify({"ok": False, "error": "missing_confirm"})

    def _do_restart():

        time.sleep(1.0)
        try:
            db.save()
        except Exception as e:
            print(f"⚠️ db.save before restart: {e}")
        sys.stdout.flush(); sys.stderr.flush()
        print("🔄 إعادة تشغيل السيرفر بطلب من الأدمن...")

        try:
            script_path = os.path.abspath(sys.argv[0])
            workdir = os.path.dirname(script_path) or os.getcwd()
            python = sys.executable
            old_pid = os.getpid()

            shell_cmd = (
                f'( sleep 2; '
                f'  kill -9 {old_pid} 2>/dev/null; '
                f'  sleep 0.5; '
                f'  cd "{workdir}" && '
                f'  nohup "{python}" "{script_path}" >/dev/null 2>&1 & '
                f') >/dev/null 2>&1 < /dev/null &'
            )
            subprocess.Popen(
                shell_cmd, shell=True,
                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                start_new_session=True,
            )

            time.sleep(0.5)
            sys.stdout.flush(); sys.stderr.flush()
            os._exit(0)
        except Exception as e:
            print(f"❌ فشل إعادة التشغيل: {e}")
            sys.stdout.flush()

            try:
                os.execv(sys.executable, [sys.executable] + sys.argv)
            except:
                os._exit(1)

    threading.Thread(target=_do_restart, daemon=True).start()
    return jsonify({
        "ok": True,
        "message": "بدأت عملية إعادة التشغيل — السيرفر سيكون جاهزاً خلال 5-10 ثواني"
    })

@app.route('/api/admin/vn/purge', methods=['POST'])
def api_admin_vn_purge():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    mode = str(data.get("mode", "smart")).strip()
    cur_prov = db.vn_config.get("provider", "5sim")
    if mode == "all":

        n_c = len(db.vn_countries)
        n_s = len(db.vn_services)

        db.vn_countries.clear()
        db.vn_services.clear()
        db.save()
        return jsonify({"ok": True, "purged_countries": n_c, "purged_services": n_s, "mode": "all"})

    rm_countries = []
    for cc, c in list(db.vn_countries.items()):
        prov = c.get("_provider")
        if prov and prov != cur_prov:
            rm_countries.append(cc)
        elif not prov and cur_prov == "durianrcs":

            rm_countries.append(cc)
    for cc in rm_countries:
        db.vn_countries.pop(cc, None)
    rm_services = []
    for k, s in list(db.vn_services.items()):
        prov = s.get("_provider")
        if prov and prov != cur_prov:
            rm_services.append(k)
        elif not prov and cur_prov == "durianrcs" and not s.get("durian_pid"):

            rm_services.append(k)
    for k in rm_services:
        db.vn_services.pop(k, None)
    db.save()
    return jsonify({
        "ok": True, "mode": "smart",
        "purged_countries": len(rm_countries),
        "purged_services": len(rm_services),
        "remaining_countries": len(db.vn_countries),
        "remaining_services": len(db.vn_services),
        "current_provider": cur_prov,
    })

@app.route('/api/admin/vn/sync', methods=['POST'])
def api_admin_vn_sync():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    countries, err = vn_fetch_countries_prices()
    if err:
        db.vn_config["status"] = "error"
        db.save()
        return jsonify({"ok": False, "error": err})
    cur_prov = db.vn_config.get("provider", "5sim")

    old_countries = [cc for cc, c in db.vn_countries.items()
                     if c.get("_provider") and c.get("_provider") != cur_prov]
    for cc in old_countries:
        db.vn_countries.pop(cc, None)
    old_services = [k for k, s in db.vn_services.items()
                    if s.get("_provider") and s.get("_provider") != cur_prov]
    for k in old_services:
        db.vn_services.pop(k, None)
    purged_countries = len(old_countries)
    purged_services = len(old_services)

    if cur_prov == "durianrcs":
        legacy = [k for k, s in db.vn_services.items()
                  if not s.get("_provider") and not s.get("durian_pid")]
        for k in legacy:
            db.vn_services.pop(k, None)
        purged_services += len(legacy)

        empty_countries = [cc for cc in db.vn_countries
                           if not any(s.get("country_code") == cc for s in db.vn_services.values())]
        for cc in empty_countries:
            db.vn_countries.pop(cc, None)
        purged_countries += len(empty_countries)

    added = 0; updated = 0
    synced_keys = set()
    synced_codes = set()
    mk = float(db.vn_config.get("default_markup", 30))
    for cc, info in countries.items():
        meta = VN_COUNTRIES_DATA.get(cc)
        if not meta:
            continue
        existed = cc in db.vn_countries
        c = db.vn_countries.get(cc, {"enabled": False})
        c.update({
            "code": cc,
            "name_ar": meta["name_ar"],
            "name_en": meta["name_en"],
            "phone_code": meta["phone_code"],
            "region": meta["region"],
            "services_count": info["services_count"],
            "min_price": info["min_price"],
            "max_price": info["max_price"],
            "_provider": cur_prov,
        })

        if info.get("sp_country_id"):
            c["sp_country_id"] = info["sp_country_id"]
        if info.get("fsim_country"):
            c["fsim_country"] = info["fsim_country"]
        db.vn_countries[cc] = c
        if existed: updated += 1
        else: added += 1

        for svc_id, sinfo in info.get("raw_services", {}).items():
            key = f"{cc}:{svc_id}"
            existing = db.vn_services.get(key, {})

            country_enabled = db.vn_countries.get(cc, {}).get("enabled", False)
            default_svc_enabled = bool(country_enabled)
            rec = {
                "country_code": cc,
                "service_id": svc_id,
                "name": VN_SVC_NAMES.get(svc_id.lower(), svc_id.title()),
                "cost": sinfo["cost"],
                "user_markup": existing.get("user_markup"),
                "enabled": existing.get("enabled", default_svc_enabled),
            }

            if sinfo.get("sp_svc_id"):
                rec["sp_svc_id"] = sinfo["sp_svc_id"]
            if sinfo.get("sp_country_id"):
                rec["sp_country_id"] = sinfo["sp_country_id"]
            if sinfo.get("fsim_country"):
                rec["fsim_country"] = sinfo["fsim_country"]

            if sinfo.get("sa_svc_code"):
                rec["sa_svc_code"] = sinfo["sa_svc_code"]
            if sinfo.get("sa_country_id") is not None:
                rec["sa_country_id"] = sinfo["sa_country_id"]

            if sinfo.get("durian_pid"):
                rec["durian_pid"] = sinfo["durian_pid"]
            if sinfo.get("durian_country_iso"):
                rec["durian_country_iso"] = sinfo["durian_country_iso"]
            if sinfo.get("durian_vip"):
                rec["durian_vip"] = sinfo["durian_vip"]

            if sinfo.get("_durian_svc_name"):
                rec["name"] = sinfo["_durian_svc_name"]

            rec["_provider"] = cur_prov
            db.vn_services[key] = rec
            synced_keys.add(key)
            if rec.get("sa_svc_code"):
                synced_codes.add(str(rec["sa_svc_code"]))
    # تنظيف بقايا التصنيف الخاطئ لنفس المزوّد (sms-activate/grizzly): سجل لم يُكتب
    # بهذه المزامنة لكن رمز مزوّده كُتب تحت سلَگ صحيح آخر = بقايا تصنيف قديم خاطئ.
    # لا نمسّ سجلّاً صحيح التصنيف نفد مخزونه (رمزه غير موجود ضمن synced_codes).
    if cur_prov in ("sms-activate", "grizzly"):
        stale = [k for k, s in db.vn_services.items()
                 if s.get("_provider") == cur_prov
                 and k not in synced_keys
                 and str(s.get("sa_svc_code", "")) in synced_codes]
        for k in stale:
            db.vn_services.pop(k, None)
        purged_services += len(stale)
    db.vn_config["status"] = "ok"
    db.vn_config["countries_count"] = len(countries)
    db.vn_config["last_check"] = time.time()
    db.save()
    return jsonify({
        "ok": True, "added": added, "updated": updated, "total": len(countries),
        "purged_countries": purged_countries, "purged_services": purged_services,
        "provider": cur_prov,
    })

@app.route('/api/admin/vn/countries', methods=['POST'])
def api_admin_vn_countries():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    filter_state = str(data.get("state", "all")).strip()
    filter_region = str(data.get("region", "")).strip()
    q = str(data.get("q", "")).strip().lower()
    results = []
    for cc, c in db.vn_countries.items():
        if filter_state == "enabled" and not c.get("enabled"): continue
        if filter_state == "disabled" and c.get("enabled"): continue
        if filter_region and c.get("region") != filter_region: continue
        if q and q not in (c.get("name_ar","") + c.get("name_en","") + c.get("phone_code","")).lower(): continue
        results.append(c)
    results.sort(key=lambda x: (-int(x.get("enabled", 0)), x.get("name_ar", "")))
    return jsonify({"ok": True, "countries": results, "total": len(db.vn_countries)})

