@app.route('/api/admin/vn/country/bulk', methods=['POST'])
def api_admin_vn_country_bulk():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    enable = bool(data.get("enable"))
    region = str(data.get("region", "")).strip()
    cascade = bool(data.get("cascade", True))
    changed = 0
    svc_changed = 0
    target_ccs = set()
    for cc, c in db.vn_countries.items():
        if region and c.get("region") != region: continue
        target_ccs.add(cc)
        if c.get("enabled") != enable:
            c["enabled"] = enable
            changed += 1
    if cascade and target_ccs:
        for key, s in db.vn_services.items():
            if s.get("country_code") not in target_ccs: continue
            if s.get("enabled") != enable:
                s["enabled"] = enable
                svc_changed += 1
    db.save()
    return jsonify({"ok": True, "changed": changed, "services_changed": svc_changed})

@app.route('/api/admin/vn/country/services', methods=['POST'])
def api_admin_vn_country_services():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    cc = str(data.get("code", "")).strip().lower()
    if cc not in db.vn_countries:
        return jsonify({"ok": False, "error": "not_found"})
    country = db.vn_countries[cc]
    svcs = []
    default_mk = float(db.vn_config.get("default_markup", 30))
    for key, s in db.vn_services.items():
        if s.get("country_code") != cc: continue
        mk = s.get("user_markup")
        if mk is None:
            mk = default_mk
        cost = float(s.get("cost", 0) or 0)
        sell = round(cost * (1 + mk/100), 4)
        svcs.append({
            "key": key,
            "service_id": s.get("service_id"),
            "name": s.get("name"),
            "icon": _vn_svc_icon(s.get("service_id", "")),
            "cost": cost,
            "sell": sell,
            "markup": mk,
            "enabled": s.get("enabled", False),
        })
    svcs.sort(key=lambda x: (-int(x["enabled"]), x["cost"]))
    enabled_count = sum(1 for s in svcs if s["enabled"])
    return jsonify({
        "ok": True,
        "country": country,
        "services": svcs,
        "enabled_count": enabled_count,
        "total": len(svcs),
        "default_markup": default_mk,
    })

