@app.route('/api/admin/vn/orders', methods=['POST'])
def api_admin_vn_orders():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    filter_status = str(data.get("status", "all")).strip()
    orders = []
    for oid, o in db.vn_orders.items():
        if filter_status == "active" and o.get("status") not in ("waiting", "active"): continue
        if filter_status == "received" and o.get("status") != "received": continue
        if filter_status == "cancelled" and o.get("status") not in ("cancelled", "expired"): continue
        orders.append({**o, "id": oid})
    orders.sort(key=lambda x: x.get("created", 0), reverse=True)
    orders = orders[:100]

    stats = {
        "total": len(db.vn_orders),
        "success": sum(1 for o in db.vn_orders.values() if o.get("status") == "received"),
        "active": sum(1 for o in db.vn_orders.values() if o.get("status") in ("waiting", "active")),
        "cancelled": sum(1 for o in db.vn_orders.values() if o.get("status") in ("cancelled", "expired")),
    }
    return jsonify({"ok": True, "orders": orders, "stats": stats})

@app.route('/api/vn/countries', methods=['GET'])
def api_vn_countries():

    if not db.vn_config.get("enabled"):
        return jsonify({"ok": False, "error": "disabled"})
    cur_prov = db.vn_config.get("provider", "5sim")
    countries = []
    default_mk = float(db.vn_config.get("default_markup", 30))
    for cc, c in db.vn_countries.items():
        if not c.get("enabled"): continue

        if c.get("_provider") and c.get("_provider") != cur_prov: continue

        enabled_svcs_prices = []
        for key, s in db.vn_services.items():
            if s.get("country_code") != cc or not s.get("enabled"): continue
            if s.get("_provider") and s.get("_provider") != cur_prov: continue

            if cur_prov == "durianrcs" and not s.get("durian_pid"): continue
            mk = s.get("user_markup")
            if mk is None: mk = default_mk
            cost = float(s.get("cost", 0) or 0)
            enabled_svcs_prices.append(round(cost * (1 + mk/100), 4))
        if not enabled_svcs_prices: continue
        countries.append({
            "code": cc,
            "name": c.get("name_ar", cc),
            "phone_code": c.get("phone_code", ""),
            "region": c.get("region", ""),
            "services_count": len(enabled_svcs_prices),
            "min_price": round(min(enabled_svcs_prices), 4),
            "max_price": round(max(enabled_svcs_prices), 4),
        })
    countries.sort(key=lambda x: x["min_price"])
    return jsonify({"ok": True, "countries": countries})

@app.route('/api/vn/services', methods=['GET'])
def api_vn_services():

    cc = freq.args.get("country", "").strip().lower()
    if not db.vn_config.get("enabled"):
        return jsonify({"ok": False, "error": "disabled"})
    if cc not in db.vn_countries or not db.vn_countries[cc].get("enabled"):
        return jsonify({"ok": False, "error": "country_not_available"})
    cur_prov = db.vn_config.get("provider", "5sim")
    country = db.vn_countries[cc]
    if country.get("_provider") and country.get("_provider") != cur_prov:
        return jsonify({"ok": False, "error": "country_not_available"})
    default_mk = float(db.vn_config.get("default_markup", 30))
    svcs = []
    for key, s in db.vn_services.items():
        if s.get("country_code") != cc or not s.get("enabled"): continue

        if s.get("_provider") and s.get("_provider") != cur_prov: continue

        if cur_prov == "durianrcs" and not s.get("durian_pid"): continue
        mk = s.get("user_markup")
        if mk is None: mk = default_mk
        cost = float(s.get("cost", 0) or 0)
        sell = round(cost * (1 + mk/100), 4)
        svcs.append({
            "service_id": s.get("service_id"),
            "name": s.get("name"),
            "icon": _vn_svc_icon(s.get("service_id", "")),
            "price": sell,
        })

    POPULAR_ORDER = [
        "whatsapp", "telegram", "instagram", "facebook", "tiktok",
        "twitter", "google", "gmail", "discord", "snapchat",
        "youtube", "viber", "signal", "wechat", "line",
        "microsoft", "apple", "netflix", "spotify", "amazon",
        "paypal", "binance", "tinder", "linkedin", "uber",
        "bolt", "steam", "twitch", "reddit",

        "wa", "tg", "ig", "fb", "tk", "mm", "tw", "go", "gm",
        "ds", "dc", "ym", "vi", "mb", "ms", "wg", "wx",
    ]
    priority_map = {name: i for i, name in enumerate(POPULAR_ORDER)}
    def _svc_sort_key(x):
        sid = (x.get("service_id") or "").lower()
        nm = (x.get("name") or "").lower()

        if sid in priority_map:
            return (0, priority_map[sid], x.get("price", 0))

        for k, pri in priority_map.items():
            if k in nm or k in sid:
                return (0, pri, x.get("price", 0))

        return (1, nm, x.get("price", 0))
    svcs.sort(key=_svc_sort_key)
    return jsonify({
        "ok": True,
        "country": {
            "code": cc,
            "name": country.get("name_ar"),
            "phone_code": country.get("phone_code"),
        },
        "services": svcs,
    })

def _vn_err_to_ar(err):

    if not err: return "حدث خطأ، حاول لاحقاً"
    e = str(err).strip().upper()

    if "NO_NUMBERS" in e:
        return "لا توجد أرقام متاحة لهذه الخدمة حالياً — جرّب دولة ثانية أو خدمة ثانية"
    if "NO_BALANCE" in e:
        return "رصيد المزود غير كافٍ — تواصل مع الدعم"
    if "BAD_KEY" in e:
        return "مفتاح API غير صحيح — يحتاج تحديث من لوحة الأدمن"
    if "BAD_ACTION" in e:
        return "العملية غير مدعومة من المزود"
    if "BAD_SERVICE" in e:
        return "هذه الخدمة غير مدعومة — جرّب خدمة ثانية"
    if "SERVICE_UNAVAILABLE_REGION" in e:
        return "الخدمة غير متاحة من منطقتك — المزود حاجب IP المخدم"
    if "WRONG_SERVICE" in e or "WRONG_COUNTRY" in e:
        return "الخدمة أو الدولة غير صحيحة"
    if "ERROR_SQL" in e or "SQL_ERROR" in e or "SERVER_ERROR" in e:
        return "خطأ مؤقت من المزود — حاول مرّة أخرى بعد قليل"
    if "MAX_PRICE_EXCEEDED" in e:
        return "السعر تجاوز الحد الأقصى المسموح"
    if "OPERATORS_NOT_AVAILABLE" in e:
        return "مشغّل الشبكة غير متاح الآن"

    if "NO STOCK" in e.upper() or "OUT_OF_STOCK" in e:
        return "نفذت الأرقام لهذه الخدمة — جرّب خدمة ثانية"
    if "FORBIDDEN" in e:
        return "الطلب مرفوض من المزود"

    if e.startswith("HTTP "):
        return f"خطأ اتصال مع المزود ({e})"
    if "COUNTRY_NOT_MAPPED" in e:
        return "هذه الدولة غير معرّفة عند المزود"
    if "INSUFFICIENT_BALANCE" in e:
        return "رصيدك غير كافٍ"
    if "RATE_LIMIT" in e:
        return "طلبات كثيرة بوقت قصير — انتظر دقيقة"
    if "DISABLED" in e:
        return "قسم الأرقام الوهمية متوقّف حالياً"
    if "SERVICE_NOT_AVAILABLE" in e:
        return "الخدمة غير متاحة"

    if len(str(err)) < 60 and str(err).replace("_","").isalnum():
        return f"خطأ من المزود: {err}"
    return "تعذّر إتمام الطلب — جرّب مرة ثانية"

def _vn_detect_country_from_phone(phone):

    if not phone: return (None, None)
    s = str(phone).strip().lstrip("+").replace(" ", "").replace("-", "")
    if not s.isdigit(): return (None, None)

    codes = []
    for iso, info in VN_COUNTRIES_DATA.items():
        pc = str(info.get("phone_code", "") or "").lstrip("+").strip()
        if pc and pc.isdigit():
            codes.append((pc, iso))

    codes.sort(key=lambda x: -len(x[0]))
    for pc, iso in codes:
        if s.startswith(pc):
            return (iso, "+" + pc)
    return (None, None)

@app.route('/api/vn/buy', methods=['POST'])
def api_vn_buy():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    if user.get("banned"):
        return jsonify({"ok": False, "error": "banned"})
    if not db.vn_config.get("enabled"):
        return jsonify({"ok": False, "error": "disabled"})
    if not sensitive_rate_check(freq.remote_addr, "vn_buy"):
        return jsonify({"ok": False, "error": "rate_limit"}), 429
    cc = str(data.get("country", "")).strip().lower()
    svc_id = str(data.get("service", "")).strip().lower()
    key = f"{cc}:{svc_id}"
    if key not in db.vn_services or not db.vn_services[key].get("enabled"):
        return jsonify({"ok": False, "error": "service_not_available"})
    s = db.vn_services[key]
    default_mk = float(db.vn_config.get("default_markup", 30))
    mk = s.get("user_markup")
    if mk is None: mk = default_mk
    cost_provider = float(s.get("cost", 0) or 0)
    sell_price = round(cost_provider * (1 + mk/100), 4)

    # حارس ضد الشراء المزدوج: لا نسمح بطلبين متزامنين لنفس المستخدم
    if not _vn_buy_guard_acquire(uid):
        return jsonify({"ok": False, "error": "طلب شراء قيد التنفيذ — انتظر لحظة"})

    reserved = False
    try:
        # حجز الرصيد ذرّياً قبل الشراء (يمنع سباق فحص-ثم-خصم والخصم المزدوج)
        if uid != ADMIN_ID:
            if not db.try_debit(uid, sell_price):
                bal = db.get_bal(uid)
                return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": sell_price})
            reserved = True

        MAX_RETRIES = 5
        res = None
        last_err = None
        attempts = 0
        skipped_phones = []
        while attempts < MAX_RETRIES:
            attempts += 1
            res = vn_buy_number(cc, svc_id)
            if not res.get("ok"):
                last_err = res.get("error", "buy_failed")
                break
            bought_phone = str(res.get("phone", "")).strip()
            if not bought_phone:
                last_err = "empty_phone_response"
                res = None
                break
            if _vn_is_blacklisted(uid, bought_phone):
                skipped_phones.append(bought_phone)
                try:
                    vn_cancel_provider_order(res.get("order_id", ""))
                except Exception:
                    pass
                print(f"[VN] phone {bought_phone} blacklisted for uid={uid} — retry {attempts}/{MAX_RETRIES}")
                res = None
                time.sleep(0.6)
                continue
            break

        if not res or not res.get("ok"):
            # فشل الشراء — نعيد الرصيد المحجوز
            if reserved:
                db.add_bal(uid, sell_price)
                reserved = False
            if skipped_phones and not last_err:
                err_raw = "no_fresh_number"
                err_ar = f"كل الأرقام المتاحة سبق شراؤها — جرّب لاحقاً أو غيّر الدولة (تم تجاوز {len(skipped_phones)} رقم)"
                return jsonify({"ok": False, "error": err_ar, "error_raw": err_raw, "skipped": len(skipped_phones)})
            err_raw = (res or {}).get("error", last_err or "buy_failed")
            err_ar = _vn_err_to_ar(err_raw)
            return jsonify({"ok": False, "error": err_ar, "error_raw": err_raw})

        oid = "vn_" + secrets.token_hex(5)
        ttl = int(db.vn_config.get("number_ttl", 20) or 20)
        now = time.time()
        phone = res.get("phone", "")

        # ـ مصدر الحقيقة للعرض = الدولة التي اختارها المستخدم ودفع مقابلها وفّاها المزوّد.
        # كنّا سابقاً نعيد تسمية الدولة بناءً على بادئة الرقم، لكن أكواد كثيرة مشتركة
        # (‎+1 أمريكا/كندا، ‎+7 روسيا/كازاخستان…) فتظهر دولة خاطئة. تركنا الاختيار كما هو
        # ونحتفظ بالكشف كتشخيص فقط (للّوگ وحقل diagnostics) دون تغيير العرض.
        country = db.vn_countries.get(cc, {}) or VN_COUNTRIES_DATA.get(cc, {})
        final_cc = cc
        final_pcode = country.get("phone_code", "")
        final_name = country.get("name_ar", cc.upper())

        detected_iso, detected_pcode = _vn_detect_country_from_phone(phone)
        if detected_iso and detected_iso != cc:
            print(f"[VN] NOTE: selected cc={cc}({final_pcode}) phone={phone} "
                  f"prefix-detected={detected_iso}({detected_pcode}) "
                  f"provider_country={res.get('provider_country','')}. "
                  f"Keeping selected country for display.")

        order_obj = {
            "uid": uid,
            "country_code": final_cc,
            "country_name": final_name,
            "country_flag": final_cc,
            "phone_code": final_pcode,
            "requested_country": cc,
            "provider_country": res.get("provider_country", ""),
            "detected_country": detected_iso or "",
            "operator": res.get("operator", ""),
            "service_id": svc_id,
            "service_name": s.get("name", svc_id),
            "service_icon": _vn_svc_icon(svc_id),
            "phone": phone,
            "provider_order_id": res.get("order_id", ""),
            "status": "waiting",
            "cost": cost_provider,
            "sell": sell_price,
            "refunded": False,
            "sms_text": "",
            "sms_code": "",
            "created": now,
            "expires": now + (ttl * 60),
            "_last_poll": 0,
        }
        with _VN_LOCK:
            db.vn_orders[oid] = order_obj
        reserved = False  # الرصيد الآن مدفوع فعلاً مقابل طلب قائم
        db.save()

        _safe_buy = {k: v for k, v in db.vn_orders[oid].items() if k != "provider_order_id"}
        return jsonify({"ok": True, "order_id": oid, "order": _safe_buy})
    finally:
        # أمان إضافي: لو خرجنا بسبب استثناء بعد الحجز ولم نُنشئ طلباً، نعيد الرصيد
        if reserved:
            try: db.add_bal(uid, sell_price)
            except Exception: pass
        _vn_buy_guard_release(uid)

@app.route('/api/vn/order', methods=['GET'])
def api_vn_order():

    oid = freq.args.get("id", "").strip()
    data = {"token": freq.args.get("token", "")}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    if oid not in db.vn_orders:
        return jsonify({"ok": False, "error": "not_found"})
    o = db.vn_orders[oid]
    if o.get("uid") != user['id'] and user['id'] != ADMIN_ID:
        return jsonify({"ok": False, "error": "forbidden"})

    changed = False
    if o.get("status") in ("waiting", "active"):
        if o.get("expires") and time.time() > o["expires"]:
            with _VN_LOCK:
                if _vn_expire_order(oid, o):
                    changed = True
        else:
            prov_oid = o.get("provider_order_id")
            if prov_oid:
                res = vn_check_sms(prov_oid)
                if _vn_apply_check_result(oid, o, res):
                    changed = True
    if changed:
        db.save()

    remaining = max(0, int(o.get("expires", 0) - time.time())) if o.get("expires") else 0

    safe_o = {k: v for k, v in o.items() if k != "provider_order_id"}
    return jsonify({"ok": True, "order": {**safe_o, "id": oid, "remaining": remaining}})

@app.route('/api/vn/cancel', methods=['POST'])
def api_vn_cancel():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    oid = str(data.get("id", "")).strip()
    if oid not in db.vn_orders:
        return jsonify({"ok": False, "error": "not_found"})
    o = db.vn_orders[oid]
    if o.get("uid") != user['id'] and user['id'] != ADMIN_ID:
        return jsonify({"ok": False, "error": "forbidden"})

    # كل القرار يتم داخل القفل: نتأكد أن الطلب ما زال قابلاً للإلغاء (لم يصل كود
    # ولم يُلغَ من المزوّد في نفس اللحظة)، ثم نسترد مرّة واحدة فقط.
    with _VN_LOCK:
        if o.get("status") not in ("waiting", "active"):
            # ربما وصل الكود للتو أو أُلغي مسبقاً — نرفض الإلغاء (لا استرداد لرقم استلم كوداً)
            return jsonify({"ok": False, "error": "cannot_cancel", "status": o.get("status")})
        o["status"] = "cancelled"
        o["cancelled_at"] = time.time()
        o["cancel_reason"] = "cancelled_by_user"
        refunded = _vn_refund_order(o, oid, "cancelled_by_user")
        phone = str(o.get("phone", "")).strip()
        if phone:
            _vn_add_to_blacklist(
                o.get("uid"), phone,
                reason="cancelled_by_user",
                country=o.get("country_code", ""),
                service=o.get("service_id", ""),
            )

    # إلغاء عند المزوّد خارج القفل (نداء شبكة)
    prov_oid = o.get("provider_order_id")
    if prov_oid:
        try: vn_cancel_provider_order(prov_oid)
        except: pass

    db.save()
    return jsonify({"ok": True, "refunded": bool(refunded)})

