@app.route('/api/charge_games', methods=['GET'])
def api_public_charge_games():

    result = {gid: g for gid, g in db.charge_games.items() if g.get("active", True)}
    body = json.dumps({"ok": True, "games": result}, ensure_ascii=False, separators=(',',':'))

    etag = hashlib.md5(body.encode('utf-8')).hexdigest()[:16]
    inm = freq.headers.get('If-None-Match', '')
    if inm == etag:
        resp = make_response('', 304)
        resp.headers['ETag'] = etag
        resp.headers['Cache-Control'] = 'public, max-age=60'
        return resp
    resp = make_response(body, 200)
    resp.headers['Content-Type'] = 'application/json; charset=utf-8'
    resp.headers['ETag'] = etag
    resp.headers['Cache-Control'] = 'public, max-age=60'
    return resp

