def _compress_game_image(data_url, max_w=800, max_h=400, quality=70):

    try:
        from PIL import Image
        import base64
        if ',' not in data_url: return data_url
        header, b64 = data_url.split(',', 1)
        img_bytes = base64.b64decode(b64)
        img = Image.open(io.BytesIO(img_bytes))
        if img.mode == 'RGBA':
            bg = Image.new('RGB', img.size, (0, 0, 0))
            bg.paste(img, mask=img.split()[3])
            img = bg
        elif img.mode != 'RGB':
            img = img.convert('RGB')
        w, h = img.size
        if w > max_w or h > max_h:
            ratio = min(max_w / w, max_h / h)
            img = img.resize((int(w * ratio), int(h * ratio)), Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format='JPEG', quality=quality, optimize=True)
        compressed = base64.b64encode(buf.getvalue()).decode()
        result = f"data:image/jpeg;base64,{compressed}"
        print(f"🖼️ Image compressed: {len(b64)//1024}KB → {len(compressed)//1024}KB")
        return result
    except ImportError:
        print("⚠️ Pillow not installed — pip install Pillow")
        return data_url
    except Exception as e:
        print(f"⚠️ Image compress error: {e}")
        return data_url

def _compress_game_icon(data_url, size=256, quality=82):

    try:
        from PIL import Image
        import base64
        if ',' not in data_url: return data_url
        header, b64 = data_url.split(',', 1)
        img_bytes = base64.b64decode(b64)
        img = Image.open(io.BytesIO(img_bytes))
        if img.mode == 'RGBA':
            bg = Image.new('RGB', img.size, (0, 0, 0))
            bg.paste(img, mask=img.split()[3])
            img = bg
        elif img.mode != 'RGB':
            img = img.convert('RGB')

        w, h = img.size
        if w != h:
            side = min(w, h)
            left = (w - side) // 2
            top = (h - side) // 2
            img = img.crop((left, top, left + side, top + side))

        if img.size[0] > size:
            img = img.resize((size, size), Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format='JPEG', quality=quality, optimize=True)
        compressed = base64.b64encode(buf.getvalue()).decode()
        result = f"data:image/jpeg;base64,{compressed}"
        print(f"🎯 Icon compressed: {len(b64)//1024}KB → {len(compressed)//1024}KB ({size}×{size})")
        return result
    except ImportError:
        print("⚠️ Pillow not installed — pip install Pillow")
        return data_url
    except Exception as e:
        print(f"⚠️ Icon compress error: {e}")
        return data_url

@app.route('/api/admin/charge_games/add', methods=['POST'])
def api_admin_charge_games_add():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    name = str(data.get("name", "")).strip()
    unit = str(data.get("unit", "")).strip()
    image = str(data.get("image", "")).strip()
    icon = str(data.get("icon", "")).strip()
    packages = data.get("packages", [])
    if not name or not unit or not image:
        return jsonify({"ok": False, "error": "missing_fields"})
    if not isinstance(packages, list) or not packages:
        return jsonify({"ok": False, "error": "no_packages"})
    image = _compress_game_image(image)

    if icon:
        icon = _compress_game_icon(icon)

    clean_packages = []
    for p in packages:
        if not isinstance(p, dict): continue
        amt = str(p.get("amount", "")).strip()
        try: pr_id = float(p.get("price_id", p.get("price", 0)) or 0)
        except: pr_id = 0
        try: pr_acc = float(p.get("price_account", p.get("price", 0)) or 0)
        except: pr_acc = 0
        if not amt or (pr_id <= 0 and pr_acc <= 0): continue
        if pr_id <= 0: pr_id = pr_acc
        if pr_acc <= 0: pr_acc = pr_id
        clean_packages.append({
            "amount": amt,
            "price_id": pr_id,
            "price_account": pr_acc,
            "price": pr_id,
            "badge": str(p.get("badge", "")).strip()
        })
    if not clean_packages:
        return jsonify({"ok": False, "error": "no_valid_packages"})

    emoji = str(data.get("emoji", "")).strip() or "💎"
    if emoji not in ("💎", "🧩", "🪙", "💳", "🥇"):
        emoji = "💎"

    m = data.get("methods") or {}
    methods = {
        "id":      bool(m.get("id", True)),
        "account": bool(m.get("account", True)),
        "airdrop": bool(m.get("airdrop", False)),
    }
    if not any(methods.values()):
        methods["id"] = True

    gid = f"cg_{int(time.time())}_{secrets.token_hex(3)}"
    db.charge_games[gid] = {
        "id": gid,
        "name": name,
        "category": str(data.get("category", "")).strip(),
        "unit": unit,
        "image": image,
        "icon": icon,
        "emoji": emoji,
        "methods": methods,
        "packages": clean_packages,
        "active": True,
        "created": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    db.save()
    return jsonify({"ok": True, "id": gid})

@app.route('/api/admin/charge_games/edit', methods=['POST'])
def api_admin_charge_games_edit():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    gid = str(data.get("id", "")).strip()
    if gid not in db.charge_games:
        return jsonify({"ok": False, "error": "not_found"})
    g = db.charge_games[gid]
    if "name" in data: g["name"] = str(data["name"]).strip() or g["name"]
    if "category" in data: g["category"] = str(data["category"]).strip()
    if "unit" in data: g["unit"] = str(data["unit"]).strip() or g["unit"]
    if "image" in data and str(data["image"]).strip(): g["image"] = _compress_game_image(str(data["image"]).strip())

    if "icon" in data:
        ic_val = str(data["icon"]).strip()
        if ic_val == "CLEAR":
            g["icon"] = ""
        elif ic_val:
            g["icon"] = _compress_game_icon(ic_val)
    if "active" in data: g["active"] = bool(data["active"])

    if "emoji" in data:
        em = str(data.get("emoji", "")).strip()
        if em in ("💎", "🧩", "🪙", "💳", "🥇"):
            g["emoji"] = em

    if "methods" in data and isinstance(data.get("methods"), dict):
        m = data["methods"]
        new_methods = {
            "id":      bool(m.get("id", True)),
            "account": bool(m.get("account", True)),
            "airdrop": bool(m.get("airdrop", False)),
        }
        if any(new_methods.values()):
            g["methods"] = new_methods

    if "packages" in data:
        packages = data.get("packages", [])
        if isinstance(packages, list) and packages:
            clean = []
            for p in packages:
                if not isinstance(p, dict): continue
                amt = str(p.get("amount", "")).strip()
                try: pr_id = float(p.get("price_id", p.get("price", 0)) or 0)
                except: pr_id = 0
                try: pr_acc = float(p.get("price_account", p.get("price", 0)) or 0)
                except: pr_acc = 0
                if not amt or (pr_id <= 0 and pr_acc <= 0): continue
                if pr_id <= 0: pr_id = pr_acc
                if pr_acc <= 0: pr_acc = pr_id
                clean.append({
                    "amount": amt,
                    "price_id": pr_id,
                    "price_account": pr_acc,
                    "price": pr_id,
                    "badge": str(p.get("badge", "")).strip()
                })
            if clean: g["packages"] = clean
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/charge_games/delete', methods=['POST'])
def api_admin_charge_games_delete():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    gid = str(data.get("id", "")).strip()
    if gid in db.charge_games:
        del db.charge_games[gid]
        db.save()
    return jsonify({"ok": True})

# ════════════════════════════════════════════════════════════════════
#  g2bulk — مزوّد شحن الألعاب والبطاقات الرقمية (REST API v1)
#  يحل محل قسم شحن الألعاب اليدوي القديم — تلقائي بالكامل
# ════════════════════════════════════════════════════════════════════

def _g2_cfg():
    cfg = getattr(db, "g2bulk", None)
    if not isinstance(cfg, dict):
        cfg = {}
        db.g2bulk = cfg
    return cfg

def _g2_base():
    return (_g2_cfg().get("base_url") or "https://api.g2bulk.com/v1").rstrip("/")

def _g2_call(path, method="GET", body=None, timeout=25):
    """استدعاء g2bulk REST v1 — المفتاح بالـ header. يرجّع (http_status, data_dict)."""
    cfg = _g2_cfg()
    key = (cfg.get("api_key") or "").strip()
    if not key:
        return 0, {"success": False, "error": "no_api_key"}
    url = _g2_base() + path
    headers = {"X-API-Key": key, "Content-Type": "application/json", "Accept": "application/json"}
    try:
        if method.upper() == "GET":
            r = requests.get(url, headers=headers, timeout=timeout)
        else:
            r = requests.post(url, headers=headers, json=(body or {}), timeout=timeout)
        try:
            data = r.json()
        except Exception:
            data = {}
        if not isinstance(data, dict):
            data = {"_raw": data}
        return r.status_code, data
    except Exception as e:
        return 0, {"success": False, "error": str(e)}

def _g2_err(d, st):
    """استخراج رسالة خطأ g2bulk الحقيقية من الرد (error / message / detail.message) بدل http_xxx المبهم."""
    if isinstance(d, dict):
        msg = d.get("error") or d.get("message")
        if not msg:
            det = d.get("detail")
            if isinstance(det, dict):
                msg = det.get("message") or det.get("error")
            elif isinstance(det, str):
                msg = det
        if msg:
            return str(msg).strip()[:200]
    return f"http_{st}"

def _g2_markup(kind):
    cfg = _g2_cfg()
    try:
        mk = float(cfg.get("game_markup" if kind == "game" else "card_markup", 0) or 0)
    except (ValueError, TypeError):
        mk = 0.0
    return mk if mk >= 0 else 0.0

def _g2_sell_usd(provider_usd, kind="game"):
    """سعر المزوّد بالدولار → سعر البيع للزبون بالدولار (مع نسبة الربح)."""
    try:
        base = float(provider_usd or 0)
    except (ValueError, TypeError):
        base = 0.0
    return round(base * (1 + _g2_markup(kind) / 100.0), 4)

def _g2_game_needs_id(code):
    """هل اللعبة تحتاج معرّف من الزبون (آيدي/يوزرنيم..)؟ من /games/fields."""
    try:
        st, d = _g2_call("/games/fields", "POST", {"game": code})
        info = (d or {}).get("info", {}) if isinstance(d, dict) else {}
        fields = info.get("fields", []) if isinstance(info, dict) else []
        idpat = ("userid", "user_id", "playerid", "player_id", "id", "uid",
                 "openid", "account", "username", "user", "email", "phone")
        for f in (fields or []):
            if str(f).strip().lower() in idpat:
                return True
        return False
    except Exception:
        return True  # احتياطاً نطلب الآيدي عند الشك

def _g2_norm_status(s):
    """توحيد حالة g2bulk → done/pending/processing/failed."""
    s = str(s or "").strip().lower()
    if s in ("completed", "complete", "success", "done"):
        return "done"
    if s in ("processing", "in progress", "in_progress"):
        return "processing"
    if s in ("failed", "fail", "canceled", "cancelled", "refunded", "error"):
        return "failed"
    return "pending"

def _g2_refund(order):
    """إرجاع رصيد الزبون مرة واحدة فقط (idempotent عبر علم refunded)."""
    if not order or order.get("refunded"):
        return
    uid = order.get("uid")
    cost = float(order.get("cost", 0) or 0)
    if uid and uid != ADMIN_ID and cost > 0:
        db.add_bal(uid, cost)
        order["refunded"] = True
        try:
            push_user_notif(uid, "system", "💰 تم إرجاع رصيدك",
                            f"تعذّر تنفيذ طلب {order.get('title','')} — رجعنا {cost:.2f}$ لرصيدك", "wallet")
        except Exception:
            pass
    else:
        order["refunded"] = True

