@app.route('/api/admin/g2/config', methods=['POST'])
def api_admin_g2_config():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    cfg = _g2_cfg()
    if "api_key" in data:
        k = str(data.get("api_key", "")).strip()
        if k and not k.startswith("•"):  # لا تكتب فوق المفتاح بالنقاط المخفية
            cfg["api_key"] = k
    if "base_url" in data and str(data.get("base_url", "")).strip():
        cfg["base_url"] = str(data["base_url"]).strip().rstrip("/")
    if "enabled" in data:
        cfg["enabled"] = bool(data["enabled"])
    for fld in ("game_markup", "card_markup"):
        if fld in data:
            try:
                cfg[fld] = max(0.0, float(data[fld]))
            except (ValueError, TypeError):
                pass
    db.save()
    masked = ""
    if cfg.get("api_key"):
        kk = cfg["api_key"]
        masked = ("•" * max(0, len(kk) - 8)) + kk[-8:]
    return jsonify({"ok": True, "config": {
        "enabled": cfg.get("enabled", False),
        "base_url": cfg.get("base_url"),
        "game_markup": cfg.get("game_markup", 0),
        "card_markup": cfg.get("card_markup", 0),
        "api_key_masked": masked,
        "last_sync": cfg.get("last_sync", ""),
        "games_count": len(cfg.get("games", []) or []),
        "cards_count": len(cfg.get("cards", []) or []),
    }})

@app.route('/api/admin/g2/balance', methods=['POST'])
def api_admin_g2_balance():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    st, d = _g2_call("/getMe", "GET")
    if st == 200 and d.get("success"):
        return jsonify({"ok": True, "balance": d.get("balance", 0),
                        "username": d.get("username", ""), "user_id": d.get("user_id", "")})
    return jsonify({"ok": False, "error": _g2_err(d, st)})

@app.route('/api/admin/g2/sync', methods=['POST'])
def api_admin_g2_sync():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    cfg = _g2_cfg()
    out = {"games": 0, "cards": 0, "categories": 0, "errors": []}
    # 1) الألعاب
    st, d = _g2_call("/games", "GET")
    if st == 200 and isinstance(d.get("games"), list):
        cfg["games"] = [{
            "id": g.get("id"), "code": g.get("code"), "name": g.get("name"),
            "image_url": g.get("image_url", ""), "enabled": True
        } for g in d["games"] if g.get("code")]
        out["games"] = len(cfg["games"])
    else:
        out["errors"].append("games:" + str(d.get("error") or st))
    # 2) فئات البطاقات
    st, d = _g2_call("/category", "GET")
    if st == 200 and isinstance(d.get("categories"), list):
        cfg["card_categories"] = [{
            "id": c.get("id"), "title": c.get("title"),
            "image_url": c.get("image_url", ""), "product_count": c.get("product_count", 0)
        } for c in d["categories"]]
        out["categories"] = len(cfg["card_categories"])
    else:
        out["errors"].append("categories:" + str(d.get("error") or st))
    # 3) منتجات البطاقات
    st, d = _g2_call("/products", "GET")
    if st == 200 and isinstance(d.get("products"), list):
        cfg["cards"] = [{
            "id": p.get("id"), "title": p.get("title"), "category_id": p.get("category_id"),
            "category_title": p.get("category_title", ""), "unit_price": p.get("unit_price", 0),
            "image_url": p.get("image_url", ""), "stock": p.get("stock", 0), "enabled": True
        } for p in d["products"]]
        out["cards"] = len(cfg["cards"])
    else:
        out["errors"].append("products:" + str(d.get("error") or st))
    cfg["last_sync"] = time.strftime("%Y-%m-%d %H:%M:%S")
    db.save()
    return jsonify({"ok": True, "synced": out, "last_sync": cfg["last_sync"]})

