@app.route('/api/g2/game/catalogue', methods=['POST'])
def api_g2_game_catalogue():
    data = freq.json or {}
    code = str(data.get("code", "")).strip()
    if not code:
        return jsonify({"ok": False, "error": "no_code"})
    st, d = _g2_call(f"/games/{code}/catalogue", "GET")
    if st != 200 or not isinstance(d, dict) or not d.get("success"):
        return jsonify({"ok": False, "error": _g2_err(d, st)})
    cats = []
    for c in (d.get("catalogues") or []):
        sell = _g2_sell_usd(c.get("amount", 0), "game")
        cats.append({"id": c.get("id"), "name": c.get("name"),
                     "usd": sell, "provider_usd": c.get("amount", 0)})
    return jsonify({"ok": True, "game": d.get("game", {}), "catalogues": cats})

@app.route('/api/g2/game/order', methods=['POST'])
def api_g2_game_order():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    cfg = _g2_cfg()
    if not cfg.get("enabled"):
        return jsonify({"ok": False, "error": "disabled"})
    uid = user['id']
    code = str(data.get("code", "")).strip()
    cat_name = str(data.get("catalogue_name", "")).strip()
    player_id = str(data.get("player_id", "")).strip()
    server_id = str(data.get("server_id", "")).strip()
    charname = str(data.get("charname", "")).strip()
    if not code or not cat_name:
        return jsonify({"ok": False, "error": "missing_fields"})
    if _g2_game_needs_id(code) and not player_id:
        return jsonify({"ok": False, "error": "missing_fields"})
    # السعر الموثوق من الكتالوج الحي
    st, d = _g2_call(f"/games/{code}/catalogue", "GET")
    if st != 200 or not isinstance(d, dict) or not d.get("success"):
        return jsonify({"ok": False, "error": "catalogue_unavailable"})
    match = None
    for c in (d.get("catalogues") or []):
        if str(c.get("name")) == cat_name:
            match = c
            break
    if not match:
        return jsonify({"ok": False, "error": "package_not_found"})
    cost = _g2_sell_usd(match.get("amount", 0), "game")
    if cost <= 0:
        return jsonify({"ok": False, "error": "bad_price"})
    bal = db.get_bal(uid)
    if uid != ADMIN_ID and bal < cost:
        return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})
    if uid != ADMIN_ID:
        db.sub_bal(uid, cost)
    # إرسال الطلب
    body = {"catalogue_name": cat_name}
    if player_id:
        body["player_id"] = player_id
    if server_id:
        body["server_id"] = server_id
    if charname:
        body["charname"] = charname
    gst, gd = _g2_call(f"/games/{code}/order", "POST", body, timeout=40)
    ok = (gst == 200 and isinstance(gd, dict) and gd.get("success"))
    if not ok:
        if uid != ADMIN_ID:
            db.add_bal(uid, cost)  # فشل فوري — إرجاع مباشر
        return jsonify({"ok": False, "error": _g2_err(gd, gst)})
    g2order = gd.get("order", {}) if isinstance(gd, dict) else {}
    local_oid = f"G2-{int(time.time())}-{secrets.token_hex(2)}"
    rec = {
        "id": local_oid, "uid": uid, "type": "topup", "game_code": code,
        "title": (d.get("game", {}).get("name") or code) + " — " + cat_name,
        "catalogue_name": cat_name, "player_id": player_id, "server_id": server_id,
        "player_name": g2order.get("player_name", ""), "cost": cost,
        "g2_order_id": g2order.get("order_id"), "status": _g2_norm_status(g2order.get("status", "pending")),
        "refunded": False, "date": time.strftime("%Y-%m-%d %H:%M:%S"),
        "user_name": user.get("name", ""),
    }
    db.g2_orders[local_oid] = rec
    db.save()
    push_user_notif(uid, "order", "تم تقديم طلب الشحن!", rec["title"], "gamepad")
    return jsonify({"ok": True, "order": {
        "id": local_oid, "status": rec["status"], "title": rec["title"],
        "player_name": rec["player_name"], "cost": cost
    }, "new_balance": db.get_bal(uid)})

@app.route('/api/g2/order/status', methods=['POST'])
def api_g2_order_status():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    local_oid = str(data.get("id", "")).strip()
    rec = db.g2_orders.get(local_oid)
    if not rec or (rec.get("uid") != user['id'] and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "not_found"})
    _g2_reconcile_order(rec)
    db.save()
    return jsonify({"ok": True, "status": rec.get("status"), "refunded": rec.get("refunded", False),
                    "codes": rec.get("codes", []) if rec.get("type") == "card" else None})

def _g2_reconcile_order(rec):
    """يستعلم عن حالة الطلب من g2bulk ويحدّث السجل + يرجّع الرصيد عند الفشل."""
    if not rec or rec.get("status") in ("done", "failed"):
        return
    if rec.get("type") == "topup":
        st, d = _g2_call("/games/order/status", "POST",
                         {"order_id": rec.get("g2_order_id"), "game": rec.get("game_code")})
        new = _g2_norm_status((d or {}).get("status") or (d or {}).get("order", {}).get("status"))
        if new:
            rec["status"] = new
    else:  # card
        oid = rec.get("g2_order_id")
        st, d = _g2_call(f"/orders/{oid}/delivery", "GET")
        if st == 200 and isinstance(d, dict):
            rec["status"] = "done"
            items = d.get("delivery_items") or []
            if items:
                rec["codes"] = items
        elif st == 410:
            rec["status"] = "failed"
        elif st == 202:
            rec["status"] = "processing"
    if rec.get("status") == "failed":
        _g2_refund(rec)

