@app.route('/api/g2/cards', methods=['GET'])
def api_g2_cards():
    cfg = _g2_cfg()
    if not cfg.get("enabled"):
        return jsonify({"ok": False, "error": "disabled", "categories": [], "cards": []})
    cards = []
    for p in (cfg.get("cards") or []):
        if not p.get("enabled", True):
            continue
        cards.append({
            "id": p.get("id"), "title": p.get("title"), "category_id": p.get("category_id"),
            "category_title": p.get("category_title", ""), "usd": _g2_sell_usd(p.get("unit_price", 0), "card"),
            "image_url": p.get("image_url", ""), "stock": p.get("stock", 0)
        })
    return jsonify({"ok": True, "categories": cfg.get("card_categories", []), "cards": cards})

@app.route('/api/g2/card/buy', methods=['POST'])
def api_g2_card_buy():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    cfg = _g2_cfg()
    if not cfg.get("enabled"):
        return jsonify({"ok": False, "error": "disabled"})
    uid = user['id']
    try:
        pid = int(data.get("product_id"))
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "bad_product"})
    try:
        qty = max(1, int(data.get("quantity", 1)))
    except (ValueError, TypeError):
        qty = 1
    prod = None
    for p in (cfg.get("cards") or []):
        if p.get("id") == pid:
            prod = p
            break
    if not prod:
        return jsonify({"ok": False, "error": "product_not_found"})
    cost = round(_g2_sell_usd(prod.get("unit_price", 0), "card") * qty, 4)
    if cost <= 0:
        return jsonify({"ok": False, "error": "bad_price"})
    bal = db.get_bal(uid)
    if uid != ADMIN_ID and bal < cost:
        return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})
    if uid != ADMIN_ID:
        db.sub_bal(uid, cost)
    idem = str(uuid.uuid4())
    cfgkey = (cfg.get("api_key") or "").strip()
    url = _g2_base() + f"/products/{pid}/purchase"
    headers = {"X-API-Key": cfgkey, "Content-Type": "application/json",
               "X-Idempotency-Key": idem, "Accept": "application/json"}
    try:
        r = requests.post(url, headers=headers, json={"quantity": qty}, timeout=40)
        gd = r.json() if r.content else {}
        gst = r.status_code
    except Exception as e:
        if uid != ADMIN_ID:
            db.add_bal(uid, cost)
        return jsonify({"ok": False, "error": "network:" + str(e)})
    if gst != 200 or not isinstance(gd, dict) or not gd.get("success"):
        if uid != ADMIN_ID:
            db.add_bal(uid, cost)
        return jsonify({"ok": False, "error": _g2_err(gd, gst)})
    local_oid = f"G2C-{int(time.time())}-{secrets.token_hex(2)}"
    status = _g2_norm_status(gd.get("status", ""))
    codes = gd.get("delivery_items") or []
    if codes:
        status = "done"
    rec = {
        "id": local_oid, "uid": uid, "type": "card", "product_id": pid,
        "title": (prod.get("title") or "بطاقة") + (f" ×{qty}" if qty > 1 else ""),
        "qty": qty, "cost": cost, "g2_order_id": gd.get("order_id"),
        "status": status, "codes": codes, "refunded": False,
        "poll_url": gd.get("poll_url", ""), "date": time.strftime("%Y-%m-%d %H:%M:%S"),
        "user_name": user.get("name", ""),
    }
    db.g2_orders[local_oid] = rec
    db.save()
    push_user_notif(uid, "order", "تم شراء البطاقة!", rec["title"], "ticket")
    return jsonify({"ok": True, "order": {
        "id": local_oid, "status": status, "title": rec["title"],
        "codes": codes, "cost": cost
    }, "new_balance": db.get_bal(uid)})

@app.route('/api/g2/orders', methods=['POST'])
def api_g2_orders():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    mine = [r for r in db.g2_orders.values() if r.get("uid") == uid]
    mine.sort(key=lambda r: r.get("date", ""), reverse=True)
    return jsonify({"ok": True, "orders": mine[:100]})

def _g2_status_loop():
    """متابعة تلقائية لحالات الطلبات المعلّقة + إرجاع الرصيد عند الفشل."""
    while True:
        try:
            time.sleep(35)
            cfg = _g2_cfg()
            if not cfg.get("enabled") or not (cfg.get("api_key") or "").strip():
                continue
            pend = [r for r in list(db.g2_orders.values())
                    if r.get("status") in ("pending", "processing")]
            if not pend:
                continue
            changed = False
            for rec in pend[:40]:
                before = rec.get("status")
                try:
                    _g2_reconcile_order(rec)
                except Exception:
                    continue
                if rec.get("status") != before:
                    changed = True
                    if rec.get("status") == "done":
                        try:
                            push_user_notif(rec.get("uid"), "order", "اكتمل طلبك ✅",
                                            rec.get("title", ""), "gamepad")
                        except Exception:
                            pass
            if changed:
                db.save()
        except Exception:
            continue

threading.Thread(target=_g2_status_loop, daemon=True).start()

@app.route('/api/charge_order', methods=['POST'])
def api_charge_order():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    gid = str(data.get("game_id", "")).strip()
    game = db.charge_games.get(gid)
    if not game or not game.get("active", True):
        return jsonify({"ok": False, "error": "game_not_found"})
    try:
        pkg_idx = int(data.get("package_idx", -1))
    except:
        pkg_idx = -1
    packages = game.get("packages", [])
    if pkg_idx < 0 or pkg_idx >= len(packages):
        return jsonify({"ok": False, "error": "invalid_package"})
    pkg = packages[pkg_idx]

    method = str(data.get("method", "id")).strip().lower()
    if method not in ("id", "account", "airdrop"):
        method = "id"

    g_methods = game.get("methods") or {"id": True, "account": True, "airdrop": False}
    if not g_methods.get(method, False):
        return jsonify({"ok": False, "error": "method_not_available"})

    if method == "id":
        cost = float(pkg.get("price_id", pkg.get("price", 0)) or 0)
    else:
        cost = float(pkg.get("price_account", pkg.get("price", 0)) or 0)
    if cost <= 0:
        cost = float(pkg.get("price", 0) or 0)

    notes = str(data.get("notes", "")).strip()

    if method == "account":
        email = str(data.get("email", "")).strip()
        password = str(data.get("password", ""))
        platform = str(data.get("platform", "")).strip()
        character_name = str(data.get("character_name", "")).strip()
        if not email or not password or not platform:
            return jsonify({"ok": False, "error": "missing_account_info"})
        player_id = ""
        player_name = character_name
    elif method == "airdrop":
        email = str(data.get("email", "")).strip()
        password = str(data.get("password", ""))
        platform = ""
        character_name = str(data.get("character_name", "")).strip()
        if not email or not password:
            return jsonify({"ok": False, "error": "missing_airdrop_info"})
        player_id = ""
        player_name = character_name
    else:
        player_id = str(data.get("player_id", "")).strip()
        player_name = str(data.get("player_name", "")).strip()
        email = password = platform = character_name = ""
        if not player_id or not player_name:
            return jsonify({"ok": False, "error": "missing_player_info"})

    bal = db.get_bal(uid)
    if uid != ADMIN_ID and bal < cost:
        return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})

    if uid != ADMIN_ID:
        db.sub_bal(uid, cost)

    oid = f"CG-{int(time.time())}-{secrets.token_hex(2)}"
