@app.route('/api/admin/recommended_services/add', methods=['POST'])
def api_admin_recommended_add():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    sid = str(data.get("service_id", "")).strip()
    if not sid:
        return jsonify({"ok": False, "error": "missing service_id"})
    short = sid.rsplit(':', 1)[-1] if ':' in sid else sid
    for stored in db.recommended_services:
        st = str(stored)
        if st == sid or st == short or st.endswith(':' + short) or sid.endswith(':' + st):
            return jsonify({"ok": False, "error": "already_exists"})
    db.recommended_services.append(sid)
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/recommended_services/delete', methods=['POST'])
def api_admin_recommended_delete():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    sid = str(data.get("service_id", "")).strip()
    if not sid:
        return jsonify({"ok": True})
    short = sid.rsplit(':', 1)[-1] if ':' in sid else sid
    to_remove = []
    for stored in db.recommended_services:
        st = str(stored)
        if st == sid or st == short or st.endswith(':' + short) or sid.endswith(':' + st):
            to_remove.append(stored)
    for r in to_remove:
        if r in db.recommended_services:
            db.recommended_services.remove(r)
    if to_remove:
        db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/profits', methods=['POST'])
def api_admin_profits():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    total_revenue = 0
    total_provider = 0
    total_refunded = 0
    total_orders = 0
    for uid, orders in db.orders.items():
        for o in orders:
            c = float(o.get("cost", 0))
            total_revenue += c
            total_orders += 1

            pc = o.get("provider_cost")
            if pc is not None:
                total_provider += float(pc)
            else:

                sname = (o.get("service", "") or "").lower()
                mark = _follower_mark() if "follow" in sname or "متابع" in sname else _general_mark()
                total_provider += round(c / mark, 4) if mark > 0 else c
            if o.get("refunded"):
                total_refunded += float(o.get("refund_amount", c))
    profit = round(total_revenue - total_provider, 2)
    margin = round((profit / total_revenue * 100), 1) if total_revenue > 0 else 0
    avg_profit = round(profit / total_orders, 2) if total_orders > 0 else 0
    return jsonify({
        "ok": True,
        "revenue": round(total_revenue, 2),
        "provider_cost": round(total_provider, 2),
        "profit": profit,
        "margin": margin,
        "refunded": round(total_refunded, 2),
        "total_orders": total_orders,
        "avg_profit": avg_profit,
        "follower_mark": _follower_mark(),
        "general_mark": _general_mark()
    })

def calc_actual_spent(orders):

    total = 0
    for o in orders:
        cost = o.get("cost", 0)
        if o.get("refunded"):
            refund_amt = o.get("refund_amount", cost)
            total += cost - refund_amt
        else:
            cached = o.get("_cached_status", {})
            st = cached.get("status", "").lower() if cached else ""
            if st == "canceled":
                continue
            total += cost
    return round(total, 4)

def check_level_gift(uid):

    total_spent = calc_actual_spent(db.orders.get(uid, []) + db.orders.get(str(uid), []))
    uid_key = str(uid)
    given = db.level_gifts_given.get(uid_key, [])
    for i, lv in enumerate(db.levels):
        if i not in given and total_spent > lv["max"]:
            gift = float(lv.get("gift", 0))
            if gift > 0:
                db.add_bal(uid, gift)
                given.append(i)
                db.level_gifts_given[uid_key] = given
                db.save()
                push_user_notif(uid, "system", f"{lv['emoji']} مبروك! أكملت المستوى {lv['name']}",
                    f"تم إضافة ${gift:.2f} هدية لرصيدك", "gift")

@app.route('/api/levels', methods=['POST'])
def api_levels():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False}), 401
    uid = user['id']
    total_spent = calc_actual_spent(db.orders.get(uid, []) + db.orders.get(str(uid), []))
    given = db.level_gifts_given.get(str(uid), [])
    current = 0
    for i, lv in enumerate(db.levels):
        if total_spent >= lv["min"]:
            current = i
    lvs = []
    for i, lv in enumerate(db.levels):
        lvs.append({"name": lv["name"], "emoji": lv["emoji"], "min": lv["min"], "max": lv["max"],
            "gift": lv["gift"], "msg": lv["msg"], "done": i in given, "current": i == current})
    next_min = db.levels[current + 1]["min"] if current + 1 < len(db.levels) else None
    remaining = round(next_min - total_spent, 2) if next_min else 0
    return jsonify({"ok": True, "levels": lvs, "current": current, "total_spent": round(total_spent, 2),
        "remaining": remaining, "next_min": next_min,
        "next_name": db.levels[current + 1]["name"] if current + 1 < len(db.levels) else None,
        "next_emoji": db.levels[current + 1]["emoji"] if current + 1 < len(db.levels) else None})

