@app.route('/api/custom_order', methods=['POST'])
def api_custom_order():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    sid = data.get("service_id", "")
    svc = db.custom_services.get(sid)
    if not svc or not svc.get("active", True):
        return jsonify({"ok": False, "error": "service_not_found"})
    oid = f"CO-{int(time.time())}-{secrets.token_hex(2)}"
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    if svc.get("qty_mode") and svc.get("type") == "subscription":
        qty = int(data.get("quantity", 0) or 0)
        mn = int(svc.get("min", 1) or 1); mx = int(svc.get("max", 100) or 100)
        if qty < mn or qty > mx:
            return jsonify({"ok": False, "error": "quantity_out_of_range", "min": mn, "max": mx})
        unit = float(svc.get("unit_price", 0) or 0)
        cost = round(unit * qty, 4)
        bal = db.get_bal(uid)
        if uid != ADMIN_ID and bal < cost:
            return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})
        if uid != ADMIN_ID:
            db.sub_bal(uid, cost)
        order = {"id": oid, "uid": uid, "service_id": sid, "service_name": svc["name"],
            "type": "subscription", "qty": qty, "package": f"الكمية: {qty}", "cost": cost,
            "status": "pending", "date": now, "user_name": user.get("name", "")}
        db.custom_orders[oid] = order
        tid = str(len(db.tickets) + 1)
        tnow = time.strftime("%d/%m %H:%M")
        db.tickets[tid] = {"id": tid, "uid": uid, "subject": f"طلب اشتراك: {svc['name']} — الكمية {qty}",
            "category": "📦 طلب اشتراك", "status": "open", "date": tnow, "created": time.time(), "custom_order_id": oid,
            "messages": [{"from": "system", "text": f"🎫 طلب اشتراك جديد (حسب الكمية)\n\n{svc.get('icon','')} {svc['name']}\n🔢 الكمية: {qty}\n💵 سعر الوحدة: ${unit:.2f}\n💰 الإجمالي: ${cost:.2f}\n\nبانتظار الإدارة للتنفيذ اليدوي...", "time": tnow}]}
        db.save()
        push_user_notif(uid, "order", "تم تقديم طلب اشتراك! 📦",
            f"{svc['name']} — الكمية: {qty} — ${cost:.2f}", "box")
        try:
            bot.send_message(ADMIN_ID, f"📦 طلب اشتراك (حسب الكمية) جديد!\n\n👤 {user.get('name','')} (ID: {uid})\n{svc['name']}\n🔢 الكمية: {qty}\n💵 سعر الوحدة: ${unit:.2f}\n💰 الإجمالي: ${cost:.2f}\n🎫 تذكرة #{tid}")
        except: pass
        push_admin_notif("order", {"uid": uid, "service": svc['name'], "cost": cost})
        return jsonify({"ok": True, "order": order, "ticket_id": tid, "balance": db.get_bal(uid)})
    if svc["type"] in ("subscription", "charging"):
        is_charging = svc["type"] == "charging"
        order_label = "شحن" if is_charging else "اشتراك"
        order_emoji = "⚡" if is_charging else "📦"
        pkg_index = int(data.get("package_index", 0))
        packages = svc.get("packages", [])
        if pkg_index < 0 or pkg_index >= len(packages):
            return jsonify({"ok": False, "error": "invalid_package"})
        pkg = packages[pkg_index]
        cost = float(pkg.get("price", 0))
        bal = db.get_bal(uid)
        if uid != ADMIN_ID and bal < cost:
            return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})
        if uid != ADMIN_ID:
            db.sub_bal(uid, cost)
        order = {"id": oid, "uid": uid, "service_id": sid, "service_name": svc["name"],
            "type": svc["type"], "package": pkg.get("name", ""), "cost": cost, "status": "pending", "date": now, "user_name": user.get("name", "")}
        db.custom_orders[oid] = order

        # ═══ تسليم مباشر (إيميل و/أو اسم مستخدم) بدل فتح تذكرة — حسب إعدادات الاشتراك ═══
        email_req = bool(svc.get("email_required")) and svc["type"] == "subscription"
        user_req  = bool(svc.get("username_required")) and svc["type"] == "subscription"
        if email_req or user_req:
            email = (data.get("email") or "").strip()[:120]
            username = (data.get("username") or "").strip()[:120]
            # تحقق من الإيميل لو مطلوب
            if email_req:
                _ok_email = bool(email) and ("@" in email) and ("." in email.split("@")[-1])
                if not _ok_email:
                    # رجّع الرصيد لأننا خصمناه فوق
                    if uid != ADMIN_ID:
                        db.add_bal(uid, cost)
                    db.custom_orders.pop(oid, None)
                    return jsonify({"ok": False, "error": "invalid_email"})
            # تحقق من اسم المستخدم لو مطلوب
            if user_req:
                if not username:
                    if uid != ADMIN_ID:
                        db.add_bal(uid, cost)
                    db.custom_orders.pop(oid, None)
                    return jsonify({"ok": False, "error": "invalid_username"})
            # خزّن المعلومات + اضبط نوع التسليم
            _delivery_parts = []
            if email_req:
                order["email"] = email
                _delivery_parts.append("email")
            if user_req:
                order["username"] = username
                _delivery_parts.append("username")
            order["delivery"] = "+".join(_delivery_parts)
            db.save()
            # نص الوجهة للإشعارات
            _dest_bits = []
            if email_req: _dest_bits.append(email)
            if user_req: _dest_bits.append(username)
            _dest = " و ".join(_dest_bits)
            push_user_notif(uid, "order", "تم إرسال طلبك! 📨",
                f"{svc['name']} — {pkg.get('name','')} — سيتم تفعيل الاشتراك على {_dest}", "box")
            try:
                _admin_lines = ["📨 طلب اشتراك (تفعيل مباشر)!", "",
                                f"👤 {user.get('name','')} (ID: {uid})",
                                f"{svc['icon']} {svc['name']}",
                                f"📦 {pkg.get('name','')}",
                                f"💰 ${cost:.2f}"]
                if email_req: _admin_lines.append(f"✉️ {email}")
                if user_req:  _admin_lines.append(f"👤 {username}")
                bot.send_message(ADMIN_ID, "\n".join(_admin_lines))
            except: pass
            push_admin_notif("order", {"uid": uid, "service": svc['name'], "cost": cost})
            return jsonify({"ok": True, "order": order, "email_sent": True,
                            "email": email if email_req else "",
                            "username": username if user_req else "",
                            "balance": db.get_bal(uid)})

        tid = str(len(db.tickets) + 1)
        tnow = time.strftime("%d/%m %H:%M")
        db.tickets[tid] = {"id": tid, "uid": uid, "subject": f"طلب {order_label}: {svc['name']} — {pkg.get('name','')}", "category": f"{order_emoji} طلب {order_label}", "status": "open", "date": tnow, "created": time.time(), "custom_order_id": oid,
            "messages": [{"from": "system", "text": f"🎫 طلب {order_label} جديد\n\n{svc['icon']} {svc['name']}\n{order_emoji} الباقة: {pkg.get('name','')}\n💰 السعر: ${cost:.2f}\n⏱️ المدة: {pkg.get('duration','')}\n\nبانتظار الإدارة لإرسال التفاصيل...", "time": tnow}]}
        db.save()

        push_user_notif(uid, "order", f"تم تقديم طلب {order_label}! {order_emoji}",
            f"{svc['name']} — {pkg.get('name','')} — ${cost:.2f}", "box")
        try:
            bot.send_message(ADMIN_ID, f"{order_emoji} طلب {order_label} جديد!\n\n👤 {user.get('name','')} (ID: {uid})\n{svc['icon']} {svc['name']}\n{order_emoji} {pkg.get('name','')}\n💰 ${cost:.2f}\n🎫 تذكرة #{tid}")
        except: pass

        push_admin_notif("order", {"uid": uid, "service": svc['name'], "cost": cost})
        return jsonify({"ok": True, "order": order, "ticket_id": tid, "balance": db.get_bal(uid)})
    else:
        link = data.get("link", "").strip()
        qty = int(data.get("quantity", 0))
        comments = data.get("comments", "").strip()
        rate = float(svc.get("rate", 0))
        mn, mx = int(svc.get("min", 0)), int(svc.get("max", 0))
        if not re.match(r"^https?://", link):
            return jsonify({"ok": False, "error": "invalid_link"})
        if qty < mn or qty > mx:
            return jsonify({"ok": False, "error": "quantity_out_of_range", "min": mn, "max": mx})
        cost = round((rate * qty) / 1000.0, 4)
        bal = db.get_bal(uid)
        if uid != ADMIN_ID and bal < cost:
            return jsonify({"ok": False, "error": "insufficient_balance", "balance": bal, "cost": cost})
        if uid != ADMIN_ID:
            db.sub_bal(uid, cost)
        order = {"id": oid, "uid": uid, "service_id": sid, "service_name": svc["name"],
            "type": "social", "qty": qty, "link": link, "comments": comments, "cost": cost, "status": "pending", "date": now}
        db.custom_orders[oid] = order
        db.save()

        push_user_notif(uid, "order", "تم تقديم طلبك! 📱",
            f"{svc['name']} — الكمية: {qty} — ${cost:.4f}", "box")
        try:
            bot.send_message(ADMIN_ID, f"📱 طلب سوشيال مخصص\n\n👤 {user.get('name','')} (ID: {uid})\n{svc['icon']} {svc['name']}\n🔢 {qty}\n🔗 {link}\n💰 ${cost:.4f}" + (f"\n💬 تعليق: {comments}" if comments else ""))
        except: pass

        push_admin_notif("order", {"uid": uid, "service": svc['name'], "cost": cost})
        return jsonify({"ok": True, "order": order, "balance": db.get_bal(uid)})

