@app.route('/api/admin/custom_orders/update', methods=['POST'])
def api_admin_custom_order_update():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    oid = data.get("order_id", "")
    status = data.get("status", "")
    order = db.custom_orders.get(oid)
    if not order:
        return jsonify({"ok": False, "error": "not found"})
    order["status"] = status

    co_uid = order.get("uid")
    if co_uid:
        if status == "completed":
            _pkg_or_qty = order.get('package','') or ('الكمية: ' + str(order.get('qty',0)))
            push_user_notif(co_uid, "order", "تم اكتمال طلبك! ✅",
                f"{order.get('service_name','')} — {_pkg_or_qty}", "box")
        elif status == "canceled":
            co_cost = float(order.get("cost", 0))
            if co_cost > 0 and not order.get("refunded"):
                db.add_bal(co_uid, co_cost)
                order["refunded"] = True
            push_user_notif(co_uid, "system", "تم إلغاء طلبك المخصص ❌",
                f"{order.get('service_name','')} — تم استرجاع ${co_cost:.2f}", "wallet")
        elif status == "processing":
            push_user_notif(co_uid, "system", "طلبك قيد التنفيذ ⚙️",
                f"{order.get('service_name','')} — الإدارة تعمل على طلبك", "box")
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/users/edit', methods=['POST'])
def api_admin_user_edit():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    target = data.get("username", "")
    action = data.get("action", "")
    users = _load_web_users()
    if target not in users:
        return jsonify({"ok": False, "error": "user not found"})
    u = users[target]
    if action == "add_balance":
        try:
            amount = float(data.get("amount", 0))
        except:
            return jsonify({"ok": False, "error": "مبلغ غير صالح"})

        if abs(amount) > 10000:
            return jsonify({"ok": False, "error": "المبلغ يتجاوز الحد المسموح ($10,000)"})
        if amount == 0:
            return jsonify({"ok": False, "error": "المبلغ لا يمكن أن يكون صفر"})
        tg_id = u.get("telegram_id")
        effective_uid = tg_id if tg_id else u.get("uid", target)
        old_bal = db.get_bal(effective_uid)
        db.add_bal(effective_uid, amount)
        new_bal = db.get_bal(effective_uid)

        audit_log("admin_balance_edit", target, {
            "amount": amount, "old_balance": old_bal, "new_balance": new_bal,
            "by_admin": user.get("username", "admin"), "ip": freq.remote_addr
        })
        return jsonify({"ok": True, "new_balance": new_bal})
    elif action == "ban":
        _mutate_web_users(lambda uu: uu[target].__setitem__("banned", True) if target in uu else None)
        audit_log("admin_ban_user", target, {"by_admin": user.get("username","admin")})
        return jsonify({"ok": True})
    elif action == "unban":
        _mutate_web_users(lambda uu: uu[target].__setitem__("banned", False) if target in uu else None)
        audit_log("admin_unban_user", target, {"by_admin": user.get("username","admin")})
        return jsonify({"ok": True})
    elif action == "delete":
        if u.get("role") == "admin":
            return jsonify({"ok": False, "error": "cannot delete admin"})
        def _del_mut(uu):
            if target in uu and uu[target].get("role") != "admin":
                del uu[target]
        _mutate_web_users(_del_mut)
        audit_log("admin_delete_user", target, {"by_admin": user.get("username","admin")})
        return jsonify({"ok": True})
    elif action == "reset_password":
        new_pass = secrets.token_hex(4)
        _mutate_web_users(lambda uu: uu[target].__setitem__("password", _hash_pass(new_pass)) if target in uu else None)
        invalidate_user_sessions(target)
        audit_log("admin_reset_password", target, {"by_admin": user.get("username","admin")})
        tg_id = u.get("telegram_id")
        if tg_id:
            try: bot.send_message(tg_id, f"🔑 تم إعادة تعيين كلمة المرور\n\nالكلمة الجديدة: {new_pass}\n\nغيّرها بعد الدخول")
            except: pass
        return jsonify({"ok": True, "temp_password": new_pass})
    elif action == "send_message":
        msg = data.get("message", "").strip()
        tg_id = u.get("telegram_id")
        if tg_id and msg:
            try:
                bot.send_message(tg_id, f"💬 رسالة من الإدارة:\n\n{msg}")
            except: pass

        target_uid = u.get("uid", u.get("username", ""))
        if msg:
            push_user_notif(target_uid, "system", "💬 رسالة من الإدارة", msg, "message")
            return jsonify({"ok": True})
        return jsonify({"ok": False, "error": "empty message"})
    return jsonify({"ok": False, "error": "invalid action"})

PASSWORD_RESET_REQUESTS = {}

@app.route('/api/auth/forgot/find', methods=['POST'])
def api_auth_forgot_find():

    if not sensitive_rate_check(freq.remote_addr, "forgot"):
        return jsonify({"ok": False, "error": "كثرة المحاولات — انتظر دقيقة"}), 429
    data = freq.json or {}
    login_input = data.get("login", "").strip().lower()
    if not login_input:
        return jsonify({"ok": False, "error": "أدخل اسم المستخدم أو البريد"})
    users = _load_web_users()
    found_user = found_username = None
    if login_input in users:
        found_username = login_input
        found_user = users[login_input]
    else:
        for uname, u in users.items():
            if u.get("email", "").lower() == login_input:
                found_username = uname
                found_user = u
                break
    if not found_user:

        time.sleep(0.3)
        return jsonify({"ok": False, "error": "لم يتم العثور على الحساب"})
    email = found_user.get("email", "")
    masked = email[:2] + "***@" + email.split("@")[-1] if "@" in email else ""
    return jsonify({"ok": True, "username": found_username, "name": found_user.get("name", found_username),
        "email_masked": masked, "has_email": bool(email), "has_telegram": bool(found_user.get("telegram_id")),
        "has_security_q": bool(found_user.get("security_question")),
        "security_question": found_user.get("security_question", "")})

@app.route('/api/auth/forgot/email_otp', methods=['POST'])
def api_auth_forgot_email_otp():
    if not sensitive_rate_check(freq.remote_addr, "forgot_otp"):
        return jsonify({"ok": False, "error": "كثرة المحاولات"}), 429
    data = freq.json or {}
    username = data.get("username", "").lower()
    users = _load_web_users()
    u = users.get(username)
    if not u: return jsonify({"ok": False, "error": "not found"})
    email = u.get("email", "")
    if not email:
        return jsonify({"ok": False, "error": "لا يوجد بريد إلكتروني مسجل"})
    otp = _gen_otp6()
    OTP_STORE[f"reset_{username}"] = {"code": otp, "expires": time.time() + 300}
    print(f"🔑 Reset OTP for {username}: {otp}")

    _send_reset_email_bg(email, u.get("name", username), otp)

    tg_id = u.get("telegram_id")
    if tg_id:
        try: bot.send_message(tg_id, f"🔐 رمز استعادة كلمة المرور\n\nالرمز: {otp}\n\nصالح لمدة 5 دقائق")
        except: pass
    return jsonify({"ok": True})

@app.route('/api/auth/forgot/verify_otp', methods=['POST'])
def api_auth_forgot_verify_otp():
    data = freq.json or {}
    username = data.get("username", "").lower()
    code = data.get("code", "")
    stored = OTP_STORE.get(f"reset_{username}")
    if not stored or time.time() > stored["expires"]:
        return jsonify({"ok": False, "error": "الرمز منتهي الصلاحية"})
    if stored["code"] != code:
        return jsonify({"ok": False, "error": "الرمز غير صحيح"})
    OTP_STORE.pop(f"reset_{username}", None)
    rt = secrets.token_hex(16)
    OTP_STORE[f"resetok_{username}"] = {"token": rt, "expires": time.time() + 600}
    return jsonify({"ok": True, "reset_token": rt})

@app.route('/api/auth/forgot/verify_security', methods=['POST'])
def api_auth_forgot_verify_security():
    data = freq.json or {}
