@bot.callback_query_handler(func=lambda c: c.data.startswith(("pwr_ok|", "pwr_no|")))
def cb_password_reset(c):
    parts = c.data.split("|")
    rid = parts[1]
    bot.answer_callback_query(c.id)
    req = PASSWORD_RESET_REQUESTS.get(rid)
    if not req: return bot.edit_message_text("طلب غير موجود", ADMIN_ID, c.message.message_id)
    if req.get("status") != "pending": return bot.edit_message_text("تم التعامل مسبقاً", ADMIN_ID, c.message.message_id)
    if parts[0] == "pwr_ok":
        username = parts[2] if len(parts) > 2 else req["username"]
        new_pass = secrets.token_hex(4)
        users = _load_web_users()
        if username in users:
            users[username]["password"] = _hash_pass(new_pass)
            _save_web_users(users)
            tg_id = users[username].get("telegram_id")
            if tg_id:
                try: bot.send_message(tg_id, f"🔑 كلمة المرور الجديدة: {new_pass}")
                except: pass
        req["status"] = "done"
        bot.edit_message_text(f"✅ تم: @{username} -> {new_pass}", ADMIN_ID, c.message.message_id)
    else:
        req["status"] = "rejected"
        bot.edit_message_text(f"❌ رفض {rid}", ADMIN_ID, c.message.message_id)

@app.route('/api/recharge', methods=['POST'])
def api_recharge():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']

    if check_user_spam(uid, "recharge"):
        return jsonify({"ok": False, "error": "تم حظر حسابك تلقائياً بسبب نشاط مشبوه"})
    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور"})
    method = data.get('method', '')
    amount_usd = float(data.get('amount', 0))
    if method not in db.payment_methods:
        return jsonify({"ok": False, "error": "invalid_method"})
    if amount_usd <= 0:
        return jsonify({"ok": False, "error": "invalid_amount"})

    image_data = data.get('image', '')
    if not image_data or not image_data.startswith('data:image'):
        return jsonify({"ok": False, "error": "يجب إرفاق صورة وصل الدفع"})

    pm = db.payment_methods[method]
    amount_local = round(amount_usd * pm["rate"], 0)
    ref = f"REF-{time.strftime('%Y%m%d%H%M%S')}-{uid}"

    db.recharge_requests[ref] = {
        "uid": uid, "method": method, "usd": amount_usd,
        "local": amount_local, "status": "pending",
        "date": time.strftime("%Y-%m-%d %H:%M:%S"),
        "name": user.get("first_name", "")
    }
    db.save()

    try:
        import base64 as b64mod
        receipts_dir = "receipts"
        os.makedirs(receipts_dir, exist_ok=True)
        header, b64data = image_data.split(',', 1)
        ext = '.jpg'
        if 'png' in header:
            ext = '.png'
        raw = b64mod.b64decode(b64data)
        if len(raw) > 5 * 1024 * 1024:
            pass
        receipt_path = os.path.join(receipts_dir, f"{ref}{ext}")
        with open(receipt_path, 'wb') as rf:
            rf.write(raw)
        db.recharge_requests[ref]["receipt_file"] = f"{ref}{ext}"
        db.recharge_requests[ref]["has_image"] = True
        db.save()

        try:
            import io
            photo_io = io.BytesIO(raw)
            photo_io.name = f"{ref}{ext}"
            bot.send_photo(ADMIN_ID, photo_io,
                caption=f"📸 صورة وصل الدفع\n🧾 {ref}\n👤 {user.get('first_name','')} (ID: {uid})")
        except Exception as e:
            print(f"⚠️ فشل إرسال صورة الوصل لتليكرام: {e}")
    except Exception as e:
        print(f"⚠️ خطأ بحفظ صورة الوصل: {e}")

    push_admin_notif("recharge", {"uid": uid, "name": user.get("first_name", ""), "method": method, "usd": amount_usd, "ref": ref})

    kb = types.InlineKeyboardMarkup()
    kb.row(
        types.InlineKeyboardButton("✅ موافقة", callback_data=f"wrc_ok|{ref}"),
        types.InlineKeyboardButton("❌ رفض", callback_data=f"wrc_no|{ref}")
    )
    try:
        bot.send_message(ADMIN_ID,
            f"📥 طلب شحن جديد\n\n"
            f"👤 {user.get('first_name','')} (ID: {uid})\n"
            f"💳 {method}\n"
            f"💰 ${amount_usd:.2f} ({amount_local:,.0f} IQD)\n"
            f"🧾 {ref}",
            reply_markup=kb)
    except:
        pass

    return jsonify({"ok": True, "ref": ref, "amount_local": amount_local})

@app.route('/api/recharge_history', methods=['POST'])
def api_recharge_history():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    history = []
    for ref, info in db.recharge_requests.items():
        if info.get("uid") == uid:
            history.append({
                "ref": ref, "method": info.get("method"),
                "usd": info.get("usd"), "local": info.get("local"),
                "status": info.get("status", "pending"),
                "date": info.get("date", ""),
                "has_image": info.get("has_image", False)
            })
    history.reverse()
    return jsonify({"ok": True, "history": history})

def _binance_sync_time():

    global _BINANCE_TIME_OFFSET
    try:
        r = requests.get(f"{BINANCE_BASE}/api/v3/time", timeout=10)
        srv = int(r.json()["serverTime"])
        _BINANCE_TIME_OFFSET = srv - int(time.time() * 1000)
    except Exception as e:
        print(f"⚠️ Binance time sync: {e}")

def _bnow():
    return int(time.time() * 1000) + _BINANCE_TIME_OFFSET

def _bsign(query):
    secret = _setting("binance_api_secret", BINANCE_API_SECRET)
    return hmac.new(secret.encode(), query.encode(), hashlib.sha256).hexdigest()

def _binance_req(method, path, params=None):

    params = dict(params or {})
    params["timestamp"] = _bnow()
    params["recvWindow"] = 60000
    qs = "&".join(f"{k}={v}" for k, v in params.items())
    sig = _bsign(qs)
    url = f"{BINANCE_BASE}{path}?{qs}&signature={sig}"
    headers = {"X-MBX-APIKEY": _setting("binance_api_key", BINANCE_API_KEY)}
    for attempt in range(3):
        try:
            r = requests.request(method, url, headers=headers, timeout=20)
            r.raise_for_status()
            return r.json()
        except Exception as e:
            if attempt == 2:
                raise
            time.sleep(0.8 * (attempt + 1))

def _binance_networks(coin):

    data = _binance_req("GET", "/sapi/v1/capital/config/getall", {})
    nets = []
    for c in data:
        if c.get("coin", "").upper() == coin.upper():
            for n in c.get("networkList", []):
                if n.get("depositEnable", False):
                    nets.append({"network": n.get("network"), "name": n.get("name", n.get("network")),
                                 "fee": str(n.get("depositFee", "0")), "minConfirm": n.get("minConfirm", 0)})
            break
    return nets

def _binance_deposit_addr(coin, network):

    data = _binance_req("GET", "/sapi/v1/capital/deposit/address",
                        {"coin": coin.upper(), "network": network.upper()})
    addr = data.get("address", "")
    tag = data.get("tag") or None
    if not addr:
        raise RuntimeError("No deposit address returned")
    return addr, tag

def _binance_deposits(coin, start_ms):

    return _binance_req("GET", "/sapi/v1/capital/deposit/hisrec",
                        {"coin": coin.upper(), "startTime": start_ms})

def _binance_price(coin):

    c = coin.upper()
    if c in ("USDT",):
        return 1.0
    for sym in [f"{c}USDT", f"{c}USDC"]:
        try:
            r = requests.get(f"{BINANCE_BASE}/api/v3/ticker/price", params={"symbol": sym}, timeout=10)
            if r.status_code == 200:
                p = float(r.json()["price"])
                if p > 0:
                    return p
        except:
            pass
    return None

def _binance_internal_transfers(start_ms):

    transfers = []
    try:
        data = _binance_req("GET", "/sapi/v1/pay/transactions", {"startTime": start_ms, "limit": 100})
        for t in data.get("data", []):
            transfers.append({
                "type": "pay", "amount": float(t.get("amount", 0)),
                "currency": t.get("currency", ""), "status": t.get("orderStatus", ""),
                "txid": t.get("transactionId", ""), "time": t.get("transactionTime", 0),
                "sender": t.get("payerInfo", {}).get("name", "") if isinstance(t.get("payerInfo"), dict) else "",
                "sender_binance_id": str(t.get("payerInfo", {}).get("binanceId", "") or t.get("payerInfo", {}).get("accountId", "")).strip() if isinstance(t.get("payerInfo"), dict) else "",
            })
    except Exception as e:
        print(f"⚠️ Pay history: {e}")
    try:
        data2 = _binance_req("GET", "/sapi/v1/capital/deposit/hisrec", {"startTime": start_ms})
        for d in data2:
            if str(d.get("transferType", "")) == "1":
                transfers.append({
                    "type": "internal", "amount": float(d.get("amount", 0)),
                    "currency": d.get("coin", ""),
                    "status": "credited" if int(d.get("status", 0)) in (1, 6) else "pending",
                    "txid": d.get("txId", d.get("id", "")), "time": d.get("insertTime", 0),
                })
    except:
        pass
    return transfers

def _crypto_monitor_loop():

    _binance_sync_time()
    print("✅ Binance time synced — Crypto monitor started")
    last_sync = time.time()
    while True:
        try:
            if time.time() - last_sync > 600:
                _binance_sync_time()
                last_sync = time.time()
            deposits = db.crypto_deposits
            if not deposits:
                time.sleep(CRYPTO_CHECK_SEC)
                continue
            dirty = False
            now = time.time()
            for dep in deposits:
                if dep.get("status") not in ("pending", "detected"):
                    continue
                if now - dep.get("created", 0) > CRYPTO_INVOICE_TTL * 2:
                    if dep["status"] == "pending":
                        dep["status"] = "expired"
                        dirty = True
                    continue
                ttype = dep.get("transfer_type", "wallet")
                coin = dep["coin"]
                start_ms = int(dep.get("created", time.time()) * 1000) - 5 * 60 * 1000
                if ttype == "wallet":
                    try:
                        recs = _binance_deposits(coin, start_ms)
                    except:
                        continue
                    address = dep.get("address", "")
                    tag = dep.get("tag")
                    network = dep.get("network", "")
                    amount = float(dep.get("amount_coin", 0))
                    matched = None
                    for d in recs:
                        if str(d.get("address", "")).upper() != address.upper():
                            continue
                        if tag and str(d.get("addressTag") or d.get("tag") or "").upper() != str(tag).upper():
                            continue
                        if str(d.get("network", "")).upper() != network.upper():
                            continue
                        try:
                            damt = float(d.get("amount", 0))
                        except:
                            damt = 0
                        if damt + 1e-12 < amount:
                            continue
                        matched = d
                        break
                    if not matched:
                        continue
                    dstatus = int(matched.get("status", -1))
                    txid = matched.get("txId") or matched.get("txIdHash") or ""
                    confirms = matched.get("confirmTimes", "")

                    if txid:
                        already_credited = any(
                            dd.get("txid") == txid and dd.get("status") == "credited"
                            for dd in deposits if dd != dep
                        )
                        if already_credited:
                            dep["status"] = "duplicate"
                            dirty = True
                            try:
                                bot.send_message(ADMIN_ID, f"⚠️ إيداع مكرر تم حظره!\nUID: {dep['uid']}\nTx: {txid[:20]}...\nRef: {dep.get('ref','')}")
                            except:
                                pass
                            continue
                    if dstatus == 0 and dep["status"] == "pending":
                        dep["status"] = "detected"
                        dep["txid"] = txid
                        dep["confirms"] = confirms
                        dirty = True
                        uid = dep["uid"]
                        push_user_notif(uid, "system", "تم اكتشاف الإيداع!", f"{coin} ({network}) — بانتظار التأكيد", "wallet")
                        try:
                            bot.send_message(ADMIN_ID, f"⏳ إيداع {coin} ({network})\nUID: {uid}\nبانتظار التأكيد...")
                        except:
                            pass
                    elif dstatus in (1, 6) and dep["status"] in ("pending", "detected"):
                        uid = dep["uid"]
                        usd = float(dep.get("amount_usd", 0))

                        if coin not in ("USDT", "USDC") and usd > 0:
                            try:
                                cur_price = _binance_price(coin)
                                if cur_price and cur_price > 0:
                                    damt_actual = float(matched.get("amount", 0))
                                    real_usd = damt_actual * cur_price

                                    if real_usd < usd * 0.5:
                                        dep["status"] = "review"
                                        dep["txid"] = txid
                                        dep["review_reason"] = f"القيمة الفعلية ${real_usd:.2f} أقل من المطلوب ${usd:.2f}"
                                        dirty = True
                                        try:
                                            bot.send_message(ADMIN_ID, f"⚠️ إيداع يحتاج مراجعة!\n👤 {uid}\n💰 {damt_actual} {coin} = ${real_usd:.2f}\n📋 المطلوب: ${usd:.2f}\n🧾 {dep.get('ref','')}")
                                        except:
                                            pass
                                        continue

                                    usd = round(real_usd, 2)
                                    dep["amount_usd_actual"] = usd
                            except:
                                pass
                        dep["status"] = "credited"
                        dep["txid"] = txid
                        dep["confirms"] = confirms
                        dep["credited_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
                        dirty = True
                        if usd > 0:
                            db.add_bal(uid, usd)
                            push_user_notif(uid, "system", "تم شحن رصيدك تلقائياً!", f"+${usd:.2f} عبر {coin} ({network})", "wallet")
                            try:
                                bot.send_message(ADMIN_ID, f"🪙 شحن كريبتو تلقائي\n👤 {uid}\n💰 +${usd:.2f}\n{coin}/{network}\nTx: {txid[:20]}...")
                            except:
                                pass
                elif ttype == "binance_id":
                    try:
                        transfers = _binance_internal_transfers(start_ms)
                    except:
                        continue
                    target_usd = float(dep.get("amount_usd", 0))
                    target_coin = dep.get("coin", "USDT").upper()
                    uid = dep["uid"]

                    _linked_bid = ""
                    try:
                        _uname = dep.get("username", "")
                        if _uname:
                            _wu = _load_web_users()
                            _linked_bid = _wu.get(_uname, {}).get("binance_pay_id", "").strip()
                    except:
                        _linked_bid = ""

                    matched = None
                    for t in transfers:
                        cur = t.get("currency", "").upper()
                        amt = float(t.get("amount", 0))
                        if cur != target_coin:
                            continue
                        txid = str(t.get("txid", ""))
                        already = any(
                            dd.get("txid") == txid and dd.get("status") in ("credited", "duplicate")
                            for dd in deposits if dd != dep and txid
                        )
                        if already:
                            continue

                        if _linked_bid:
                            sender_id = str(t.get("sender_binance_id", "")).strip()
                            if sender_id and sender_id == _linked_bid:
                                if target_usd > 0 and abs(amt - target_usd) / target_usd > 0.05:
                                    dep["status"] = "review"
                                    dep["txid"] = txid
                                    dep["review_reason"] = f"المبلغ المستلم ${amt:.2f} يختلف عن المطلوب ${target_usd:.2f}"
                                    dirty = True
                                    try:
                                        bot.send_message(ADMIN_ID, f"⚠️ Binance Pay — فرق بالمبلغ\n👤 {uid}\n💰 وصل ${amt:.2f} / مطلوب ${target_usd:.2f}\n🆔 Sender: {_linked_bid}")
                                    except:
                                        pass
                                    break
                                matched = t
                                break
                        else:
                            if abs(amt - target_usd) <= 0.02:
                                matched = t
                                break

                    if matched:
                        dep["status"] = "credited"
                        dep["txid"] = str(matched.get("txid", ""))
                        dep["credited_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
                        dep["matched_by"] = "binance_id" if _linked_bid else "amount"
                        dirty = True
                        usd = float(matched.get("amount", target_usd)) if _linked_bid else target_usd
                        usd = round(usd, 2)
                        if usd > 0:
                            db.add_bal(uid, usd)
                            push_user_notif(uid, "system", "تم شحن رصيدك!", f"+${usd:.2f} عبر Binance Pay", "wallet")
                            try:
                                _match_info = f"Sender ID: {_linked_bid}" if _linked_bid else "مطابقة بالمبلغ"
                                bot.send_message(ADMIN_ID, f"🪙 شحن Binance Pay\n👤 {uid}\n💰 +${usd:.2f}\n🔍 {_match_info}")
                            except:
                                pass
            if dirty:
                db.save()
        except Exception as e:
            print(f"⚠️ Crypto monitor error: {e}")
        time.sleep(CRYPTO_CHECK_SEC)

