@app.route('/api/admin/crypto_icons/set', methods=['POST'])
def api_admin_crypto_icons_set():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user or (user['id'] != ADMIN_ID and not user.get('is_admin')):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    coin = str(data.get("coin", "")).strip().upper()
    icon = str(data.get("icon", "")).strip()
    if coin not in CRYPTO_COINS:
        return jsonify({"ok": False, "error": "invalid_coin"})
    if not icon or not icon.startswith("data:"):
        return jsonify({"ok": False, "error": "invalid_icon"})

    if len(icon) > 280000:
        return jsonify({"ok": False, "error": "icon_too_large"})
    if not hasattr(db, 'crypto_coin_icons') or db.crypto_coin_icons is None:
        db.crypto_coin_icons = {}
    db.crypto_coin_icons[coin] = icon
    db.save()
    return jsonify({"ok": True})

