@app.route('/api/user/binance_pay_id/set', methods=['POST'])
def api_user_binance_pay_id_set():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uname = user.get("username", "")
    if not uname:
        return jsonify({"ok": False, "error": "no_username"})
    new_id = str(data.get("binance_pay_id", "")).strip()
    if not new_id:
        return jsonify({"ok": False, "error": "invalid_id"})
    if not new_id.isdigit():
        return jsonify({"ok": False, "error": "الـ Binance Pay ID يجب أن يكون أرقام فقط"})
    users = _load_web_users()
    for un, ud in users.items():
        if un != uname and ud.get("binance_pay_id") == new_id:
            return jsonify({"ok": False, "error": "هذا الـ Binance Pay ID مربوط بحساب آخر"})
    users[uname]["binance_pay_id"] = new_id
    _save_web_users(users)
    audit_log("binance_pay_id_linked", user['id'], {"binance_pay_id": new_id})
    return jsonify({"ok": True})

ASIACELL_RATE = 1700
ASIACELL_WEBHOOK_SECRET = "0510e9242a8b6fc4f10f80cd6ebc42f51708fad3"
ASIACELL_EXPIRE_SEC = 600
ASIACELL_DEDUP_SEC = 120

_asia_credit_lock = threading.Lock()

def _asia_cleanup_expired():

    now = time.time()
    expired_refs = [
        ref for ref, req in db.asiacell_requests.items()
        if req.get('status') in ('waiting', 'confirmed')
        and now > req.get('expires', 0) + 86400
    ]
    if expired_refs:
        for ref in expired_refs:
            db.asiacell_requests[ref]['status'] = 'expired'
        db.save()
        print(f"🧹 تنظيف {len(expired_refs)} طلب آسياسيل منتهي")

def _asia_safe_credit(ref, source="auto"):

    with _asia_credit_lock:
        req = db.asiacell_requests.get(ref)
        if not req:
            return (False, "not_found")

        if req.get('status') == 'credited':
            return (False, "already_credited")

        if req.get('status') == 'rejected':
            return (False, "rejected")

        now = time.time()
        uid = req['uid']
        dedup_key = f"{uid}_{req['amount_iqd']}"
        for _r, _rq in db.asiacell_requests.items():
            if _r == ref:
                continue
            if (_rq.get('status') == 'credited'
                and _rq.get('_credited_ts', 0)
                and now - _rq['_credited_ts'] < ASIACELL_DEDUP_SEC
                and f"{_rq['uid']}_{_rq['amount_iqd']}" == dedup_key):
                print(f"⚠️ [DEDUP] الطلب {ref} مكرر — نفس اليوزر+المبلغ شُحن قبل {now - _rq['_credited_ts']:.0f}ث")
                return (False, "duplicate")

        usd = req['amount_usd']
        req['status'] = 'credited'
        req['credited_at'] = time.strftime("%Y-%m-%d %H:%M:%S")
        req['_credited_ts'] = now
        req['credit_source'] = source
        if source == "manual":
            req['manual'] = True

        db.add_bal(uid, usd)
        db.save()

        print(f"✅ Asiacell {source} credit: ref={ref}, uid={uid}, +${usd:.2f}")
        return (True, usd)

@app.route('/api/asiacell/request', methods=['POST'])
def api_asiacell_request():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    web_uid = user.get('uid', uid)
    phone = data.get('phone', '').strip().replace(' ', '')

    try:
        amount_iqd = int(data.get('amount_iqd', 0))
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "المبلغ غير صحيح"})

    print(f"📱 Asia request: uid={uid}, phone={phone[:4]}****, amount={amount_iqd}")

    if not phone or len(phone) < 10 or len(phone) > 11:
        return jsonify({"ok": False, "error": "رقم الهاتف غير صحيح"})
    if not phone.startswith('07'):
        return jsonify({"ok": False, "error": "الرقم يجب أن يبدأ بـ 07"})
    if not phone.isdigit():
        return jsonify({"ok": False, "error": "الرقم يجب أن يحتوي أرقام فقط"})

    if amount_iqd < 1000 or amount_iqd > 60000:
        return jsonify({"ok": False, "error": "المبلغ يجب أن يكون بين 1,000 و 60,000 دينار"})

    asia_pm = db.payment_methods.get("آسيا سيل", {})
    admin_number = asia_pm.get("number", "07728047319")

    amount_usd = round(amount_iqd / ASIACELL_RATE, 2)

    ref = f"ASIA-{secrets.token_hex(10)}"

    _asia_cleanup_expired()

    db.asiacell_requests[ref] = {
        "uid": uid,
        "web_uid": web_uid,
        "phone": phone,
        "amount_iqd": amount_iqd,
        "amount_usd": amount_usd,
        "admin_number": admin_number,
        "status": "waiting",
        "date": time.strftime("%Y-%m-%d %H:%M:%S"),
        "name": user.get("first_name", ""),
        "expires": time.time() + ASIACELL_EXPIRE_SEC,
    }
    db.save()

    ussd_code = f"*123*{amount_iqd}*{admin_number}#"

    threading.Thread(target=wa_security_alert, args=(phone, amount_iqd), daemon=True).start()

    return jsonify({
        "ok": True,
        "ref": ref,
        "ussd_code": ussd_code,
        "admin_number": admin_number,
        "amount_iqd": amount_iqd,
        "amount_usd": amount_usd,
        "expires_in": ASIACELL_EXPIRE_SEC
    })

