WEBHOOK_ALLOWED_IPS = set()

@app.route('/api/asiacell/webhook', methods=['POST', 'GET'])
@app.route('/webhook', methods=['POST', 'GET'])
def api_asiacell_webhook():

    import re as _re

    incoming_secret = (
        freq.args.get('secret', '') or
        freq.args.get('key', '') or
        freq.headers.get('X-Webhook-Secret', '') or
        freq.headers.get('Authorization', '').replace('Bearer ', '')
    )
    if not incoming_secret:
        try:
            if freq.is_json:
                incoming_secret = (freq.json or {}).get('secret', '')
        except Exception:
            pass

    if incoming_secret != ASIACELL_WEBHOOK_SECRET:
        print(f"🚫 Webhook REJECTED — invalid secret from IP: {freq.remote_addr}")
        return jsonify({"ok": False, "error": "unauthorized"}), 403

    if WEBHOOK_ALLOWED_IPS and freq.remote_addr not in WEBHOOK_ALLOWED_IPS:
        print(f"🚫 Webhook REJECTED — IP not allowed: {freq.remote_addr}")
        return jsonify({"ok": False, "error": "ip_not_allowed"}), 403

    print(f"📩 Webhook: method={freq.method}, IP={freq.remote_addr}")

    sms_from = ''
    sms_body = ''

    try:

        if freq.args:
            sms_from = freq.args.get('from', freq.args.get('sender', freq.args.get('number', freq.args.get('phone', ''))))
            sms_body = freq.args.get('body', freq.args.get('message', freq.args.get('text', freq.args.get('msg', ''))))

        if not sms_body and freq.form:
            sms_from = freq.form.get('from', freq.form.get('sender', freq.form.get('number', freq.form.get('phone', freq.form.get('From', '')))))
            sms_body = freq.form.get('body', freq.form.get('message', freq.form.get('text', freq.form.get('msg', freq.form.get('Body', freq.form.get('Message', ''))))))

        if not sms_body and freq.is_json:
            data = freq.json or {}
            sms_from = data.get('from', data.get('sender', data.get('number', data.get('phone', data.get('From', '')))))
            sms_body = data.get('body', data.get('message', data.get('text', data.get('msg', data.get('Body', data.get('Message', ''))))))

        if not sms_body:
            try:
                raw = freq.data.decode('utf-8', errors='ignore').strip()
                if raw and '{{' not in raw:
                    from_match = _re.search(r'[Ff]rom\s*[:：]\s*([\d+]+)', raw)
                    if from_match:
                        sms_from = from_match.group(1)
                        lines = raw.split('\n', 1)
                        sms_body = lines[1].strip() if len(lines) > 1 else ''
                    else:
                        sms_body = raw
            except Exception:
                pass

    except Exception as e:
        print(f"⚠️ Webhook parse error: {e}")

    sms_from = str(sms_from).replace(' ', '').replace('+964', '0')

    if '{{' in sms_from or '{{' in sms_body:
        return jsonify({"ok": True, "matched": False, "error": "Template variables not resolved."})

    print(f"📩 SMS: from=[{sms_from[:6]}...], body_len={len(sms_body)}")

    if not sms_body:
        return jsonify({"ok": True, "matched": False, "reason": "empty body"})

    sms_phone = ''
    sms_amount = 0
    sms_type = ''

    recv_match = _re.search(r'(?:إستلمت|استلمت|تم\s+استلام|وصلك)\s+([\d,]+)\s*(?:د|دينار|IQD)\s+(?:من\s+)?(?:الرقم\s+)?(\d{10,11})', sms_body)
    if recv_match:
        sms_amount = int(recv_match.group(1).replace(',', ''))
        sms_phone = recv_match.group(2)
        sms_type = 'received'
        print(f"📩 Pattern1 RECEIVE: amount={sms_amount}, sender={sms_phone[:4]}****")
    else:

        sent_match = _re.search(r'([\d,]+)\s*(?:د|دينار|IQD)\s+(?:ارسلت|أرسلت|تم\s+ارسال(?:ها)?)\s+(?:من\s+)?(?:رصيدك\s+)?(?:الى|إلى|ال)\s+(\d{10,11})', sms_body)
        if sent_match:
            sms_amount = int(sent_match.group(1).replace(',', ''))
            sms_phone = sent_match.group(2)
            sms_type = 'sent'
            print(f"📩 Pattern2 SENT: amount={sms_amount}, dest={sms_phone[:4]}****")
        else:

            phone_match = _re.search(r'(0?7\d{9})', sms_body)
            amount_match = _re.search(r'([\d,]+)\s*(?:د\b|د\.|IQD|دينار)', sms_body)
            if phone_match:
                sms_phone = phone_match.group(1)
            if amount_match:
                try:
                    sms_amount = int(str(amount_match.group(1)).replace(',', ''))
                except (ValueError, TypeError):
                    pass
            sms_type = 'unknown'
            if sms_amount > 0:
                print(f"⚠️ Pattern3 (generic): amount={sms_amount} — إشعار أدمن فقط")
                try:
                    bot.send_message(ADMIN_ID,
                        f"⚠️ SMS غير معروف النمط — يحتاج تأكيد يدوي\n\n"
                        f"المبلغ: {sms_amount:,} IQD\n"
                        f"الرقم: {sms_phone or 'غير معروف'}\n"
                        f"المحتوى: {sms_body[:150]}")
                except Exception:
                    pass
                return jsonify({"ok": True, "matched": False, "reason": "unknown_pattern_sent_to_admin"})

    if sms_phone and not sms_phone.startswith('0'):
        sms_phone = '0' + sms_phone

    print(f"📩 Final: type={sms_type}, amount={sms_amount}")

    if sms_amount > 0 and sms_type in ('received', 'sent'):
        now = time.time()

        for ref, req in db.asiacell_requests.items():
            if req['status'] not in ('waiting', 'confirmed'):
                continue

            if now > req.get('expires', 0):
                continue
            if req['amount_iqd'] != sms_amount:
                continue

            req_user_phone = req.get('phone', '')
            if req_user_phone and not req_user_phone.startswith('0'):
                req_user_phone = '0' + req_user_phone
            req_admin_num = req.get('admin_number', '')
            if req_admin_num and not req_admin_num.startswith('0'):
                req_admin_num = '0' + req_admin_num

            sms_p = sms_phone.lstrip('0')
            matched = False

            if sms_type == 'received':

                if sms_p and sms_p == req_user_phone.lstrip('0'):
                    matched = True
            elif sms_type == 'sent':

                if sms_p and sms_p == req_admin_num.lstrip('0'):
                    matched = True

            if not sms_p:
                matched = False

            if matched:
                uid = req['uid']

                success, result = _asia_safe_credit(ref, source="auto")

                if not success:

                    if result in ("already_credited", "duplicate", "rejected"):
                        print(f"⏭️ Skipping {ref}: {result} — checking next requests...")
                        continue
                    else:
                        return jsonify({"ok": True, "matched": False, "reason": result})

                usd = result

                push_user_notif(uid, "system", "تم شحن رصيدك تلقائياً! 📱",
                    f"+${usd:.2f} عبر آسياسيل ({req['amount_iqd']:,} IQD)", "wallet")

                _wa_phone = req.get('phone', '')
                if _wa_phone:
                    threading.Thread(target=wa_deposit_approved, args=(_wa_phone, usd, db.get_bal(uid)), daemon=True).start()

                try:
                    bot.send_message(ADMIN_ID,
                        f"✅ شحن آسياسيل تلقائي\n\n"
                        f"👤 {req.get('name','')} (ID: {uid})\n"
                        f"📞 {req.get('phone','')}\n"
                        f"💰 {sms_amount:,} IQD → ${usd:.2f}\n"
                        f"🧾 {ref}")
                except Exception:
                    pass

                return jsonify({"ok": True, "matched": True, "ref": ref})

        print(f"⚠️ No match: type={sms_type}, amount={sms_amount}")
    elif sms_amount <= 0:
        print(f"⚠️ Could not parse amount from SMS")

    try:
        bot.send_message(ADMIN_ID,
            f"📩 SMS وارد (بدون مطابقة)\n"
            f"من: {sms_from}\n"
            f"المحتوى: {sms_body[:200]}")
    except Exception:
        pass

    return jsonify({"ok": True, "matched": False})

@app.route('/webhook/test', methods=['GET'])
def webhook_test():

    return """<html><body style="font-family:monospace;padding:20px;background:#111;color:#0f0">
    <h2>✅ Webhook is alive!</h2>
    <p>POST to /webhook with SMS data + secret param</p>
    <p>Example: /webhook?secret=YOUR_SECRET</p>
    <p>Supported formats: JSON, form-data, query params, plain text</p>
    </body></html>"""

_asia2_sessions = {}
_ASIA2_SESSION_TTL = 600
_ASIA2_ODP_BASE = "https://odpapp.asiacell.com/api/v1"

def _asia2_get_headers():
    return {
        'User-Agent': "okhttp/5.0.0-alpha.2",
        'X-ODP-API-KEY': secrets.token_hex(16),
        'DeviceID': str(uuid.uuid4()),
        'X-OS-Version': "11",
        'X-Device-Type': "[Android][realme][RMX3834 11][TIRAMISU][HMS][4.3.7:90000325]",
        'X-ODP-APP-VERSION': "4.3.7",
        'X-FROM-APP': "odp",
        'X-ODP-CHANNEL': "mobile",
        'Content-Type': "application/json; charset=UTF-8"
    }

def _asia2_cleanup():
    now = time.time()
    expired = [k for k, v in _asia2_sessions.items() if now - v.get('created', 0) > _ASIA2_SESSION_TTL]
    for k in expired:
        del _asia2_sessions[k]

def _asia2_phone_to_intl(phone):
    phone = phone.strip().replace(' ', '')
    if phone.startswith('07'):
        return '964' + phone[1:]
    if phone.startswith('+964'):
        return phone[1:]
    if phone.startswith('964'):
        return phone
    return phone

@app.route('/api/asiacell2/login', methods=['POST'])
def api_asiacell2_login():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    web_uid = user.get('uid', uid)
    phone = data.get('phone', '').strip().replace(' ', '')
    try:
        amount_iqd = int(data.get('amount_iqd', 0))
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "المبلغ غير صحيح"})

    if not phone or len(phone) < 10 or len(phone) > 11:
        return jsonify({"ok": False, "error": "رقم الهاتف غير صحيح"})
    if not phone.startswith('07'):
        return jsonify({"ok": False, "error": "الرقم يجب أن يبدأ بـ 07"})
    if not phone.isdigit():
        return jsonify({"ok": False, "error": "الرقم يجب أن يحتوي أرقام فقط"})
    if amount_iqd < 1000 or amount_iqd > 60000:
        return jsonify({"ok": False, "error": "المبلغ يجب أن يكون بين 1,000 و 60,000 دينار"})

    amount_usd = round(amount_iqd / ASIACELL_RATE, 2)
    _asia2_cleanup()

    user_sessions = sum(1 for v in _asia2_sessions.values() if v.get('uid') == uid)
    if user_sessions >= 3:
        return jsonify({"ok": False, "error": "عندك طلبات كثيرة، انتظر شوية"})

    headers = _asia2_get_headers()
    intl_phone = _asia2_phone_to_intl(phone)
    print(f"📱 Asia2 login: uid={uid}, phone={phone[:4]}****, amount={amount_iqd}")

    try:
        res = requests.post(
            f"{_ASIA2_ODP_BASE}/login?lang=en",
            json={"captchaCode": "", "username": intl_phone},
            headers=headers, timeout=15
        )
        rdata = res.json()
    except Exception as e:
        print(f"⚠️ Asia2 login error: {e}")
        return jsonify({"ok": False, "error": "خطأ بالاتصال بآسياسيل، حاول لاحقاً"})

    if not rdata.get("success"):
        msg = rdata.get("message", "خطأ في رقم الهاتف")
        return jsonify({"ok": False, "error": f"آسياسيل: {msg}"})

    next_url = rdata.get("nextUrl", "")
    pid_match = re.search(r'PID=([a-f0-9\-]+)', next_url)
    if not pid_match:
        return jsonify({"ok": False, "error": "خطأ بالاتصال، حاول مجدداً"})

    pid = pid_match.group(1)
    session_id = f"A2-{secrets.token_hex(12)}"
    _asia2_sessions[session_id] = {
        "uid": uid, "web_uid": web_uid, "phone": phone, "intl_phone": intl_phone,
        "pid": pid, "headers": headers, "amount_iqd": amount_iqd, "amount_usd": amount_usd,
        "step": "otp_sent", "created": time.time(), "name": user.get("first_name", ""),
    }
    return jsonify({"ok": True, "session": session_id, "phone": phone, "amount_iqd": amount_iqd, "amount_usd": amount_usd})

@app.route('/api/asiacell2/verify', methods=['POST'])
def api_asiacell2_verify():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    session_id = data.get('session', '')
    otp = str(data.get('otp', '')).strip()
    sess = _asia2_sessions.get(session_id)
    if not sess:
        return jsonify({"ok": False, "error": "الجلسة منتهية، أعد المحاولة"})
    if str(sess['uid']) != str(user['id']) and str(sess.get('web_uid','')) != str(user.get('uid','')):
        return jsonify({"ok": False, "error": "unauthorized"})
    if sess['step'] != 'otp_sent':
        return jsonify({"ok": False, "error": "خطوة غير صحيحة"})
    if not otp or len(otp) < 4:
        return jsonify({"ok": False, "error": "الرمز غير صحيح"})

    headers = sess['headers']
    try:
        res = requests.post(
            f"{_ASIA2_ODP_BASE}/smsvalidation?lang=en",
            json={"PID": sess['pid'], "passcode": otp, "token": ""},
            headers=headers, timeout=15
        )
        rdata = res.json()
    except Exception as e:
        return jsonify({"ok": False, "error": "خطأ بالاتصال، حاول مجدداً"})

    if not rdata.get("success"):
        msg = rdata.get("message", "رمز التحقق خاطئ")
        return jsonify({"ok": False, "error": f"آسياسيل: {msg}"})

    access_token = rdata.get("access_token", "")
    if not access_token:
        return jsonify({"ok": False, "error": "فشل الحصول على التوكن"})

    headers["Authorization"] = f"Bearer {access_token}"
    sess['headers'] = headers
    sess['token'] = access_token

    asia_pm = db.payment_methods.get("آسيا سيل", {})
    admin_number = asia_pm.get("number", "07728047319")
    receiver_intl = _asia2_phone_to_intl(admin_number)

    try:
        res2 = requests.post(
            f"{_ASIA2_ODP_BASE}/credit-transfer/start?lang=ar",
            json={"amount": sess['amount_iqd'], "receiverMsisdn": receiver_intl},
            headers=headers, timeout=15
        )
        rdata2 = res2.json()
    except Exception as e:
        return jsonify({"ok": False, "error": "فشل بدء التحويل، حاول لاحقاً"})

    if not (rdata2.get("success") or rdata2.get("PID")):
        msg = rdata2.get("message", "فشل بدء التحويل — تأكد من رصيد كافٍ")
        return jsonify({"ok": False, "error": msg})

    sess['transfer_pid'] = rdata2.get("PID", "")
    sess['step'] = 'transfer_otp_sent'
    return jsonify({"ok": True, "step": "transfer_otp", "amount_iqd": sess['amount_iqd'], "amount_usd": sess['amount_usd']})

@app.route('/api/asiacell2/confirm', methods=['POST'])
def api_asiacell2_confirm():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    session_id = data.get('session', '')
    otp = str(data.get('otp', '')).strip()
    sess = _asia2_sessions.get(session_id)
    if not sess:
        return jsonify({"ok": False, "error": "الجلسة منتهية، أعد المحاولة"})
    if str(sess['uid']) != str(user['id']) and str(sess.get('web_uid','')) != str(user.get('uid','')):
        return jsonify({"ok": False, "error": "unauthorized"})
    if sess['step'] != 'transfer_otp_sent':
        return jsonify({"ok": False, "error": "خطوة غير صحيحة"})
    if not otp or len(otp) < 4:
        return jsonify({"ok": False, "error": "الرمز غير صحيح"})

    try:
        res = requests.post(
            f"{_ASIA2_ODP_BASE}/credit-transfer/do-transfer?lang=ar",
            json={"PID": sess['transfer_pid'], "passcode": otp},
            headers=sess['headers'], timeout=15
        )
        rdata = res.json()
    except Exception as e:
        return jsonify({"ok": False, "error": "خطأ بالاتصال، حاول مجدداً"})

    if not rdata.get("success"):
        msg = rdata.get("message", "فشل تأكيد التحويل")
        return jsonify({"ok": False, "error": msg})

    uid = sess['uid']
    amount_usd = sess['amount_usd']
    amount_iqd = sess['amount_iqd']
    phone = sess['phone']

    db.add_bal(uid, amount_usd)
    ref = f"A2-{secrets.token_hex(10)}"
    db.asiacell_requests[ref] = {
        "uid": uid, "web_uid": sess.get('web_uid', uid), "phone": phone,
        "amount_iqd": amount_iqd, "amount_usd": amount_usd,
        "admin_number": db.payment_methods.get("آسيا سيل", {}).get("number", "07728047319"),
        "status": "credited", "date": time.strftime("%Y-%m-%d %H:%M:%S"),
        "credited_at": time.strftime("%Y-%m-%d %H:%M:%S"), "_credited_ts": time.time(),
        "credit_source": "api_auto", "name": sess.get('name', ''), "method": "asiacell_api",
    }
    db.save()

    try: del _asia2_sessions[session_id]
    except KeyError: pass

    new_bal = db.get_bal(uid)
    push_user_notif(uid, "system", "تم شحن رصيدك تلقائياً!", f"+${amount_usd:.2f} عبر آسياسيل ({amount_iqd:,} IQD)", "wallet")
    try: email_balance_recharged(uid, amount_usd, "آسياسيل API", new_bal)
    except Exception: pass
    if phone:
        try: threading.Thread(target=wa_deposit_approved, args=(phone, amount_usd, new_bal), daemon=True).start()
        except Exception: pass
    try:
        bot.send_message(ADMIN_ID,
            f"✅ شحن آسياسيل API\n\n"
            f"👤 {sess.get('name','')} (ID: {uid})\n"
            f"📞 {phone}\n"
            f"💰 {amount_iqd:,} IQD → ${amount_usd:.2f}\n"
            f"💵 الرصيد: ${new_bal:.2f}\n"
            f"🧾 {ref}")
    except Exception: pass

    return jsonify({"ok": True, "ref": ref, "amount_iqd": amount_iqd, "amount_usd": amount_usd, "new_balance": new_bal})

@app.route('/api/auth/register', methods=['POST'])
def api_auth_register():

    if not sensitive_rate_check(freq.remote_addr, "register"):
        return jsonify({"ok": False, "error": "كثرة المحاولات — انتظر دقيقة"}), 429
    data = freq.json or {}
    username = data.get('username', '').strip().lower()
    email = data.get('email', '').strip().lower()
    password = data.get('password', '')

    if not username or not email or not password:
        return jsonify({"ok": False, "error": "يرجى ملء جميع الحقول"})
    if len(username) < 3:
        return jsonify({"ok": False, "error": "اسم المستخدم يجب أن يكون 3 أحرف على الأقل"})
    if len(password) < 6:
        return jsonify({"ok": False, "error": "كلمة المرور يجب أن تكون 6 أحرف على الأقل"})
    if not re.match(r'^[a-zA-Z0-9_]+$', username):
        return jsonify({"ok": False, "error": "اسم المستخدم يحتوي حروف إنجليزية وأرقام فقط"})

    if email == ADMIN_EMAIL.lower():
        return jsonify({"ok": False, "error": "البريد الإلكتروني مستخدم مسبقاً"})

    verify_rec = EMAIL_VERIFY_CODES.get(email)
    if not verify_rec or not verify_rec.get("verified"):
        return jsonify({"ok": False, "error": "يرجى تأكيد الإيميل أولاً بكود التحقق"})

    is_admin = (email == ADMIN_EMAIL)
    _reg_box = {}

    def _register_mut(users):
        # كل الفحوصات + الإنشاء داخل نفس المعاملة الذرّية حتى لا يمر
        # تسجيلان متزامنان بنفس الاسم/الإيميل أو يأخذان نفس الـ LO-ID
        if username in users:
            return "اسم المستخدم موجود مسبقاً"
        for uname, u in users.items():
            if uname == "admin":
                continue
            if u.get("email") == email:
                return "البريد الإلكتروني مستخدم مسبقاً"
        new_uid = str(uuid.uuid4())[:8]
        _reg_box["uid"] = new_uid
        users[username] = {
            "uid": new_uid,
            "beinty_id": _next_beinty_id(users),
            "email": email,
            "password": _hash_pass(password),
            "telegram_id": ADMIN_ID if is_admin else None,
            "role": "admin" if is_admin else "user",
            "created": time.strftime("%Y-%m-%d %H:%M:%S"),
            "name": username,
            "balance": 0.0,
            "currency": "",
        }
        return None

    _reg_err = _mutate_web_users(_register_mut)
    if _reg_err:
        return jsonify({"ok": False, "error": _reg_err})
    uid = _reg_box.get("uid", "")

    EMAIL_VERIFY_CODES.pop(email, None)

    try:
        bot.send_message(ADMIN_ID, f"👤 تسجيل جديد!\n\n{username}\n{email}\n{time.strftime('%H:%M')}")
    except: pass

    push_admin_notif("user", {"username": username, "email": email})

    ref_code = str(data.get("ref_code", "")).strip().upper()
    if ref_code:
        try:
            new_uid = uid
            my_ref = _get_referral(new_uid)
            if not my_ref.get("referred_by") and my_ref.get("code", "") != ref_code:
                for ruid, rdata in db.referrals.items():
                    if rdata.get("code") == ref_code:
                        my_ref["referred_by"] = str(ruid)
                        rdata["count"] = rdata.get("count", 0) + 1
                        db.save()
                        try:
                            push_user_notif(ruid, "system", "إحالة جديدة!", "مستخدم جديد سجّل بكود إحالتك", "users")
                        except: pass
                        break
        except: pass

    if email:
        _send_welcome_email_bg(email, username)

    return jsonify({"ok": True, "message": "تم إنشاء الحساب بنجاح"})

def _verify_google_token(credential):
    """
    تحقق آمن من JWT توكن Google عبر استدعاء tokeninfo endpoint.
    Google يتحقق من التوقيع الرقمي ويرجع payload مفكوك.
    يرجع dict عند النجاح أو None عند الفشل.
    """
    try:
        import urllib.request, urllib.parse, urllib.error
        url = "https://oauth2.googleapis.com/tokeninfo?id_token=" + urllib.parse.quote(credential, safe='')
        req = urllib.request.Request(url, headers={'User-Agent': 'Beinty/1.0'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return None
            info = json.loads(resp.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        print(f"⚠️ Google tokeninfo HTTP {e.code}: invalid token")
        return None
    except Exception as e:
        print(f"⚠️ Google tokeninfo error: {e}")
        return None

    if info.get('aud') != _google_client_id():
        print(f"⚠️ Google token aud mismatch: got {info.get('aud')!r}")
        return None
    try:
        exp = int(info.get('exp', 0))
    except (ValueError, TypeError):
        exp = 0
    if exp < time.time():
        return None
    iss = info.get('iss', '')
    if iss not in ('https://accounts.google.com', 'accounts.google.com'):
        return None
    if info.get('email_verified') in (False, 'false', '0'):
        return None
    return info


@app.route('/api/auth/google', methods=['POST'])
def api_auth_google():

    data = freq.json or {}
    credential = data.get('credential', '')
    if not credential:
        return jsonify({"ok": False, "error": "بيانات كوكل غير صالحة"})

    info = _verify_google_token(credential)
    if not info:
        return jsonify({"ok": False, "error": "توكن غير صالح أو منتهي الصلاحية"})

    google_id = info.get('sub', '')
    email = info.get('email', '').lower()
    name = info.get('name', '')
    picture = info.get('picture', '')

    if not google_id or not email:
        return jsonify({"ok": False, "error": "بيانات كوكل ناقصة"})

    _goog_box = {}
    def _google_mut(users):
        # البحث عن حساب موجود (بـ google_id أو الإيميل) أو إنشاء جديد —
        # كله داخل معاملة ذرّية حتى لا يُنشَأ حسابان لنفس الشخص عند تسجيلين متزامنين
        for uname, u in users.items():
            if u.get("google_id") == google_id:
                _goog_box.update(username=uname, is_new=False)
                return
            if u.get("email", "").lower() == email:
                u["google_id"] = google_id
                if picture and not u.get("avatar"):
                    u["avatar"] = picture
                _goog_box.update(username=uname, is_new=False)
                return

        base_username = email.split('@')[0].lower()
        base_username = re.sub(r'[^a-z0-9_]', '', base_username)
        if len(base_username) < 3:
            base_username = "user_" + base_username
        gen_username = base_username
        counter = 1
        while gen_username in users:
            gen_username = f"{base_username}{counter}"
            counter += 1

        new_uid = str(uuid.uuid4())[:8]
        users[gen_username] = {
            "uid": new_uid,
            "beinty_id": _next_beinty_id(users),
            "email": email,
            "password": _hash_pass(secrets.token_hex(16)),
            "google_id": google_id,
            "telegram_id": None,
            "role": "user",
            "created": time.strftime("%Y-%m-%d %H:%M:%S"),
            "name": name or gen_username,
            "balance": 0.0,
            "avatar": picture,
            "currency": "",
        }
        _goog_box.update(username=gen_username, is_new=True, uid=new_uid)

    _mutate_web_users(_google_mut)
    username = _goog_box.get("username")
    _is_new = _goog_box.get("is_new", False)
    uid = _goog_box.get("uid", "")
    users = _load_web_users()
    user = users.get(username)
    if not user:
        return jsonify({"ok": False, "error": "تعذّر إنشاء الحساب — أعد المحاولة"})

    if _is_new:
        try:
            bot.send_message(ADMIN_ID, f"👤 تسجيل جديد (Google)!\n\n{username}\n{email}\n{time.strftime('%H:%M')}")
        except: pass
        push_admin_notif("user", {"username": username, "email": email})

        _send_welcome_email_bg(email, name or username)

        ref_code = str(data.get("ref_code", "")).strip().upper()
        if ref_code:
            try:
                new_uid = uid
                my_ref = _get_referral(new_uid)
                if not my_ref.get("referred_by") and my_ref.get("code", "") != ref_code:
                    for ruid, rdata in db.referrals.items():
                        if rdata.get("code") == ref_code:
                            my_ref["referred_by"] = str(ruid)
                            rdata["count"] = rdata.get("count", 0) + 1
                            db.save()
                            break
            except: pass

    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور. تواصل مع الإدارة"})

    token = _gen_token()
    is_admin = user.get("role") == "admin"
    db.web_sessions[token] = {
        "uid": user["uid"],
        "username": username,
        "telegram_id": user.get("telegram_id"),
        "role": "admin" if is_admin else "user",
        "name": user.get("name", username),
        "email": user.get("email", ""),
        "expires": time.time() + 86400 * 365
    }
    db.save()

    tg_id = user.get("telegram_id")
    effective_uid = tg_id if tg_id else user["uid"]
    balance = db.get_bal(effective_uid)

    return jsonify({
        "ok": True,
        "token": token,
        "user": {
            "uid": user["uid"],
            "username": username,
            "name": user.get("name", username),
            "email": user.get("email", ""),
            "role": "admin" if is_admin else "user",
            "balance": balance,
            "is_admin": is_admin,
            "api_key": user.get("api_key", ""),
        }
    })

@app.route('/api/auth/login', methods=['POST'])
def api_auth_login():

    ip = freq.remote_addr
    if not login_attempt_check(ip):
        return jsonify({"ok": False, "error": "محاولات كثيرة. انتظر 5 دقائق"}), 429
    if not sensitive_rate_check(ip, "login"):
        return jsonify({"ok": False, "error": "كثرة المحاولات — انتظر دقيقة"}), 429

    data = freq.json or {}
    login_input = data.get('username', '').strip().lower()
    password = data.get('password', '')

    if not login_input or not password:
        return jsonify({"ok": False, "error": "يرجى ملء جميع الحقول"})

    users = _load_web_users()
    username = None
    user = None
    if login_input in users:
        username = login_input
        user = users[login_input]
    else:
        for uname, u in users.items():
            if u.get("email", "").lower() == login_input:
                username = uname
                user = u
                break
    if not user or not _verify_pass(password, user.get("password", "")):
        login_attempt_record(ip, False)
        audit_log("login_failed", login_input, {"ip": ip})
        return jsonify({"ok": False, "error": "اسم المستخدم أو كلمة المرور غير صحيحة"})

    if _needs_rehash(user.get("password", "")):
        user["password"] = _hash_pass(password)
        _save_web_users(users)

    if user.get("banned"):
        return jsonify({"ok": False, "error": "حسابك محظور. تواصل مع الإدارة"})

    login_attempt_record(ip, True)
    audit_log("login_success", username, {"ip": ip, "is_admin": user.get("role") == "admin"})
    token = _gen_token()
    is_admin = user.get("role") == "admin"
    db.web_sessions[token] = {
        "uid": user["uid"],
        "username": username,
        "telegram_id": user.get("telegram_id"),
        "role": "admin" if is_admin else "user",
        "name": user.get("name", username),
        "email": user.get("email", ""),
        "expires": time.time() + 86400 * 365
    }
    db.save()

    tg_id = user.get("telegram_id")
    effective_uid = tg_id if tg_id else user["uid"]
    balance = db.get_bal(effective_uid)

    return jsonify({
        "ok": True,
        "token": token,
        "user": {
            "uid": user["uid"],
            "username": username,
            "name": user.get("name", username),
            "email": user.get("email", ""),
            "role": "admin" if is_admin else "user",
            "balance": balance,
            "is_admin": is_admin,
            "api_key": user.get("api_key", ""),
        }
    })

