@app.route('/api/auth/change_password', methods=['POST'])
def api_auth_change_pass():

    data = freq.json or {}
    token = data.get('token', '')
    sess = web_auth_check(token)
    if not sess:
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    current = data.get('current_password', '')
    new_pass = data.get('new_password', '')

    if not current or not new_pass:
        return jsonify({"ok": False, "error": "يرجى ملء جميع الحقول"})
    if len(new_pass) < 6:
        return jsonify({"ok": False, "error": "كلمة المرور الجديدة يجب أن تكون 6 أحرف على الأقل"})

    users = _load_web_users()
    user = users.get(sess["username"])
    if not user or not _verify_pass(current, user.get("password", "")):
        return jsonify({"ok": False, "error": "كلمة المرور الحالية غير صحيحة"})

    user["password"] = _hash_pass(new_pass)
    _save_web_users(users)

    uname = sess["username"]
    to_remove = [t for t, s in db.web_sessions.items() if s.get("username") == uname and t != token]
    for t in to_remove:
        db.web_sessions.pop(t, None)
    if to_remove:
        db.save()
    audit_log("password_change", uname, {"ip": freq.remote_addr})
    return jsonify({"ok": True, "message": "تم تغيير كلمة المرور بنجاح"})

