@app.route('/api/auth/update_profile', methods=['POST'])
def api_auth_update_profile():

    data = freq.json or {}
    token = data.get('token', '')
    sess = web_auth_check(token)
    if not sess:
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    users = _load_web_users()
    user = users.get(sess["username"])
    if not user:
        return jsonify({"ok": False, "error": "user not found"})

    new_email = data.get('email', '').strip()
    new_name = data.get('name', '').strip()

    if new_email:
        user["email"] = new_email
        sess["email"] = new_email
    if new_name:
        user["name"] = new_name
        sess["name"] = new_name

    _save_web_users(users)
    return jsonify({"ok": True, "message": "تم التحديث"})

@app.route('/api/auth/forgot', methods=['POST'])
def api_auth_forgot():

    data = freq.json or {}
    username = data.get('username', '').strip().lower()

    users = _load_web_users()
    user = users.get(username)
    if not user:
        for uname, u in users.items():
            if u.get("email") == username:
                user = u
                username = uname
                break

    if not user:
        return jsonify({"ok": False, "error": "الحساب غير موجود"})

    otp = _gen_otp6()
    OTP_STORE[username] = {"otp": otp, "expires": time.time() + 300}

    sent_via = []

    tg_id = user.get("telegram_id")
    if tg_id:
        try:
            bot.send_message(tg_id, f"🔐 رمز استعادة كلمة المرور:\n\n<b>{otp}</b>\n\nينتهي خلال 5 دقائق", parse_mode="HTML")
            sent_via.append("تليجرام")
        except: pass

    email = user.get("email", "")
    if email:
        _send_reset_email_bg(email, user.get("name", username), otp)
        sent_via.append("الإيميل")

    if not sent_via:
        return jsonify({"ok": False, "error": "فشل الإرسال. تواصل مع الدعم"})

    masked_email = email[:2] + "***@" + email.split("@")[-1] if "@" in email else ""
    msg = "تم إرسال الرمز إلى " + " و".join(sent_via)
    return jsonify({"ok": True, "message": msg, "sent_via": sent_via, "email_masked": masked_email, "resolved_user": username})

@app.route('/api/auth/verify_otp', methods=['POST'])
def api_auth_verify_otp():

    data = freq.json or {}
    username = data.get('username', '').strip().lower()
    otp = data.get('otp', '').strip()

    stored = OTP_STORE.get(username)
    if not stored:
        users = _load_web_users()
        for uname, u in users.items():
            if u.get("email","").lower() == username:
                stored = OTP_STORE.get(uname)
                break
    if not stored:
        return jsonify({"ok": False, "error": "لم يتم إرسال رمز لهذا الحساب"})
    if time.time() > stored["expires"]:
        return jsonify({"ok": False, "error": "انتهت صلاحية الرمز"})
    if stored["otp"] != otp:
        return jsonify({"ok": False, "error": "الرمز غير صحيح"})

    return jsonify({"ok": True})

@app.route('/api/auth/reset_password', methods=['POST'])
def api_auth_reset_password():

    data = freq.json or {}
    username = data.get('username', '').strip().lower()
    otp = data.get('otp', '').strip()
    new_pass = data.get('new_password', '')

    actual_username = username
    stored = OTP_STORE.get(username)
    if not stored:

        users = _load_web_users()
        for uname, u in users.items():
            if u.get("email","").lower() == username:
                actual_username = uname
                stored = OTP_STORE.get(uname)
                break

    if not stored or stored.get("otp") != otp or time.time() > stored.get("expires", 0):
        return jsonify({"ok": False, "error": "رمز غير صالح"})
    if len(new_pass) < 6:
        return jsonify({"ok": False, "error": "كلمة المرور يجب أن تكون 6 أحرف على الأقل"})

    users = _load_web_users()
    if actual_username in users:
        users[actual_username]["password"] = _hash_pass(new_pass)
        _save_web_users(users)
        OTP_STORE.pop(actual_username, None)
        OTP_STORE.pop(username, None)
        return jsonify({"ok": True, "message": "تم تغيير كلمة المرور بنجاح"})
    return jsonify({"ok": False, "error": "الحساب غير موجود"})

@app.route('/api/auth/link_telegram', methods=['POST'])
def api_auth_link_telegram():

    data = freq.json or {}
    token = data.get('token', '')
    init_data = data.get('initData', '')

    sess = web_auth_check(token)
    if not sess:
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    tg_user = verify_telegram_data(init_data)
    if not tg_user:
        return jsonify({"ok": False, "error": "بيانات تليجرام غير صالحة"})

    users = _load_web_users()
    user = users.get(sess["username"])
    if user:
        user["telegram_id"] = tg_user["id"]
        user["name"] = tg_user.get("first_name", "") + " " + tg_user.get("last_name", "")
        _save_web_users(users)
        sess["telegram_id"] = tg_user["id"]
        db.add_subscriber(tg_user["id"])
        return jsonify({"ok": True, "message": "تم ربط حساب تليجرام"})
    return jsonify({"ok": False, "error": "حساب غير موجود"})

@app.route('/api/admin/users', methods=['POST'])
def api_admin_users():

    data = freq.json or {}
    token = data.get('token', '')
    sess = web_auth_check(token)
    if not sess or sess["role"] != "admin":

        user = get_auth_user(data)
        if not user or not user.get('is_admin'):
            return jsonify({"ok": False, "error": "unauthorized"}), 401

    users = _load_web_users()
    result = []
    for uname, u in users.items():
        tg_id = u.get("telegram_id")
        effective_uid = tg_id if tg_id else u.get("uid", uname)
        balance = db.get_bal(effective_uid)
        orders_count = len(db.get_orders(effective_uid))
        result.append({
            "username": uname,
            "name": u.get("name", uname),
            "beinty_id": u.get("beinty_id", ""),
            "email": u.get("email", ""),
            "role": u.get("role", "user"),
            "balance": balance,
            "orders": orders_count,
            "telegram_id": tg_id,
            "telegram_linked": bool(tg_id),
            "created": u.get("created", ""),
            "banned": u.get("banned", False),
            "ban_reason": u.get("ban_reason", ""),
            "ban_time": u.get("ban_time", ""),
            "ban_type": u.get("ban_type", ""),
            "last_ip": u.get("last_ip", ""),
            "last_device": u.get("last_device", ""),
            "last_active": u.get("last_active", ""),
        })
    result.sort(key=lambda x: x.get("created", ""), reverse=True)
    return jsonify({"ok": True, "users": result, "total": len(result)})

@bot.callback_query_handler(func=lambda c: c.data.startswith(("wrc_ok|", "wrc_no|")))
def cb_webapp_recharge(c):
    parts = c.data.split("|")
    ref = parts[1]
    bot.answer_callback_query(c.id)
    req = db.recharge_requests.get(ref)
    if not req:
        return bot.edit_message_text("طلب غير موجود", ADMIN_ID, c.message.message_id)
    if req.get("status") != "pending":
        return bot.edit_message_text(f"{'✅ تم الموافقة' if req['status']=='done' else '❌ تم الرفض'} مسبقاً", ADMIN_ID, c.message.message_id)
    uid = req["uid"]
    if parts[0] == "wrc_ok":
        usd = req["usd"]
        db.add_bal(uid, usd)
        req["status"] = "done"
        db.save()
        push_user_notif(uid, "system", "تم شحن رصيدك! ✅",
            f"+${usd:.2f} — الرصيد: ${db.get_bal(uid):.4f}", "wallet")
        try:
            bot.send_message(uid,
                f"✅ تم شحن رصيدك!\n\n"
                f"+${usd:.2f}\n"
                f"الرصيد الجديد: ${db.get_bal(uid):.4f}",
                reply_markup=main_kb(uid))
        except:
            pass
        bot.edit_message_text(f"✅ تم الموافقة: {uid} +${usd:.2f}\n{ref}", ADMIN_ID, c.message.message_id)
    else:
        req["status"] = "rejected"
        db.save()
        push_user_notif(uid, "system", "تم رفض طلب الشحن ❌",
            f"طلب {ref} — المبلغ: ${req.get('amount',0)}", "wallet")
        try:
            bot.send_message(uid, "❌ تم رفض طلب الشحن.", reply_markup=main_kb(uid))
        except:
            pass
        bot.edit_message_text(f"❌ رفض: {uid}\n{ref}", ADMIN_ID, c.message.message_id)

@bot.callback_query_handler(func=lambda c: c.data.startswith(("asia_ok|", "asia_no|")))
def cb_asiacell_recharge(c):
    parts = c.data.split("|")
    ref = parts[1]
    bot.answer_callback_query(c.id)

    req = db.asiacell_requests.get(ref)
    if not req:
        return bot.edit_message_text("طلب غير موجود", ADMIN_ID, c.message.message_id)

    uid = req["uid"]

    if parts[0] == "asia_ok":

        success, result = _asia_safe_credit(ref, source="manual")

        if not success:
            if result == "already_credited":
                return bot.edit_message_text(
                    f"⚠️ تم شحنه مسبقاً ({req.get('credit_source', 'auto')})\n{ref}",
                    ADMIN_ID, c.message.message_id)
            else:
                return bot.edit_message_text(
                    f"⚠️ فشل: {result}\n{ref}",
                    ADMIN_ID, c.message.message_id)

        usd = result

        push_user_notif(uid, "system", "تم شحن رصيدك! 📱",
            f"+${usd:.2f} عبر آسياسيل ({req['amount_iqd']:,} IQD)", "wallet")
        try:
            bot.send_message(uid,
                f"✅ تم شحن رصيدك!\n\n"
                f"+${usd:.2f} (آسياسيل)\n"
                f"الرصيد الجديد: ${db.get_bal(uid):.4f}",
                reply_markup=main_kb(uid))
        except Exception:
            pass
        bot.edit_message_text(
            f"✅ آسياسيل تأكيد: {uid} +${usd:.2f}\n{ref}",
            ADMIN_ID, c.message.message_id)
    else:

        with _asia_credit_lock:
            if req.get("status") == "credited":
                return bot.edit_message_text(
                    f"⚠️ لا يمكن الرفض — تم شحنه مسبقاً!\n{ref}",
                    ADMIN_ID, c.message.message_id)
            req["status"] = "rejected"
            db.save()

        push_user_notif(uid, "system", "تم رفض طلب شحن آسياسيل ❌",
            f"طلب {ref} — {req['amount_iqd']:,} IQD", "wallet")
        try:
            bot.send_message(uid, "❌ تم رفض طلب شحن آسياسيل.", reply_markup=main_kb(uid))
        except Exception:
            pass
        bot.edit_message_text(
            f"❌ رفض آسياسيل: {uid}\n{ref}",
            ADMIN_ID, c.message.message_id)

