def push_user_notif(uid, ntype, title, text, icon="bell"):

    notifs = db.user_notifications.setdefault(uid, [])
    notifs.insert(0, {
        "id": str(uuid.uuid4())[:8],
        "type": ntype,
        "title": title,
        "text": text,
        "icon": icon,
        "time": time.time(),
        "time_str": time.strftime("%d/%m %H:%M"),
        "read": False
    })
    if len(notifs) > 50:
        db.user_notifications[uid] = notifs[:50]
    db.save()

    sub = db.push_subs.get(uid) or db.push_subs.get(str(uid))
    try:
        sub = sub or db.push_subs.get(int(uid))
    except: pass
    if sub:
        threading.Thread(target=_send_push, args=(sub, title, text, '/app'), daemon=True).start()
    else:
        print(f"⚠️ Push: No subscription for uid={uid} (subs: {list(db.push_subs.keys())})")

