@app.route('/api/coupons', methods=['POST'])
def api_coupons():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False}), 401
    uid = user['id']
    now = time.time()
    available = []
    for code, c in db.coupons.items():
        if not c.get("active", True):
            continue
        if c.get("expires") and now > c["expires"]:
            continue
        if c.get("max_usage", 0) > 0 and c.get("used", 0) >= c["max_usage"]:
            continue
        if c.get("per_user", 0) > 0:
            user_used = sum(1 for u in c.get("used_by", []) if u == str(uid))
            if user_used >= c["per_user"]:
                continue
        available.append({
            "code": code,
            "type": c.get("type", "percent"),
            "value": c.get("value", 0),
            "min_order": c.get("min_order", 0),
            "expires": c.get("expires_str", ""),
        })
    return jsonify({"ok": True, "coupons": available})

@app.route('/api/coupons/apply', methods=['POST'])
def api_coupon_apply():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False}), 401
    uid = user['id']
    code = str(data.get("code", "")).strip().upper()
    amount = float(data.get("amount", 0))
    c = db.coupons.get(code)
    if not c or not c.get("active", True):
        return jsonify({"ok": False, "error": "كود غير صالح"})
    now = time.time()
    if c.get("expires") and now > c["expires"]:
        return jsonify({"ok": False, "error": "الكود منتهي"})
    if c.get("max_usage", 0) > 0 and c.get("used", 0) >= c["max_usage"]:
        return jsonify({"ok": False, "error": "الكود نفذ"})
    if c.get("per_user", 0) > 0:
        user_used = sum(1 for u in c.get("used_by", []) if u == str(uid))
        if user_used >= c["per_user"]:
            return jsonify({"ok": False, "error": "استخدمت هذا الكود مسبقاً"})
    if c.get("min_order", 0) > 0 and amount < c["min_order"]:
        return jsonify({"ok": False, "error": f"الحد الأدنى للطلب ${c['min_order']}"})
    if c.get("first_only") and db.order_count(uid) > 0:
        return jsonify({"ok": False, "error": "هذا الكود للطلب الأول فقط"})

    if c["type"] == "percent":
        discount = round(amount * c["value"] / 100, 4)
    elif c["type"] == "fixed":
        discount = min(c["value"], amount)
    elif c["type"] == "credit":
        db.add_bal(uid, c["value"])
        c.setdefault("used_by", []).append(str(uid))
        c["used"] = c.get("used", 0) + 1
        db.save()
        push_user_notif(uid, "promo", "تم إضافة رصيد!", f"كود {code} — +${c['value']}", "wallet")
        return jsonify({"ok": True, "type": "credit", "amount": c["value"], "balance": db.get_bal(uid)})
    else:
        discount = 0
    return jsonify({"ok": True, "type": c["type"], "discount": discount, "code": code})

