REFERRAL_COMMISSION = 5
REFERRAL_MIN_WITHDRAW = 1.0

def _get_referral(uid):

    uid_key = db._safe_key(uid)
    if uid_key not in db.referrals:
        code = "BNT" + str(uuid.uuid4())[:6].upper()
        db.referrals[uid_key] = {
            "code": code,
            "referred_by": None,
            "count": 0,
            "earnings": 0.0,
            "pending": 0.0,
            "history": [],
        }
        db.save()
    return db.referrals[uid_key]

@app.route('/api/referral', methods=['POST'])
def api_referral():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False}), 401
    uid = user['id']
    ref = _get_referral(uid)
    try:
        base = freq.url_root.rstrip('/')
        if not base or 'localhost' in base or '127.0.0.1' in base:
            base = WEBAPP_URL
    except Exception:
        base = WEBAPP_URL
    return jsonify({"ok": True, "referral": {
        "code": ref["code"],
        "count": ref["count"],
        "earnings": round(ref["earnings"], 2),
        "pending": round(ref.get("pending", 0), 2),
        "commission": REFERRAL_COMMISSION,
        "min_withdraw": REFERRAL_MIN_WITHDRAW,
        "link": f"{base}/app?ref={ref['code']}",
        "history": ref.get("history", [])[-10:],
    }})

@app.route('/api/referral/apply', methods=['POST'])
def api_referral_apply():

    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False}), 401
    uid = user['id']
    code = str(data.get("code", "")).strip().upper()
    my_ref = _get_referral(uid)
    if my_ref.get("referred_by"):
        return jsonify({"ok": False, "error": "لديك إحالة مسبقاً"})
    if my_ref["code"] == code:
        return jsonify({"ok": False, "error": "لا يمكنك إحالة نفسك"})

    referrer_uid = None
    for ruid, rdata in db.referrals.items():
        if rdata.get("code") == code:
            referrer_uid = ruid
            break
    if not referrer_uid:
        return jsonify({"ok": False, "error": "كود إحالة غير صالح"})
    my_ref["referred_by"] = str(referrer_uid)
    ref_data = db.referrals[referrer_uid]
    ref_data["count"] = ref_data.get("count", 0) + 1
    db.save()
    push_user_notif(referrer_uid, "system", "إحالة جديدة!", f"مستخدم جديد سجّل بكود إحالتك", "users")
    return jsonify({"ok": True})

@app.route('/api/referral/withdraw', methods=['POST'])
def api_referral_withdraw():
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False}), 401
    uid = user['id']
    ref = _get_referral(uid)
    pending = ref.get("pending", 0)
    if pending < REFERRAL_MIN_WITHDRAW:
        return jsonify({"ok": False, "error": f"الحد الأدنى للسحب ${REFERRAL_MIN_WITHDRAW}"})
    db.add_bal(uid, pending)
    ref["earnings"] = round(ref.get("earnings", 0) + pending, 4)
    ref["pending"] = 0
    db.save()
    push_user_notif(uid, "system", "تم سحب أرباح الإحالة!", f"+${pending:.2f} إلى رصيدك", "wallet")
    return jsonify({"ok": True, "amount": pending, "balance": db.get_bal(uid)})

