def _get_user_order_count(uid):
    """عدد الطلبات للمستخدم"""
    try:
        uid_key = db._safe_key(uid)
        count = len(db.orders.get(uid_key, [])) + len(db.orders.get(str(uid), []))
        for ck, cv in db.custom_orders.items():
            if str(cv.get("uid")) == str(uid):
                count += 1
        return count
    except:
        return 0

def _user_has_review(uid):
    """فحص إذا كان المستخدم عنده تقييم موجود"""
    for rv in db.reviews.values():
        if str(rv.get("uid")) == str(uid):
            return rv
    return None

@app.route('/api/reviews/list', methods=['GET', 'POST'])
def api_reviews_list():
    """جلب التقييمات المقبولة للعرض بالشريط المتحرك"""
    if not db.reviews_settings.get("enabled", True):
        return jsonify({"ok": True, "enabled": False, "reviews": [], "total": 0, "avg": 0})
    users = _web_users_ro()   # PERF FIX #6
    uid_avatar_map = {}
    for uname, u in users.items():
        if u.get("avatar"):
            tg_id = u.get("telegram_id")
            uid_val = u.get("uid")
            if tg_id:
                uid_avatar_map[str(tg_id)] = u["avatar"]
            if uid_val:
                uid_avatar_map[str(uid_val)] = u["avatar"]
    approved = []
    for rid, rv in db.reviews.items():
        if rv.get("status") == "approved":
            current_avatar = rv.get("avatar", "")
            uid_str = str(rv.get("uid", ""))
            if uid_str and uid_str != "admin_manual" and uid_str in uid_avatar_map:
                current_avatar = uid_avatar_map[uid_str]
            approved.append({
                "id": rid,
                "name": rv.get("name", "مستخدم"),
                "avatar": current_avatar,
                "stars": rv.get("stars", 5),
                "text": rv.get("text", ""),
                "verified": rv.get("verified", True),
                "created": rv.get("created", ""),
            })
    approved.sort(key=lambda x: x.get("created", ""), reverse=True)
    total = len(approved)
    avg = 0
    if total > 0:
        avg = round(sum(r["stars"] for r in approved) / total, 1)
    return jsonify({
        "ok": True,
        "enabled": True,
        "reviews": approved[:30],
        "total": total,
        "avg": avg,
        "speed": db.reviews_settings.get("strip_speed", 4),
    })

@app.route('/api/reviews/my', methods=['POST'])
def api_reviews_my():
    """جلب تقييم المستخدم الحالي"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    existing = _user_has_review(uid)
    order_count = _get_user_order_count(uid)
    min_orders = db.reviews_settings.get("min_orders", 3)
    can_submit = (order_count >= min_orders) and db.reviews_settings.get("allow_user_submit", True)
    return jsonify({
        "ok": True,
        "existing": existing,
        "can_submit": can_submit,
        "order_count": order_count,
        "min_orders": min_orders,
        "allow_submit": db.reviews_settings.get("allow_user_submit", True),
    })

@app.route('/api/reviews/submit', methods=['POST'])
def api_reviews_submit():
    """إرسال تقييم جديد من المستخدم"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    if not db.reviews_settings.get("allow_user_submit", True):
        return jsonify({"ok": False, "error": "التقييمات معطلة حالياً"})
    uid = user['id']
    min_orders = db.reviews_settings.get("min_orders", 3)
    order_count = _get_user_order_count(uid)
    if order_count < min_orders:
        return jsonify({"ok": False, "error": f"تحتاج {min_orders} طلبات على الأقل لإضافة تقييم"})
    existing = _user_has_review(uid)
    if existing:
        return jsonify({"ok": False, "error": "لديك تقييم بالفعل"})
    stars = int(data.get("stars", 5))
    text = (data.get("text", "") or "").strip()
    if stars < 1 or stars > 5:
        return jsonify({"ok": False, "error": "التقييم بين 1-5 نجوم"})
    if len(text) < 10:
        return jsonify({"ok": False, "error": "التعليق قصير جداً (10 حروف على الأقل)"})
    if len(text) > 500:
        return jsonify({"ok": False, "error": "التعليق طويل جداً (500 حرف كحد أقصى)"})
    users = _load_web_users()
    user_name = user.get('name', 'مستخدم')
    user_avatar = ""
    for uname, u in users.items():
        if str(u.get("uid", "")) == str(uid) or u.get("telegram_id") == uid:
            user_name = u.get("name", uname)
            user_avatar = u.get("avatar", "")
            break
    rid = uuid.uuid4().hex[:12]
    auto_approve = not db.reviews_settings.get("require_approval", True)
    db.reviews[rid] = {
        "id": rid,
        "uid": str(uid),
        "name": user_name,
        "avatar": user_avatar,
        "stars": stars,
        "text": text,
        "status": "approved" if auto_approve else "pending",
        "verified": True,
        "order_count": order_count,
        "created": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    db.save()
    try:
        if not auto_approve:
            bot.send_message(ADMIN_ID, f"⭐ تقييم جديد قيد المراجعة\n\n👤 {user_name}\n⭐ {stars}/5\n💬 {text[:100]}")
    except: pass
    msg = "تم نشر تقييمك، شكراً!" if auto_approve else "تم إرسال تقييمك، سيتم مراجعته قريباً"
    return jsonify({"ok": True, "message": msg, "status": db.reviews[rid]["status"]})

@app.route('/api/reviews/delete_mine', methods=['POST'])
def api_reviews_delete_mine():
    """حذف تقييم المستخدم"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user:
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    uid = user['id']
    existing = _user_has_review(uid)
    if not existing:
        return jsonify({"ok": False, "error": "ما عندك تقييم"})
    rid = existing.get("id")
    if rid in db.reviews:
        del db.reviews[rid]
        db.save()
    return jsonify({"ok": True, "message": "تم حذف التقييم"})


@app.route('/api/admin/reviews/list', methods=['POST'])
def api_admin_reviews_list():
    """قائمة كل التقييمات للأدمن"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    status_filter = data.get("status", "all")
    search = (data.get("search", "") or "").lower().strip()
    users = _load_web_users()
    uid_avatar_map = {}
    for uname, u in users.items():
        if u.get("avatar"):
            tg_id = u.get("telegram_id")
            uid_val = u.get("uid")
            if tg_id:
                uid_avatar_map[str(tg_id)] = u["avatar"]
            if uid_val:
                uid_avatar_map[str(uid_val)] = u["avatar"]
    items = []
    counts = {"all": 0, "pending": 0, "approved": 0, "rejected": 0}
    for rid, rv in db.reviews.items():
        st = rv.get("status", "pending")
        counts["all"] += 1
        counts[st] = counts.get(st, 0) + 1
        if status_filter != "all" and st != status_filter:
            continue
        if search and search not in rv.get("name", "").lower() and search not in rv.get("text", "").lower() and search not in str(rv.get("uid", "")):
            continue
        current_avatar = rv.get("avatar", "")
        uid_str = str(rv.get("uid", ""))
        if uid_str and uid_str != "admin_manual" and uid_str in uid_avatar_map:
            current_avatar = uid_avatar_map[uid_str]
        items.append({
            "id": rid,
            "uid": rv.get("uid", ""),
            "name": rv.get("name", ""),
            "avatar": current_avatar,
            "stars": rv.get("stars", 5),
            "text": rv.get("text", ""),
            "status": st,
            "order_count": rv.get("order_count", 0),
            "created": rv.get("created", ""),
        })
    items.sort(key=lambda x: x.get("created", ""), reverse=True)
    return jsonify({
        "ok": True,
        "reviews": items,
        "counts": counts,
        "settings": db.reviews_settings,
    })

@app.route('/api/admin/reviews/action', methods=['POST'])
def api_admin_reviews_action():
    """إجراءات على تقييم: approve, reject, delete"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    rid = data.get("id", "")
    action = data.get("action", "")
    if rid not in db.reviews:
        return jsonify({"ok": False, "error": "التقييم غير موجود"})
    if action == "approve":
        db.reviews[rid]["status"] = "approved"
    elif action == "reject":
        db.reviews[rid]["status"] = "rejected"
    elif action == "delete":
        del db.reviews[rid]
    else:
        return jsonify({"ok": False, "error": "إجراء غير معروف"})
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/reviews/add', methods=['POST'])
def api_admin_reviews_add():
    """إضافة تقييم يدوي من الأدمن (أو تعديل)"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    rid = data.get("id", "")
    name = (data.get("name", "") or "").strip()
    text = (data.get("text", "") or "").strip()
    stars = int(data.get("stars", 5))
    status = data.get("status", "approved")
    avatar = data.get("avatar", "")
    if not name or not text:
        return jsonify({"ok": False, "error": "الاسم والنص مطلوبان"})
    if stars < 1 or stars > 5:
        stars = 5
    if status not in ("approved", "pending", "rejected"):
        status = "approved"
    if rid and rid in db.reviews:
        db.reviews[rid].update({
            "name": name, "text": text, "stars": stars,
            "status": status, "avatar": avatar,
        })
    else:
        new_id = uuid.uuid4().hex[:12]
        db.reviews[new_id] = {
            "id": new_id,
            "uid": "admin_manual",
            "name": name,
            "avatar": avatar,
            "stars": stars,
            "text": text,
            "status": status,
            "verified": True,
            "order_count": 0,
            "created": time.strftime("%Y-%m-%d %H:%M:%S"),
            "manual": True,
        }
    db.save()
    return jsonify({"ok": True})

@app.route('/api/admin/reviews/settings', methods=['POST'])
def api_admin_reviews_settings():
    """تحديث إعدادات قسم التقييمات"""
    data = freq.json or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify({"ok": False}), 403
    key = data.get("key", "")
    value = data.get("value")
    allowed = ("enabled", "allow_user_submit", "require_approval", "min_orders", "strip_speed")
    if key not in allowed:
        return jsonify({"ok": False, "error": "مفتاح غير معروف"})
    if key in ("enabled", "allow_user_submit", "require_approval"):
        db.reviews_settings[key] = bool(value)
    elif key == "min_orders":
        try:
            v = int(value)
            db.reviews_settings[key] = max(0, min(100, v))
        except:
            return jsonify({"ok": False, "error": "قيمة غير صالحة"})
    elif key == "strip_speed":
        try:
            v = int(value)
            db.reviews_settings[key] = max(2, min(20, v))
        except:
            return jsonify({"ok": False, "error": "قيمة غير صالحة"})
    db.save()
    return jsonify({"ok": True, "settings": db.reviews_settings})

TUT_AUDIO_DIR = "tut_audio"
TUT_TEXTS = {
    "and": [
        "مرحبا! هسه راح نشرحلك شلون تنزل تطبيق بينتي وتفعل الإشعارات.",
        "افتح متصفح جوجل كروم واكتب بينتي دوت كوم. بعدين اضغط النقاط الثلاث.",
        "من القائمة اضغط إضافة إلى الشاشة الرئيسية.",
        "اضغط تثبيت.",
        "تمام! أيقونة بينتي على شاشتك. افتحها.",
        "هسه اضغط زر تفعيل على بانر الإشعارات.",
        "اضغط سماح على طلب الإذن.",
        "تمام! الإشعارات مفعلة. هيج شكلها لما توصلك.",
        "نصيحة: ألغِ تحسين البطارية لكروم. شكرا لاستخدامك بينتي!",
    ],
    "ios": [
        "مرحبا! نشرحلك تثبيت بينتي على آيفون. لازم تستخدم سفاري.",
        "اضغط زر المشاركة أسفل الشاشة.",
        "اختر إضافة إلى الشاشة الرئيسية ثم إضافة.",
        "مهم! افتح من أيقونة بينتي على الشاشة. مو سفاري.",
        "اضغط تفعيل ثم سماح.",
        "تمام! شكرا لاستخدامك بينتي!",
    ]
}

def generate_tut_audio():
    os.makedirs(TUT_AUDIO_DIR, exist_ok=True)
    generated = 0
    for platform, texts in TUT_TEXTS.items():
        for i, text in enumerate(texts):
            fpath = os.path.join(TUT_AUDIO_DIR, f"{platform}_{i}.mp3")
            if os.path.exists(fpath):
                continue
            try:
                resp = requests.post(
                    f"https://api.elevenlabs.io/v1/text-to-speech/{ELEVEN_VOICE}",
                    headers={"xi-api-key": ELEVEN_API_KEY, "Content-Type": "application/json"},
                    json={"text": text, "model_id": ELEVEN_MODEL,
                          "voice_settings": {"stability": 0.5, "similarity_boost": 0.75}},
                    timeout=30)
                if resp.status_code == 200:
                    with open(fpath, 'wb') as f:
                        f.write(resp.content)
                    generated += 1
                else:
                    print(f"[TTS] Error {resp.status_code} for {platform}_{i}")
            except Exception as e:
                print(f"[TTS] Exception: {e}")
    return generated

@app.route('/api/tut-audio/<fname>')
def serve_tut_audio(fname):
    fpath = os.path.join(TUT_AUDIO_DIR, fname)
    if os.path.exists(fpath):
        return send_file(fpath, mimetype='audio/mpeg')
    return '', 404

@app.route('/api/generate-tut-audio', methods=['POST'])
def api_generate_tut_audio():
    data = freq.get_json(force=True, silent=True) or {}
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify(ok=False, error='غير مصرح')
    count = generate_tut_audio()
    total = sum(len(v) for v in TUT_TEXTS.values())
    existing = sum(1 for p in ['and','ios'] for i in range(len(TUT_TEXTS[p])) if os.path.exists(os.path.join(TUT_AUDIO_DIR,f"{p}_{i}.mp3")))
    return jsonify(ok=True, generated=count, total=total, cached=existing)

@app.route('/')
def serve_landing():
    global _landing_gz
    if os.path.exists('landing.html'):
        if _landing_gz is None:

            with open('landing.html','r',encoding='utf-8') as f:
                html = f.read()
            html = _apply_site_name_to_html(html)
            html = _apply_contact_links_to_html(html)
            _landing_gz = _gzip.compress(html.encode('utf-8'), compresslevel=6)
        if 'gzip' in freq.headers.get('Accept-Encoding',''):
            resp = app.response_class(response=_landing_gz, status=200, mimetype='text/html')
            resp.headers['Content-Encoding'] = 'gzip'
            resp.headers['Cache-Control'] = 'public, max-age=300, stale-while-revalidate=60'
            resp.headers['Vary'] = 'Accept-Encoding'
            resp.headers['X-Content-Type-Options'] = 'nosniff'
            return resp

        try:
            html_text = _gzip.decompress(_landing_gz).decode('utf-8')
            resp = app.response_class(response=html_text, status=200, mimetype='text/html')
        except:

            with open('landing.html','r',encoding='utf-8') as f:
                html_text = f.read()
            html_text = _apply_site_name_to_html(html_text)
            html_text = _apply_contact_links_to_html(html_text)
            resp = app.response_class(response=html_text, status=200, mimetype='text/html')
        resp.headers['Cache-Control'] = 'public, max-age=300, stale-while-revalidate=60'
        return resp
    return send_file('webapp.html')

