@app.route('/sw.js')
def serve_sw():

    iv = int(getattr(db, 'pwa_icon_version', 1) or 1)
    nm = _site_name()
    cache_prefix = (nm.lower().replace(" ", "-") if nm else "site") or "site"
    sw_code = r'''
const ICON_VER = __IV__;
const CACHE_NAME = '__CP__-v' + ICON_VER + '-__BUILD__';
const OFFLINE_URL = '/app';
const ICON_192 = '/pwa-icon-192.png?v=' + ICON_VER;
const ICON_512 = '/pwa-icon-512.png?v=' + ICON_VER;
const PRECACHE = ['/app', ICON_192, ICON_512];

self.addEventListener('install', e => {
  self.skipWaiting();
  e.waitUntil(caches.open(CACHE_NAME).then(cache => cache.addAll(PRECACHE).catch(()=>{})));
});

self.addEventListener('activate', e => {
  e.waitUntil(Promise.all([
    caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)))),
    self.clients.claim()
  ]));
});

// PERF FIX #14 — أصول immutable (/s/<hash>/app.js|css): كاش-أولاً.
// ما نحتاج نسأل السيرفر عنها أبداً لأن الرابط يتغيّر عند أي تحديث.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  const url = new URL(e.request.url);
  if (url.pathname.startsWith('/api/')) return;
  if (url.origin !== self.location.origin) return;

  if (url.pathname.startsWith('/s/')) {
    e.respondWith(
      caches.match(e.request).then(hit => hit || fetch(e.request).then(r => {
        if (r.ok) { const c = r.clone(); caches.open(CACHE_NAME).then(ch => ch.put(e.request, c)); }
        return r;
      }))
    );
    return;
  }

  // أيقونة PWA: شبكة-أولاً مع cache بستراتيجية stale-while-revalidate
  if (url.pathname === '/pwa-icon-192.png' || url.pathname === '/pwa-icon-512.png') {
    e.respondWith(
      fetch(e.request).then(r => {
        if (r.ok) {
          const clone = r.clone();
          caches.open(CACHE_NAME).then(c => c.put(e.request, clone));
        }
        return r;
      }).catch(() => caches.match(e.request))
    );
    return;
  }

  // PERF FIX #15 — /app: كاش-أولاً + مهلة شبكة.
  // قبل: لو ما كو نسخة بالكاش، الـSW ينتظر السيرفر بلا مهلة أبداً →
  // إذا السيرفر بطيء (وهو كان بطيء بسبب /api/services) المستخدم يشوف
  // صفحة بيضاء لين ما يرد. الآن: مهلة 6 ثواني ثم رجوع لأي نسخة مخزّنة.
  if (url.pathname === '/app' || url.pathname === '/app/') {
    e.respondWith(
      caches.open(CACHE_NAME).then(cache =>
        cache.match(e.request).then(cached => {
          const fetchP = fetch(e.request).then(r => {
            if (r.ok) cache.put(e.request, r.clone());
            return r;
          }).catch(() => cached);
          if (cached) { fetchP.catch(()=>{}); return cached; }
          return Promise.race([
            fetchP,
            new Promise(res => setTimeout(() => res(null), 6000))
          ]).then(r => r || cache.match(OFFLINE_URL).then(o => o || fetchP));
        })
      )
    );
    return;
  }

  e.respondWith(
    fetch(e.request).then(r => {
      if (r.ok) {
        const clone = r.clone();
        caches.open(CACHE_NAME).then(c => c.put(e.request, clone));
      }
      return r;
    }).catch(() => caches.match(e.request).then(r => r || caches.match(OFFLINE_URL)))
  );
});

self.addEventListener('push', e => {
  let data = {title: '', body: 'لديك إشعار جديد', icon: ICON_192};
  try { data = e.data.json(); } catch(err) {}
  const options = {
    body: data.body || '',
    icon: data.icon || ICON_192,
    badge: ICON_192,
    vibrate: [100, 50, 100],
    dir: 'rtl',
    lang: 'ar',
    tag: data.tag || 'site-notif',
    renotify: true,
    data: { url: data.url || '/app' },
    actions: data.actions || []
  };
  e.waitUntil(self.registration.showNotification(data.title || '', options));
});

self.addEventListener('notificationclick', e => {
  e.notification.close();
  const url = e.notification.data?.url || '/app';
  e.waitUntil(
    clients.matchAll({type: 'window', includeUncontrolled: true}).then(list => {
      for (const c of list) {
        if (c.url.includes('/app') && 'focus' in c) return c.focus();
      }
      return clients.openWindow(url);
    })
  );
});

// رسالة من الصفحة الرئيسية لتفعيل التحديث الفوري
self.addEventListener('message', e => {
  if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting();
  if (e.data && e.data.type === 'CLEAR_CACHE') {
    e.waitUntil(caches.keys().then(keys => Promise.all(keys.map(k => caches.delete(k)))));
  }
});
'''
    sw_code = sw_code.replace('__IV__', str(iv)).replace('__CP__', cache_prefix).replace('__BUILD__', _BUILD_ID)
    resp = make_response(sw_code.strip())
    resp.headers['Content-Type'] = 'application/javascript'
    resp.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
    resp.headers['Service-Worker-Allowed'] = '/'
    return resp

@app.route('/pwa-icon-192.png')
@app.route('/pwa-icon-512.png')
def serve_pwa_icon():

    iv = int(getattr(db, 'pwa_icon_version', 1) or 1)
    etag = f'"pwa-{iv}-{("c" if db.pwa_icon else "d")}"'
    inm = freq.headers.get('If-None-Match', '')
    if inm == etag:
        resp = make_response('', 304)
        resp.headers['ETag'] = etag
        resp.headers['Cache-Control'] = 'public, max-age=300, must-revalidate'
        return resp

    if db.pwa_icon and db.pwa_icon.startswith("data:image/"):
        try:
            import base64 as _b64
            header, b64data = db.pwa_icon.split(",", 1)
            img_bytes = _b64.b64decode(b64data)

            mime = "image/png"
            if "jpeg" in header or "jpg" in header: mime = "image/jpeg"
            elif "webp" in header: mime = "image/webp"
            resp = make_response(img_bytes)
            resp.headers['Content-Type'] = mime
            resp.headers['Cache-Control'] = 'public, max-age=300, must-revalidate'
            resp.headers['ETag'] = etag
            return resp
        except:
            pass

    size = 512 if '512' in freq.path else 192
    s = size
    r = int(s * 0.22)

    lw = int(s * 0.55)
    lh = int(s * 0.55)
    lr = int(s * 0.125)
    cx = s // 2
    cy = s // 2
    fs = int(s * 0.28)

    first_letter = (_site_name()[0:1] or "B").upper()
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="{s}" height="{s}" viewBox="0 0 {s} {s}">
    <defs>
      <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#fafcff"/><stop offset="100%" stop-color="#eef3fa"/></linearGradient>
      <linearGradient id="fg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#4a90d9"/><stop offset="100%" stop-color="#2563eb"/></linearGradient>
    </defs>
    <rect width="{s}" height="{s}" rx="{r}" fill="url(#bg)"/>
    <g transform="translate({cx},{cy})">
      <rect x="{-lw//2}" y="{-lh//2}" width="{lw}" height="{lh}" rx="{lr}" fill="#d4e2f2" opacity="0.45" transform="rotate(-15)"/>
      <rect x="{-lw//2}" y="{-lh//2}" width="{lw}" height="{lh}" rx="{lr}" fill="#a8c8e4" opacity="0.6" transform="rotate(-8)"/>
      <rect x="{-lw//2}" y="{-lh//2}" width="{lw}" height="{lh}" rx="{lr}" fill="url(#fg)" transform="rotate(0)"/>
    </g>
    <text x="{cx}" y="{cy + fs//3}" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-size="{fs}" font-weight="700" fill="#fff">{first_letter}</text>
    </svg>'''
    try:
        import cairosvg
        png = cairosvg.svg2png(bytestring=svg.encode(), output_width=size, output_height=size)
    except:
        resp = make_response(svg)
        resp.headers['Content-Type'] = 'image/svg+xml'
        return resp
    resp = make_response(png)
    resp.headers['Content-Type'] = 'image/png'
    resp.headers['Cache-Control'] = 'public, max-age=300, must-revalidate'
    resp.headers['ETag'] = etag
    return resp

