@app.route('/api/admin/push/send', methods=['POST'])
def api_admin_push_send():

    data = freq.get_json(silent=True) or {}
    token = data.get('token','')
    user = get_auth_user(data)
    if not user or not user.get('is_admin'):
        return jsonify(ok=False, error='unauthorized')
    target = data.get('target', 'all')
    title = data.get('title', 'Beinty')
    body = data.get('body', '')
    url = data.get('url', '/app')
    if not body:
        return jsonify(ok=False, error='body required')
    subs = db.push_subs
    sent = 0
    if target == 'all':
        for uid, sub in list(subs.items()):
            if _send_push(sub, title, body, url):
                sent += 1
    else:
        sub = subs.get(target)
        if sub and _send_push(sub, title, body, url):
            sent = 1
    return jsonify(ok=True, sent=sent)

def _send_push(subscription, title, body, url='/app'):

    if not subscription or not db.vapid_private:
        print("⚠️ Push: Missing subscription or VAPID key")
        return False
    try:
        from pywebpush import webpush
    except ImportError:
        print("⚠️ pywebpush not installed! Run: pip install pywebpush")
        return False
    try:
        import jwt as pyjwt
        from cryptography.hazmat.primitives.serialization import load_pem_private_key
        import base64, urllib.parse

        endpoint = subscription.get('endpoint','') if isinstance(subscription, dict) else ''
        parsed = urllib.parse.urlparse(endpoint)
        aud = f"{parsed.scheme}://{parsed.netloc}"
        now = int(time.time())
        payload_jwt = {
            "aud": aud,
            "exp": now + 43200,
            "sub": f"mailto:{ADMIN_EMAIL}"
        }
        priv_key = load_pem_private_key(db.vapid_private.encode(), password=None)
        token = pyjwt.encode(payload_jwt, priv_key, algorithm="ES256")

        pub_numbers = priv_key.public_key().public_numbers()
        x = pub_numbers.x.to_bytes(32, 'big')
        y = pub_numbers.y.to_bytes(32, 'big')
        pub_uncompressed = b'\x04' + x + y
        pub_b64 = base64.urlsafe_b64encode(pub_uncompressed).rstrip(b'=').decode()
        vapid_headers = {
            "Authorization": f"vapid t={token},k={pub_b64}"
        }
        push_payload = json.dumps({
            'title': title, 'body': body,
            'icon': '/pwa-icon-192.png', 'url': url,
            'tag': 'beinty-' + str(now)
        })
        webpush(subscription, push_payload, headers=vapid_headers)
        print(f"✅ Push sent: {title}")
        return True
    except ImportError:

        try:
            push_payload = json.dumps({
                'title': title, 'body': body,
                'icon': '/pwa-icon-192.png', 'url': url,
                'tag': 'beinty-' + str(int(time.time()))
            })
            webpush(subscription, push_payload,
                vapid_private_key=db.vapid_private,
                vapid_claims={"sub": f"mailto:{ADMIN_EMAIL}"}
            )
            print(f"✅ Push sent (fallback): {title}")
            return True
        except Exception as e2:
            err2 = str(e2)
            print(f"❌ Push fallback error: {e2}")
            if '400' in err2 or '403' in err2 or '410' in err2 or 'Gone' in err2 or 'Forbidden' in err2:
                for uid, sub in list(db.push_subs.items()):
                    if sub == subscription:
                        db.push_subs.pop(uid, None); db.save()
                        print(f"🗑️ Removed invalid push sub (fallback): {uid}")
                        break
            return False
    except Exception as e:
        err = str(e)
        print(f"❌ Push error: {type(e).__name__}: {err}")

        if '400' in err or '403' in err or '410' in err or 'Gone' in err or 'Forbidden' in err or 'Bad Request' in err:
            for uid, sub in list(db.push_subs.items()):
                if sub == subscription:
                    db.push_subs.pop(uid, None); db.save()
                    print(f"🗑️ Removed invalid push sub: {uid} (reason: {err[:60]})")
                    break
        return False

def _generate_vapid_keys():

    try:
        from cryptography.hazmat.primitives.asymmetric import ec
        from cryptography.hazmat.primitives import serialization
        import base64

        private_key = ec.generate_private_key(ec.SECP256R1())

        private_pem = private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.PKCS8,
            encryption_algorithm=serialization.NoEncryption()
        ).decode()

        public_numbers = private_key.public_key().public_numbers()
        x = public_numbers.x.to_bytes(32, 'big')
        y = public_numbers.y.to_bytes(32, 'big')
        public_uncompressed = b'\x04' + x + y
        public_b64 = base64.urlsafe_b64encode(public_uncompressed).rstrip(b'=').decode()
        db.vapid_private = private_pem
        db.vapid_public = public_b64
        db.save()
        print("✅ VAPID keys generated for Push Notifications")
    except Exception as e:
        print(f"⚠️ Failed to generate VAPID keys: {e}")
        print("   Install: pip install pywebpush cryptography")

