@app.route('/api/push/test', methods=['POST','GET'])
def api_push_test():

    if not db.push_subs:
        return jsonify(ok=False, error='no_subscribers', msg='لا يوجد مشتركين — فعّل الإشعارات من الموقع أولاً')
    sent = 0
    failed = []
    for uid, sub in list(db.push_subs.items()):
        result = _send_push(sub, '🔔 اختبار Beinty', 'هذا إشعار تجريبي — الإشعارات تشتغل! ✅', '/app')
        if result:
            sent += 1
        else:
            failed.append(uid)

    for uid in failed:
        db.push_subs.pop(uid, None)
    if failed:
        db.save()
    return jsonify(ok=sent > 0, sent=sent, failed=len(failed), subscribers=len(db.push_subs))

