  h+='<div style="font-size:.52rem;font-weight:700;color:var(--t3);margin-bottom:4px"><i class="fas fa-hashtag"></i> \u0631\u0642\u0645 \u0627\u0644\u062e\u062f\u0645\u0629 (Service ID)</div>';
  h+='<div style="display:flex;gap:6px"><input class="inp" id="recSvcIdInp" type="number" placeholder="\u0645\u062b\u0627\u0644: 1234" oninput="searchRecSvc()"><button onclick="searchRecSvc()" style="padding:8px 14px;background:var(--acSh);border:1px solid var(--ac);border-radius:10px;color:var(--ac);font-size:.55rem;font-weight:700;cursor:pointer;flex-shrink:0;font-family:inherit"><i class="fas fa-search"></i> \u0628\u062d\u062b</button></div>';
