  h+='<button onclick="document.getElementById(\'recAddFormArea\').innerHTML=\'\'" style="width:100%;padding:8px;margin-top:4px;border:1px solid var(--bd);border-radius:10px;background:transparent;color:var(--t3);font-family:inherit;font-size:.52rem;font-weight:700;cursor:pointer"><i class="fas fa-times"></i> \u0625\u0644\u063a\u0627\u0621</button>';
