@bot.message_handler(func=lambda m: m.chat.id == ADMIN_ID and S(m.chat.id).get("step") == "tk_admin_reply")
def h_tk_admin_reply(m):
    tid = S(m.chat.id).get("tk_id")
    S_clear(m.chat.id)
    tickets = db.tickets
    t = tickets.get(tid)
    if not t:
        bot.send_message(m.chat.id, "❌ التذكرة غير موجودة")
        return
    now = time.strftime("%d/%m %H:%M")
    t["messages"].append({"from": "admin", "text": m.text, "time": now})
    t["status"] = "replied"
    db.save()
    bot.send_message(m.chat.id, f"✅ تم الرد على تذكرة #TK-{tid}")

    try:
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("🌐 فتح المتجر", web_app=types.WebAppInfo(url=WEBAPP_URL)))
        bot.send_message(t["uid"], f"💬 رد جديد على تذكرتك #TK-{tid}!\n\n{m.text}", reply_markup=kb)
    except: pass

