@bot.message_handler(func=lambda m: S(m.chat.id).get("step") == "track_input")
def h_track(m):
    uid, txt = m.chat.id, m.text.strip()
    if txt in ("إلغاء", "الغاء", "cancel"):
        S_clear(uid)
        return bot.send_message(uid, "تم الإلغاء.", reply_markup=main_kb(uid))
    o = next((x for x in db.get_orders(uid) if str(x["order"]) == txt), None)
    rec = _status_for_order(o) if o else api_call(action="status", order=txt)
    status = rec.get("status", "غير معروف").lower()
    sa = {"completed": "✅ مكتمل", "processing": "قيد التنفيذ", "pending": "🕐 انتظار",
          "in progress": "قيد التنفيذ", "partial": "⚠️ جزئي", "canceled": "❌ ملغي"}.get(status, f"❓ {status}")
    refill = int(rec.get("refill", 0))
    info = f"تفاصيل الطلب\n\nالرقم: {txt}\n"
    if o:
        info += f"الخدمة: {o.get('service','—')}\nالرابط: {o.get('link','—')}\nالكمية: {o.get('qty','—')}\nالتكلفة: ${o.get('cost',0):.4f}\n"
    info += f"الحالة: {sa}\nالضمان: {refill} يوم"
    kb = types.InlineKeyboardMarkup()
    if status == "completed" and refill > 0 and o:
        placed = time.mktime(time.strptime(o["timestamp"], "%Y-%m-%d %H:%M:%S"))
        if (time.time() - placed) / 3600 >= 24:
            kb.add(types.InlineKeyboardButton("♻️ طلب تعويض", callback_data=f"rf|{txt}"))
    kb.add(types.InlineKeyboardButton("📦 فحص طلب آخر", callback_data="track"))
    kb.add(types.InlineKeyboardButton("🏠 الرئيسية", callback_data="home"))
    S_clear(uid)
    bot.send_message(uid, info, reply_markup=kb)

@bot.callback_query_handler(func=lambda c: c.data.startswith("od|"))
def cb_od(c):
    oid = c.data.split("|", 1)[1]
