def _show_funds(uid):
    S_set(uid, step="recharge_method")
    kb = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=2)
    methods = list(db.payment_methods.keys())
    for i in range(0, len(methods), 2):
        if i + 1 < len(methods):
            kb.row(methods[i], methods[i+1])
        else:
            kb.row(methods[i])
    kb.row("❌ إلغاء")
    bot.send_message(uid, f"شحن الرصيد\n\nرصيدك: ${db.get_bal(uid):.4f}\n\nاختر طريقة الدفع:", reply_markup=kb)

