@bot.callback_query_handler(func=lambda c: c.data.startswith(("rc_ok|", "rc_no|")))
def cb_rc(c):
    parts = c.data.split("|")
    bot.answer_callback_query(c.id)
    if parts[0] == "rc_ok":
        uid, method, amt = int(parts[1]), parts[2], float(parts[3])
        pm = db.payment_methods.get(method, {"rate": 1})
        usd = round(amt / pm["rate"], 2)
        db.add_bal(uid, usd)
        try:
            bot.send_message(uid, f"تم الشحن!\n+${usd:.2f}\nالرصيد: ${db.get_bal(uid):.4f}", reply_markup=main_kb(uid))
        except Exception: pass
        bot.edit_message_text(f"✅ موافقة: {uid} +${usd:.2f}", ADMIN_ID, c.message.message_id)
    else:
        uid = int(parts[1])
        try:
            bot.send_message(uid, "تم رفض طلب الشحن.", reply_markup=main_kb(uid))
        except Exception: pass
        bot.edit_message_text(f"❌ رفض: {uid}", ADMIN_ID, c.message.message_id)

